import{b as o}from"./driveTimes-Bijzi9KU.js";const e={protocols:{name:"SACAA Summarised Medical Protocols in line with Part 67 (effective 16 November 2021), item 52",url:"https://caasanwebsitestorage.blob.core.windows.net/avmed-amended-protocols/Summarised%20Medical%20Protocols%20in%20line%20with%20Part%2067%20of%20the%20Civil%20Aviation%20Regulations%20and%20Technical%20Standards.pdf"},classes:{name:"SACAA: amended Part 67 regulation 67.00.2, classes of medical certificates",url:"https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-general-information/Ammended%20%20Part%2067%20Regulations%20Classes%20of%20medical%20certificates.pdf"},application:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.7 (Application for medical certificates)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_7_application.php"},class4:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.5 (Class 4 medical certificates)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_5_class_4_med.php"},cabin:{name:"Civil Aviation Regulations, 2011, Part 64, regulation 64.01.6 (Cabin crew medical fitness)",url:"https://source.acts.co.za/civil-aviation-act-2009/nr425_64_01_6_medical_fit.php"},am007:{name:"SACAA procedure AM007: issuing of Class I, II, III and IV medical certificates (reissued 15 September 2025)",url:"https://caasanwebsitestorage.blob.core.windows.net/shared-documents/AM007%20Issuing%20of%20a%20class%20IIIIII%20and%20IV%20medical%20certificate.pdf"},avmed:{name:"SACAA Aviation Medicine page",url:"https://www.caa.co.za/industry-information/aviation-medicine/"},faq:{name:"SACAA Frequently Asked Questions (medical classes and validity periods, Class 4 for cabin crew, who may examine, extensions)",url:"https://www.caa.co.za/information-for-the-public/frequently-asked-questions/"},register:{name:"SACAA list of Regular Designated Aviation Medical Examiners (Dr AO Ndhlovu, MR 336)",url:"https://caasanwebsitestorage.blob.core.windows.net/shared-documents/Regular%20DAMES.pdf"},form:{name:"SACAA form CA 67-02(a), Aviation Medical Report",url:"https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-forms-and-checklist/CA%2067-02%28a%29.pdf"},classesReg:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.2 (Classes of medical certificates)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_2_classes_of_.php"},designation:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.4 (Designation of aviation medical examiners)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_4_designation.php"},validityReg:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.6 (Period of validity and extensions)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_6_period_of_v.php"},issuing:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.8 (Issuing of medical certificate)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_8_issuing_of_.php"},duties:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.9 (Duties of holder of medical certificate)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_9_duties_of_h.php"},records:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.12 (Period of validity of medical records)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_12_period_of_.php"},suspension:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.14 (Suspension or cancellation of medical certificate)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_14_suspension.php"},spl:{name:"Civil Aviation Regulations, 2011, Part 61, regulation 61.02.1 (Requirements for SPL or ISPL, as amended 21 August 2026)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_61_02_1_requirements.php"},substance:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.13 (Substance abuse)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_13_substance_.php"},validation:{name:"Civil Aviation Regulations, 2011, Part 67, regulation 67.00.10 (Validations of foreign medical reports)",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_67_00_10_validation.php"},sacats67:{name:"SA-CATS 67 Medical certification (in the SACAA SA-CATS 2011 document), ear, nose and throat and hearing standards for Classes 1 to 4",url:"https://caasanwebsitestorage.blob.core.windows.net/legal-documents/SA-CATS%201-2011.pdf"},damesGuide:{name:"SACAA Guide for Medical Examiners (DAMEs Guide, revision March 2023), ear, nose and throat and hearing standards",url:"https://caasanwebsitestorage.blob.core.windows.net/shared-documents/Dames%20Guide.pdf"},class4Standards:{name:"SACAA Aviation Medicine workshop presentation: Class IV Medical Standards (April 2024), respiratory and asthma, and the ENT system",url:"https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-workshop-presentations/Class%20IV%20Medical%20Standards%20-%20Sr%20Tshepo%20Masole.pdf"},audiologyChecklist:{name:"SACAA form CA 67-30, Audiology Consultation Report Checklist (15 September 2025)",url:"https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-forms-and-checklist/CA%2067-30.pdf"},audiology:{name:"SACAA Aviation Medicine workshop presentation: Audiology and Aviation, Mrs Anel Louw (6 April 2022)",url:"https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-workshop-presentations/Audiology%20and%20Aviation%20-%20Mrs%20Anel%20Louw%206%20April%202022.pdf"},damesEcg:{name:"SACAA Guide for Medical Examiners (DAMEs Guide, revision March 2023), Electrocardiography: resting ECG intervals for Classes 1 to 3, procedure, interpretation and stress ECG indications",url:"https://caasanwebsitestorage.blob.core.windows.net/shared-documents/Dames%20Guide.pdf"},damesClass4:{name:"SACAA Guide for Medical Examiners (DAMEs Guide, revision March 2023), 4.1.18 Class IV medical certificates, cardiovascular system (resting ECG)",url:"https://caasanwebsitestorage.blob.core.windows.net/shared-documents/Dames%20Guide.pdf"},ecgProtocol:{name:"SA-CATS 67 Schedule 44, Protocol for cardiac conduction and rhythm disorders, 7.1 Abnormal ECG tracing (inserted by SA-CATS 2/2023, in force 17 March 2023)",url:"https://caasanwebsitestorage.blob.core.windows.net/avmed-amended-protocols/Cardiac%20Conduction%20and%20Rhythm%20Disorders%20Protocol.pdf"},cardiology:{name:"SACAA Aviation Medicine workshop presentation: Aviation Cardiology, Prof Andrew Sarkin (resting and exercise ECG)",url:"https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-workshop-presentations/Aviation%20Cardiology%20-%20Prof%20Andrew%20Sarkin.pdf"},class4Ecg:{name:"SACAA Aviation Medicine workshop presentation: Class IV Medical Standards, cardiovascular (resting ECG schedule)",url:"https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-workshop-presentations/Class%20IV%20Medical%20Standards%20-%20Sr%20Tshepo%20Masole.pdf"}},s={slug:"renew-sacaa-class-2-medical",title:"Class 2 Medical Renewal, Step by Step | ClinoTrend",h1:"How to renew your SACAA Class 2 medical, step by step",description:"Renew a SACAA Class 2 medical in South Africa: when to book, which examiner, what to bring, what happens on the day, and how to apply for a 30 day extension.",excerpt:"When to book, which examiner can renew it, what to bring, what happens on the day, and what to do if your certificate is about to expire.",keyword:"class 2 medical renewal",question:"How do I renew my SACAA Class 2 medical?",answer:"Check the expiry date on your certificate, then book a SACAA Designated Aviation Medical Examiner a few weeks before it. Bring your ID, licence, current certificate, logbook and a list of your medicines. If you meet the standards, the certificate can be issued on the day. Apply to SACAA for an extension at least 15 days before expiry if needed.",facts:["Under Part 67, a Class 2 certificate is valid for 60 months if you are less than 40, 24 months after your 40th birthday, and 12 months after your 50th birthday.","Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book.","Dr A.O. Ndhlovu, SACAA Regular DAME MR 336, does Class 2 renewals at Grand Central Airport, Midrand."],secondary:["sacaa class 2 medical certificate","class 2 medical certificate south africa","sacaa medical extension","sacaa medical examiners"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Renewals",body:[{t:"p",x:"If you fly on a student pilot licence (SPL) or a private pilot licence (PPL), your licence is only valid while you hold a current Class 2 medical certificate. Renewing it is routine, but a little planning avoids a gap in flying. This guide walks through the renewal in the order you will meet each step, with the South African Civil Aviation Regulations (Part 67) quoted where it matters."},{t:"h2",x:"Who needs a Class 2 medical?",id:"who"},{t:"p",x:"Under the amended regulation 67.00.2 of Part 67, a Class 2 medical certificate covers, among others, the SPL, the PPL for aeroplane, airship and helicopter, the flight engineer licence, the free balloon commercial pilot licence and the commercial glider pilot. The same regulation says that a pilot holding a valid Class 1 certificate is deemed to hold a valid Class 2 and Class 4 certificate."},{t:"p",x:"Cabin crew may need a Class 2 or a Class 4 medical, depending on what the airline or operator asks for. If you are cabin crew, read our guide to [cabin crew medical requirements](/blog/cabin-crew-medical-class-4-south-africa/)."},{t:"h2",x:"How do I check my expiry date?",id:"expiry"},{t:"p",x:"Look at the expiry date printed on your current certificate. Certificates run to the **last day of a month**. Under Part 67, regulation 67.00.6(3), a Class 2 certificate is valid for:"},{t:"ul",items:["60 months, if the holder is less than 40 years of age","24 months, once the holder has passed their 40th birthday","12 months, once the holder has passed their 50th birthday"]},{t:"p",x:"Older SACAA FAQ pages show shorter Class 2 periods. This practice follows the regulation. Medical conditions can mean a shorter period, so the date on your certificate is the one that counts. [How long is a Class 2 medical valid?](/blog/class-2-medical-validity-by-age/) explains how the date is counted and has a small expiry calculator."},{t:"h2",x:"How do I book with a designated examiner?",id:"examiner"},{t:"p",x:"A Class 2 renewal must be done by a Designated Aviation Medical Examiner (DAME). SACAA designates two kinds. Regular DAMEs may examine for and issue Class II and Class IV certificates. Senior DAMEs may also do Class I and Class III. Your family GP cannot issue a Class 2 certificate unless he or she is designated. Our guide to [SACAA medical examiners](/blog/sacaa-medical-examiners-dame/) shows how to check an examiner on the SACAA list."},{t:"p",x:"SACAA publishes the lists of Regular and Senior DAMEs on its aviation medicine page. It is worth checking that your examiner is on the current list."},{t:"p",x:"Dr A.O. Ndhlovu is listed by SACAA as a Regular DAME, number MR 336, at Grand Central Airport, Gate 2, Midrand. Class 2 renewals are within his scope. ClinoTrend does not currently issue Class 1."},{t:"h3",x:"When to book"},{t:"p",x:"Book a few weeks before your expiry date. That leaves time to get a specialist letter or an extra test if the examiner asks for one, without being grounded while you wait. Keep in mind that the new certificate runs from the month it is issued, so renewing many months early does not add the unused time to the new certificate."},{t:"h2",x:"What should I bring?",id:"documents"},{t:"p",x:"Regulation 67.00.7 says that when you attend the examination you must show proof of identity, show your licence and your latest medical certificate if you hold one, give the examiner information about your medical history, and sign a declaration that the information on the examination form is accurate, complete and true. In practice, bring:"},{t:"ul",items:["Your South African ID, driving licence or passport","Your pilot licence and your current medical certificate","Your logbook","A list of every medicine you take, including over the counter medicines","Glasses, contact lenses or hearing aids, if you use them","Recent reports from your doctor or specialist if you have a medical condition"]},{t:"p",x:"Complete the SACAA application form for a medical certificate online before you arrive. It is emailed only to the practice. The [Aviation Medical Report form, CA 67-02(a)](https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-forms-and-checklist/CA%2067-02%28a%29.pdf) is completed on the day."},{t:"h2",x:"What happens at the examination?",id:"examination"},{t:"p",x:"The examiner takes your medical history and examines you. At ClinoTrend a resting ECG, vision testing, a hearing test (audiometry) and urine screening are done on site. The examiner will tell you which other tests apply, including whether a chest X-ray or any further tests are needed, and whether they are done on site or referred. Ask the practice how long to allow when you book."},{t:"p",x:"Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book."},{t:"h2",x:"When do I receive my certificate?",id:"certificate"},{t:"p",x:"If you meet the standards and no further reports are needed, the certificate can be issued at the end of the examination. SACAA procedure AM007 describes two copies with the same serial number: the yellow copy goes to the SACAA licensing department and you keep the white copy with you while flying. Medical restrictions, if any apply, are written on the certificate."},{t:"p",x:"If more information is needed, your assessment is deferred until it arrives. Complicated cases are referred to the SACAA Aeromedical Committee, which AM007 says meets on the third Tuesday of each month, with documents due seven days before the meeting. If you disagree with a decision, Part 67 allows an appeal to the Director of Civil Aviation within 30 days. Read [what happens if a medical is deferred](/blog/aviation-medical-deferred-what-next/) for the full process."},{t:"h2",x:"What if I am running out of time?",id:"extension"},{t:"p",x:"Part 67, regulation 67.00.6(6), says you must apply for an extension **at least 15 days before your certificate expires**, and that the Director may extend it, on conditions, for **no more than 30 days**. SACAA procedure AM007 also says you must contact the SACAA medical department before the certificate expires, and SACAA's FAQ page explains where to send the request. An extension is a safety net, not a plan, so book your renewal early."},{t:"h2",x:"Where can I renew at Grand Central Airport?",id:"midrand"},{t:"p",x:"ClinoTrend Health & Aviation is at Gate 2, Office TG6B, Grand Central Airport, Midrand. [Book a Class 2 or Class 4 renewal](/book/?service=renewal), or read more on the [aviation medicals page](/aviation-medicals/) and the [Midrand aviation medical guide](/blog/aviation-medical-midrand-johannesburg/)."},{t:"cta",x:"Book your Class 2 renewal"}],faq:[{q:"Can my GP renew my Class 2 medical?",a:"Only if your GP is a SACAA Designated Aviation Medical Examiner. A Class 2 certificate must be issued by a DAME. Regular DAMEs issue Class 2 and Class 4. Senior DAMEs also issue Class 1 and Class 3."},{q:"How early can I renew my Class 2 medical?",a:"You can renew before the expiry date, but the new certificate runs from the month it is issued. Unused time on the old certificate is not added. Booking a few weeks early leaves room if a further report is needed."},{q:"What if my Class 2 medical expires before I can be examined?",a:"Contact the SACAA medical department before the expiry date to ask for an extension, as SACAA procedure AM007 requires. Regulation 67.00.6(6) says to apply at least 15 days before expiry, and an extension is for no more than 30 days. Then book your examination as soon as you can."},{q:"Do I need a chest X-ray for a Class 2 renewal?",a:"SACAA lists a chest X-ray at the initial examination and afterwards only when it is indicated on clinical grounds. The examiner will tell you which tests apply, including whether a chest X-ray is needed and whether it is done on site or referred."},{q:"Does a Class 1 medical cover Class 2 privileges?",a:"Yes. Regulation 67.00.2 says that a flight crew member with a valid Class 1 certificate is deemed to hold valid Class 2 and Class 4 certificates. ClinoTrend does not currently issue Class 1."}],sources:[e.validityReg,e.protocols,e.classes,e.application,e.am007,e.avmed,e.register,e.form,e.faq]},n={slug:"cabin-crew-medical-class-4-south-africa",title:"Cabin Crew Medical Requirements in SA | ClinoTrend",h1:"Cabin crew medical requirements in South Africa",description:"What medical cabin crew need in South Africa, who can examine you, Class 2 or Class 4, what to bring, and how to book at Grand Central Airport, Midrand.",excerpt:"What medical class cabin crew need, who can examine you, how long a certificate lasts, what to bring, and how to book at Grand Central Airport, Midrand.",keyword:"cabin crew medical south africa",question:"What medical do cabin crew need in South Africa?",answer:"Cabin crew need a Part 67 medical. The amended regulations list cabin crew under Class 4, while some SACAA pages still list Class 2. ClinoTrend can issue Class 2 or Class 4 for cabin crew, depending on what the airline or operator asks for. Tell us which class is required when you book.",facts:["Amended Part 67, regulation 67.00.2, lists the cabin crew member licence under Class 4.","Some SACAA pages, including the aviation medicine page and a medical-requirements table in the frequently asked questions, still list Class 2 or Class II for cabin crew.","Class 4 holders must also submit a yearly medical declaration to SACAA, on the form prescribed in SA-CATS 67 (regulation 67.00.9(3))."],secondary:["cabin crew class 4 medical","cabin crew medical certificate sacaa","class 4 aviation medical"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Cabin crew",body:[{t:"p",x:"If you are starting a cabin crew course, joining an airline, or renewing an existing cabin crew medical, you need a current medical certificate under Part 67 of the Civil Aviation Regulations. Official sources do not all use the same class name, so it helps to know what your airline or operator has asked for before you book."},{t:"h2",x:"Which medical class do cabin crew need?",id:"class"},{t:"p",x:"The amended Part 67 regulation 67.00.2 lists the **cabin crew member licence under Class 4**, alongside recreational licences such as microlight, gyroplane and glider. A SACAA frequently asked questions item says the regulation was promulgated in May 2019 and that cabin crew require a Class 4 medical."},{t:"p",x:"Some SACAA pages still list cabin crew under **Class 2 or Class II**, including the aviation medicine page and the medical-requirements table in the frequently asked questions. Because those pages have not all been updated to match the amended regulation, tell us which class your airline or operator has asked for when you book."},{t:"p",x:"Dr A.O. Ndhlovu at ClinoTrend is a Regular DAME (SACAA MR 336). He can issue **Class 2 or Class 4** for cabin crew, depending on what is required. Our guide to [SACAA medical classes](/blog/sacaa-medical-classes-explained/) sets out who needs which class."},{t:"h2",x:"Who can do a cabin crew medical?",id:"who"},{t:"p",x:"If a Class 4 medical is required, it is the one class that does not have to be done by a designated examiner. Regulation 67.00.5 allows any medical practitioner registered with the HPCSA to perform the examination, provided the application, supporting reports and test results are sent to the designated body within 60 days for verification before the certificate is issued."},{t:"p",x:"A SACAA Designated Aviation Medical Examiner (DAME) can also examine you and issue a Class 4 certificate. Regular and Senior DAMEs are both authorised for Class IV. A Class 2 medical, if that is what is required, must be done by a DAME. Dr Ndhlovu can do either class at Grand Central Airport in Midrand."},{t:"h2",x:"What does the cabin crew medical include?",id:"tests"},{t:"p",x:"The examiner takes your medical history and examines you. Typical parts of the examination include:"},{t:"ul",items:["Your medical history, taken on the SACAA form CA 67-02(a), and a signed declaration","A physical examination","Vision testing","A hearing test (audiometry)","A resting ECG","Urine screening"]},{t:"p",x:"At ClinoTrend the ECG, vision testing, hearing test and urine screening are done on site. The examiner will tell you which other tests apply, including whether a chest X-ray or any further tests are needed, and whether they are done on site or referred. Height and swimming tests, if an airline requires them for training or employment, are not part of the SACAA medical itself."},{t:"h2",x:"How long does a cabin crew medical last?",id:"validity"},{t:"p",x:"If you are issued a **Class 4** certificate, regulation 67.00.6(4) sets the period at 60 months if you are less than 40 years of age, and 36 months if you are 40 or older, calculated to the last day of a month. If you are issued a **Class 2** certificate, regulation 67.00.6(3) sets 60 months if you are less than 40, 24 months after your 40th birthday, and 12 months after your 50th birthday. Medical conditions can mean a shorter period. [How long is a Class 2 medical valid?](/blog/class-2-medical-validity-by-age/) includes a calculator for both classes."},{t:"h3",x:"The yearly Class 4 declaration"},{t:"p",x:"If you hold a Class 4 certificate, regulation 67.00.9(3) requires you to complete and submit a medical declaration to SACAA **every year**, on the form prescribed in SA-CATS 67. Contact the practice or SACAA if you are unsure which form to use."},{t:"h2",x:"Should I get the medical before a cabin crew course?",id:"course"},{t:"p",x:"Yes, if the school or airline asks you to hold a current medical before you start, or before you fly as part of training. Completing it early means a finding that needs a further report will not delay the start of your course. Ask the school which class it wants you to book."},{t:"h2",x:"What should cabin crew bring?",id:"bring"},{t:"p",x:"Regulation 67.00.7 requires you to show proof of identity, your licence and your latest medical certificate if you have one, give your medical history and sign a declaration. Bring:"},{t:"ul",items:["Your South African ID or passport","Your cabin crew licence, if you already hold one, and your current medical certificate","A list of every medicine you take, including over the counter medicines","Glasses, contact lenses or hearing aids, if you use them","Recent reports from your doctor or specialist if you have a medical condition"]},{t:"p",x:"Complete the SACAA application form for a medical certificate online before you arrive. The [Aviation Medical Report form, CA 67-02(a)](https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-forms-and-checklist/CA%2067-02%28a%29.pdf) is completed on the day."},{t:"h2",x:"How do I book a cabin crew medical in Midrand?",id:"book"},{t:"p",x:"ClinoTrend Health & Aviation is in the Main Terminal Building at Grand Central Airport, Gate 2, Office TG6B, between Johannesburg and Pretoria. You can reach the airport from Midrand Gautrain Station by e-hailing or taxi; contact the practice for directions. Ask the practice how long to allow when you book. Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book."},{t:"p",x:"[Book a Class 4 medical](/book/?service=class-4) or a [Class 2 medical](/book/?service=class-2). The [cabin crew medical page](/cabin-crew-medical/) covers the medical for working cabin crew and for aspiring flight attendants, and the [Class 4 medical certificate page](/class-4-medical/) covers validity, the yearly declaration and how to book. You can also read the [aviation medicals page](/aviation-medicals/)."},{t:"cta",x:"Book your cabin crew medical"}],faq:[{q:"Do cabin crew need a Class 2 or a Class 4 medical?",a:"It depends on what the airline or operator asks for. Amended Part 67 lists cabin crew under Class 4. Some SACAA pages still list Class 2 or Class II. ClinoTrend can issue Class 2 or Class 4 for cabin crew. Tell us which class is required when you book."},{q:"Can my own GP do my cabin crew medical?",a:"If a Class 4 medical is required, regulation 67.00.5 allows a medical practitioner registered with the HPCSA to perform the examination, provided the results are sent for verification within 60 days. A Class 2 medical must be done by a designated aviation medical examiner. A DAME can also issue Class 4."},{q:"How long is a Class 4 medical valid for cabin crew?",a:"Under regulation 67.00.6(4), a Class 4 certificate is valid for 60 months if you are less than 40 years of age, and 36 months if you are 40 or older, to the last day of a month. If you are issued a Class 2 certificate instead, different periods apply under regulation 67.00.6(3)."},{q:"Do I need the medical before my cabin crew course?",a:"If the school or airline requires a current medical before you start, or before you fly in training, complete it first. Ask which class they want you to book."},{q:"Are height and swimming part of the medical?",a:"No. Height and swimming requirements, if an airline or school uses them, are training or employment conditions, not part of the SACAA medical examination itself."}],sources:[e.cabin,e.classes,e.faq,e.class4,e.duties,e.validityReg,e.protocols,e.avmed,e.register,e.form]},r={slug:"aviation-medical-midrand-johannesburg",title:"Aviation Medical Examiner, Johannesburg | ClinoTrend",h1:"Aviation medical examiner in Midrand and Johannesburg",description:"Find a SACAA aviation medical examiner in Midrand and Johannesburg: what to bring, how the exam works, fees from R1,500, and how to book at Grand Central.",excerpt:"Where to find a SACAA designated examiner in Midrand, what to bring, how the examination works, fees, and how to book at Grand Central Airport.",keyword:"aviation medical examiner johannesburg",question:"Where can I get an aviation medical near Johannesburg?",answer:"Dr A.O. Ndhlovu, a SACAA Regular Designated Aviation Medical Examiner (MR 336), does Class 2 and Class 4 aviation medicals at ClinoTrend, Gate 2, Grand Central Airport in Midrand, on the N1 between Johannesburg and Pretoria. Book online, or fly in to FAGC. ClinoTrend does not currently issue Class 1 or Class 3.",facts:["Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book.","On-site tests include a resting ECG, vision testing, audiometry (hearing) and urine screening.","You can reach Grand Central from Midrand Gautrain Station by e-hailing or taxi. Contact the practice for directions."],secondary:["aviation medical midrand","sacaa medical examiner johannesburg","class 2 medical midrand"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Midrand",body:[{t:"p",x:"If you are looking for a SACAA aviation medical examiner in Midrand or Johannesburg, ClinoTrend Health & Aviation is at Grand Central Airport, between Johannesburg and Pretoria. Dr A.O. Ndhlovu is listed on the SACAA list of Regular Designated Aviation Medical Examiners as MR 336."},{t:"h2",x:"Which medicals are done at Grand Central?",id:"which"},{t:"p",x:"As a Regular DAME, Dr Ndhlovu issues Class 2 and Class 4 medical certificates. That covers student and private pilots, recreational pilots, and cabin crew (Class 2 or Class 4, depending on what the airline or operator asks for). Our guides to [SACAA medical classes](/blog/sacaa-medical-classes-explained/) and [cabin crew medical requirements](/blog/cabin-crew-medical-class-4-south-africa/) explain who needs which class."},{t:"table",caption:"Medical classes at ClinoTrend (Grand Central Airport, Midrand)",head:["Class","Typical licences","Issued here?"],rows:[["Class 2","Student pilots (SPL) and private pilots (PPL), plus other licences listed in regulation 67.00.2","Yes"],["Class 4","Recreational pilots, and cabin crew when a Class 4 is required","Yes"],["Class 1","Commercial and airline transport pilots","Not currently"],["Class 3","Air traffic controllers","Not currently"]]},{t:"p",x:"Class 1 and Class 3 medicals need a SACAA Senior DAME. ClinoTrend does not currently issue Class 1 or Class 3."},{t:"h2",x:"Where is the practice?",id:"where"},{t:"p",x:"ClinoTrend is in the Main Terminal Building, Gate 2, Office TG6B, Grand Central Airport, 3 New Road, Midrand. You can drive in, or fly in to FAGC and park on the apron outside the Gate 2 terminal doors."},{t:"ul",items:["**By car:** Grand Central Airport is on the N1 between Johannesburg and Pretoria. Use Gate 2.","**By Gautrain:** You can reach Grand Central from Midrand Gautrain Station by e-hailing or taxi. Contact the practice for directions.","**By air:** Fly in to Grand Central (FAGC) and park on the apron outside the terminal doors."]},{t:"p",x:"The [contact page](/contact/) has hours, a map and further directions."},{t:"h2",x:"What should I bring?",id:"bring"},{t:"p",x:"Part 67 (regulation 67.00.7) requires you to show proof of identity, your licence and your latest medical certificate if you have one, give your medical history and sign a declaration. Bring:"},{t:"ul",items:["Your South African ID or passport","Any aviation licence you hold, and your logbook if you are renewing","Your most recent aviation medical certificate, if you have one","A list of every medicine you take, including over the counter medicines","Glasses, contact lenses or hearing aids, if you use them","Recent reports from your doctor or specialist if you have a medical condition"]},{t:"p",x:"Complete the SACAA application form for a medical certificate online before you arrive. The [Aviation Medical Report form, CA 67-02(a)](https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-forms-and-checklist/CA%2067-02%28a%29.pdf) is completed on the day."},{t:"h2",x:"What happens during the examination?",id:"examination"},{t:"p",x:"The examiner takes your history and examines you. At ClinoTrend a resting ECG, vision testing, a hearing test (audiometry) and urine screening are done on site. The examiner will tell you which other tests apply, including whether a chest X-ray or any further tests are needed, and whether they are done on site or referred. Ask the practice how long to allow when you book, and whether you should arrive early to complete paperwork."},{t:"h2",x:"What does an aviation medical cost?",id:"fees"},{t:"p",x:"Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book. Fees differ between examiners and are set by each practice."},{t:"h2",x:"How do I book?",id:"book"},{t:"p",x:"Medicals are by appointment only. [Book an appointment](/book/), choose a [Class 2 medical](/book/?service=class-2), a [Class 4 medical](/book/?service=class-4), or a [renewal](/book/?service=renewal), or read the [aviation medicals page](/aviation-medicals/). Flight schools, academies and airlines can arrange group bookings in advance."},{t:"cta",x:"Book your aviation medical in Midrand"}],faq:[{q:"Where can I get an aviation medical near Johannesburg?",a:"At ClinoTrend Health & Aviation, Gate 2, Grand Central Airport, Midrand, with Dr A.O. Ndhlovu, a SACAA Regular Designated Aviation Medical Examiner (MR 336). The practice does Class 2 and Class 4 medicals."},{q:"How long does an aviation medical take?",a:"Ask the practice how long to allow when you book, and arrive a little early. Bringing the documents on the checklist and completing the SACAA form online beforehand helps the visit run smoothly."},{q:"How much does an aviation medical cost in Midrand?",a:"Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book."},{q:"Can I do a Class 1 medical at ClinoTrend?",a:"ClinoTrend does not currently issue Class 1. Class 1 and Class 3 medicals need a SACAA Senior DAME."},{q:"Can I fly in to Grand Central for my medical?",a:"Yes. Fly in to Grand Central Airport (FAGC) and park on the apron outside the Gate 2 terminal doors. Book first, as medicals are by appointment only."}],sources:[e.register,e.avmed,e.classes,e.application,e.form,e.faq]},l={slug:"class-2-medical-validity-by-age",title:"How Long a Class 2 Medical Is Valid | ClinoTrend",h1:"How long a Class 2 medical is valid, by age",description:"How long a SACAA Class 2 medical is valid: 60 months under 40, 24 months from 40, 12 months from 50, under Part 67. Includes Class 4 periods and a calculator.",excerpt:"Class 2 validity under Part 67: 60 months under 40, 24 months after 40, 12 months after 50. Class 4 periods, how the date is counted, and a calculator.",keyword:"class 2 medical validity",question:"How long is a SACAA Class 2 medical valid?",answer:"Under Part 67, regulation 67.00.6(3), a Class 2 medical is valid for 60 months if you are less than 40, 24 months after your 40th birthday, and 12 months after your 50th birthday, running to the last day of a month. Older FAQ pages show shorter periods; this practice follows the regulation. The date on your certificate counts.",facts:["A Class 4 certificate is valid for 60 months if you are less than 40, and 36 months from age 40, under regulation 67.00.6(4).","A DAME or a SACAA medical assessor may shorten the period and endorse a limitation, under regulation 67.00.6(5).","Unused time is not carried over when you renew: the new certificate runs from the month it is issued."],secondary:["class 2 medical certificate validity south africa","class 4 medical validity","sacaa medical expiry"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Validity",body:[{t:"p",x:"The date on your medical certificate is the date that matters. The periods below come from Part 67, regulation 67.00.6, and from the SACAA summarised medical protocols (effective 16 November 2021). Older SACAA FAQ pages show shorter Class 2 periods. This practice follows the regulation."},{t:"h2",x:"How long is a Class 2 medical valid?",id:"class-2"},{t:"p",x:"Regulation 67.00.6(3) says a Class 2 certificate is valid for:"},{t:"ul",items:["60 months, if the holder is less than 40 years of age","24 months, once the holder has passed their 40th birthday","12 months, once the holder has passed their 50th birthday"]},{t:"p",x:"The period is calculated from the last day of the calendar month in which the certificate is issued. For example, a Class 2 issued on 10 March 2026 to a holder younger than 40 expires on 31 March 2031. The same issue date expires on 31 March 2028 after the 40th birthday, and on 31 March 2027 after the 50th birthday."},{t:"h2",x:"How is the expiry date counted?",id:"counted"},{t:"p",x:"Validity always runs to the last day of a month. If a certificate is issued part way through a month, that whole month is counted, and the period then runs in calendar months from the end of that month. Medical conditions can mean more frequent examinations, so always use the date printed on your certificate."},{t:"calc"},{t:"h2",x:"How long is a Class 4 medical valid?",id:"class-4"},{t:"p",x:"Regulation 67.00.6(4) says a Class 4 certificate is issued for a period not exceeding 60 calendar months if the applicant is less than 40 years of age, and 36 calendar months if the applicant is 40 years of age or more, again to the last day of the month. Cabin crew may be issued Class 2 or Class 4; use the periods that match the class on your certificate. See [cabin crew medical requirements](/blog/cabin-crew-medical-class-4-south-africa/)."},{t:"h2",x:"What about Class 1 and Class 3?",id:"other-classes"},{t:"p",x:"Class 1 periods are set out in regulation 67.00.6(1). In short, a Class 1 certificate is issued for 12 months if the applicant is less than 40. From age 40 the period depends on the licence and the type of operation: six months for an airline transport pilot in single-crew commercial air transport operations; 12 months for an airline transport pilot in multi-crew operations, and for a commercial pilot, until age 60; and six months from age 60 for those last two groups. Holders in the 12 month bands from age 40 may also have extra reporting duties under regulation 67.00.6(2)."},{t:"p",x:"Class 3, under regulation 67.00.6(3), is 48 months if the holder is less than 40, 24 months after the 40th birthday, and 12 months after the 50th birthday. Class 1 and Class 3 medicals need a SACAA Senior DAME. ClinoTrend does not currently issue Class 1 or Class 3."},{t:"h2",x:"Can the period be shorter?",id:"shorter"},{t:"p",x:"Yes. Regulation 67.00.6(5) allows a DAME or a medical assessor to reduce the period of validity and endorse the reason, or any limitation, if a further examination or test is needed, or if safe performance of the holder's duties depends on a shorter period or a special limitation."},{t:"h2",x:"What changes when I turn 40 or 50?",id:"birthdays"},{t:"p",x:"The Class 2 period is set by your age on the date the certificate is issued. Once you have passed your 40th birthday, a new Class 2 is issued for 24 months. Once you have passed your 50th birthday, a new Class 2 is issued for 12 months. Turning 40 or 50 during a current period does not cut that certificate short; the shorter period applies at the next issue."},{t:"h2",x:"How should I plan renewals?",id:"planning"},{t:"p",x:"Book a few weeks before the expiry date, so there is time if the examiner asks for a specialist letter or an extra test. Renewing many months early does not add the unused time to the new certificate, because the new period starts from the month of issue. Our [Class 2 renewal guide](/blog/renew-sacaa-class-2-medical/) walks through the steps."},{t:"h2",x:"What if I am close to expiry?",id:"expiry"},{t:"p",x:"Regulation 67.00.6(6) says you must apply for an extension at least 15 days before your certificate expires. The Director may extend it, on conditions, for no more than 30 days. SACAA procedure AM007 also says you must contact the SACAA medical department before the certificate expires. An extension is a safety net, not a plan."},{t:"cta",x:"Book your Class 2 or Class 4 renewal"}],faq:[{q:"How long is a Class 2 medical valid if I am under 40?",a:"60 months, calculated from the last day of the month in which the certificate is issued, under regulation 67.00.6(3). Medical conditions can mean a shorter period. The date on your certificate is the one that applies."},{q:"How long is a Class 2 medical valid after 40?",a:"24 months once you have passed your 40th birthday, and 12 months once you have passed your 50th birthday, under regulation 67.00.6(3). Older SACAA FAQ pages show shorter periods; this practice follows the regulation."},{q:"How long is a Class 4 medical valid?",a:"60 months if you are less than 40 years of age, and 36 months if you are 40 or older, under regulation 67.00.6(4), to the last day of a month."},{q:"Can my certificate be valid for a shorter time?",a:"Yes. Regulation 67.00.6(5) allows a DAME or a medical assessor to reduce the period and endorse a reason or a limitation when a further test is needed, or when safety depends on it."},{q:"Can I extend my medical certificate?",a:"Yes, by applying to SACAA at least 15 days before expiry. Regulation 67.00.6(6) allows an extension of no more than 30 days, on conditions. Contact the SACAA medical department before the certificate expires."}],sources:[e.validityReg,e.protocols,e.am007,e.classes,e.faq,e.avmed]},d={slug:"sacaa-medical-classes-explained",title:"Aviation Medical Classes in South Africa | ClinoTrend",h1:"SACAA aviation medical classes explained",description:"Which SACAA medical class you need: Class 1, 2, 3, 4 and 5 under Part 67, who may examine you, and which classes ClinoTrend issues in Midrand.",excerpt:"Class 1 to Class 5 under Part 67: which licences they cover, who may examine you, and which classes are issued at ClinoTrend in Midrand.",keyword:"sacaa medical classes",question:"Which SACAA medical class do I need?",answer:"It depends on your licence. Under Part 67, regulation 67.00.2, commercial and airline pilots need Class 1, student and private pilots Class 2, air traffic services staff Class 3, most recreational pilots Class 4, and paragliding, hang gliding and parachute licences a Class 5 declaration. ClinoTrend issues Class 2 and Class 4.",facts:["A flight crew member with a valid Class 1 certificate is deemed to hold valid Class 2 and Class 4 certificates (regulation 67.00.2(2)).","Regular DAMEs issue Class II and Class IV. Senior DAMEs also issue Class I and Class III, as described on the SACAA aviation medicine page.","ClinoTrend does not currently issue Class 1 or Class 3."],secondary:["class 1 medical south africa","class 2 vs class 4 medical","class 5 medical sacaa"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Classes",body:[{t:"p",x:"South African aviation licences are tied to a class of medical certificate under Part 67 of the Civil Aviation Regulations. The class you need is set by your licence, not by a preference. This guide follows regulation 67.00.2 for which licences sit under each class, and official SACAA wording for who may examine you."},{t:"h2",x:"What are the five SACAA medical classes?",id:"five"},{t:"table",caption:"SACAA medical classes (Part 67, regulation 67.00.2, as amended)",head:["Class","Main licences it covers","Who examines"],rows:[["Class 1","Airline transport pilot (ATPL), commercial pilot (CPL) for aeroplane, airship and helicopter, instrument rating, Class I test pilot rating","Senior DAME"],["Class 2","Student pilot (SPL), private pilot (PPL) for aeroplane, airship and helicopter, flight engineer, free balloon CPL, commercial glider pilot","Regular or Senior DAME"],["Class 3","Air traffic controller (ATC), air traffic service assistant, remote pilot (RPL)","Senior DAME"],["Class 4","Cabin crew member licence, and recreational licences such as microlight, gyroplane, glider and free balloon","Regular or Senior DAME, or a registered medical practitioner under regulation 67.00.5"],["Class 5","Paraglider, hang glider, powered paratrike and parachute licences and their student licences","Registered medical practitioner (declaration sent to SACAA)"]]},{t:"p",x:'The table shortens the lists. The full wording is in the [SACAA copy of regulation 67.00.2](https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-general-information/Ammended%20%20Part%2067%20Regulations%20Classes%20of%20medical%20certificates.pdf), which also lists instructor ratings, tandem licences and test pilot ratings. The "Who examines" column follows the SACAA aviation medicine page (Regular DAME: Class II and IV; Senior DAME: Class I to IV), together with regulation 67.00.5 for Class 4 and regulation 67.00.2(8) and (9) for Class 5.'},{t:"h2",x:"What is the difference between a Class 1 and a Class 2 medical?",id:"class1-class2"},{t:"p",x:"A Class 1 is for flying as a profession: the CPL, the ATPL and the instrument rating. A Class 2 is for the student and private pilot licences, among others. Class 1 examinations must be done by a SACAA **Senior** Designated Aviation Medical Examiner (DAME). Validity periods also differ; see [how long a Class 2 medical is valid](/blog/class-2-medical-validity-by-age/), which also summarises Class 1 periods under regulation 67.00.6(1)."},{t:"p",x:"Regulation 67.00.2(2) adds a useful rule: a flight crew member with a valid Class 1 certificate is deemed to hold valid Class 2 and Class 4 certificates. If you stop flying commercially, regulation 67.00.2(4) lets you ask for an expired Class 1 to be substituted by a Class 2 or Class 4, with the remaining validity worked out under regulation 67.00.6. ClinoTrend does not currently issue Class 1."},{t:"h2",x:"Which class do cabin crew need?",id:"cabin"},{t:"p",x:"Amended regulation 67.00.2 lists the cabin crew member licence under **Class 4**. Some SACAA pages, including the aviation medicine page and a medical-requirements table in the frequently asked questions, still list cabin crew under Class 2 or Class II. ClinoTrend can issue Class 2 or Class 4 for cabin crew, depending on what the airline or operator asks for. Tell us which class is required when you book. The [cabin crew medical guide](/blog/cabin-crew-medical-class-4-south-africa/) explains this in more detail."},{t:"h2",x:"Which class do recreational pilots need?",id:"recreational"},{t:"p",x:"Most recreational licences, including microlight, gyroplane, glider, light sport aeroplane and free balloon, sit under **Class 4**. Paragliding, hang gliding, powered paratrike and parachute licences, and their student licences, sit under **Class 5**."},{t:"h2",x:"What is a Class 5 medical?",id:"class5"},{t:"p",x:"Class 5 is a declaration sent to SACAA, signed by a registered medical practitioner. Under regulation 67.00.2(8), a person under 60 years of age who submits a duly completed Class 5 medical self-declaration, on the prescribed form and signed by a medical practitioner registered under the Health Professions Act, is deemed to hold a Class 5 medical certificate. Under regulation 67.00.2(9), from age 60 the form is the medical declaration prescribed for that age, also signed by a registered medical practitioner."},{t:"h2",x:"Who can examine you for each class?",id:"who"},{t:"p",x:"SACAA's aviation medicine page states that Regular DAMEs may do Class II and Class IV, and Senior DAMEs may do Class I, II, III and IV. Class 4 may also be done by a registered medical practitioner under regulation 67.00.5, subject to verification. Class 5 is the declaration described above, signed by a registered medical practitioner. Our guide to [checking a SACAA medical examiner](/blog/sacaa-medical-examiners-dame/) shows how to use the official lists. Dr A.O. Ndhlovu is a Regular DAME (MR 336) and issues Class 2 and Class 4 at Grand Central Airport, Midrand. ClinoTrend does not currently issue Class 1 or Class 3."},{t:"h2",x:"How long is each certificate valid?",id:"validity"},{t:"p",x:"Validity periods are set in regulation 67.00.6 and depend on the class and your age. This page does not repeat every figure. [How long is a Class 2 medical valid?](/blog/class-2-medical-validity-by-age/) sets out Class 2 and Class 4, summarises Class 1 and Class 3, and includes a calculator. A DAME or a medical assessor may also shorten the period under regulation 67.00.6(5)."},{t:"h2",x:"Not sure which class you need?",id:"book"},{t:"p",x:"Check the licence you hold or are training for against regulation 67.00.2, or ask your flight school or operator. Then [book the matching medical](/book/), or start from the [aviation medicals page](/aviation-medicals/)."},{t:"cta",x:"Book a Class 2 or Class 4 medical"}],faq:[{q:"Do private pilots need a Class 1 or a Class 2 medical?",a:"A Class 2. Regulation 67.00.2 lists the student pilot licence and the private pilot licence for aeroplane, airship and helicopter under Class 2."},{q:"Does a Class 1 medical cover Class 2?",a:"Yes. Regulation 67.00.2(2) says a flight crew member with a valid Class 1 certificate is deemed to hold valid Class 2 and Class 4 certificates."},{q:"Which medical class do air traffic controllers need?",a:"Class 3. It also covers air traffic service assistants and remote pilots (RPL). Class 3 medicals are done by a SACAA Senior DAME."},{q:"Can a Regular DAME do a Class 1 medical?",a:"No. A Regular DAME does Class II and Class IV. Class I and Class III need a Senior DAME. ClinoTrend does not currently issue Class 1 or Class 3."},{q:"What is a Class 5 medical?",a:"A declaration sent to SACAA, signed by a registered medical practitioner, for paragliding, hang gliding, powered paratrike and parachute licences. For applicants under 60 the prescribed form is the Class 5 medical self-declaration. From age 60 the form is the medical declaration prescribed for that age."}],sources:[e.classes,e.classesReg,e.class4,e.validityReg,e.avmed,e.register]},c={slug:"student-pilot-medical-south-africa",title:"Student Pilot Medical Requirements | ClinoTrend",h1:"Student pilot medical requirements in South Africa",description:"What medical a student pilot needs in South Africa before flying solo, when to book, what to bring, and how schools can arrange group medicals in Midrand.",excerpt:"The medical a student pilot needs before flying solo, when to book, what to bring, and how flight schools can arrange group medicals in Midrand.",keyword:"student pilot medical south africa",question:"What medical does a student pilot need in South Africa?",answer:"Before you fly solo on a student pilot licence you need a valid medical certificate issued under Part 67. An SPL for aeroplane, airship or helicopter sits under Class 2. Recreational student licences sit under Class 4. Book a few weeks before you expect to fly solo, and complete the SACAA application form beforehand.",facts:["Part 61, regulation 61.02.1, says an applicant for an SPL or ISPL must be 15 years or older, hold a valid medical certificate issued under Part 67, and be registered with an approved training organisation.","Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book.","Flight schools can arrange group medicals at ClinoTrend in advance."],secondary:["student pilot licence medical","first class 2 medical","flight school aviation medical"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Student pilots",body:[{t:"p",x:"A first aviation medical is one of the early steps in learning to fly. This guide covers what a student pilot needs, when to book, what happens at a first Class 2 medical, and how flight schools can book a group at Grand Central Airport, Midrand."},{t:"h2",x:"Do student pilots need a medical?",id:"need"},{t:"p",x:"Yes. Part 61, regulation 61.02.1 (as amended on 21 August 2026), says an applicant for a student pilot licence (SPL) or integrated student pilot licence (ISPL) must be 15 years or older, hold a valid medical certificate issued in terms of Part 67, and be registered with an approved training organisation (ATO). Your SPL is what allows you to fly solo under instruction, so the medical comes first."},{t:"h2",x:"Which medical class does a student pilot need?",id:"class"},{t:"p",x:"Regulation 67.00.2 lists the SPL under **Class 2**, alongside the private pilot licence (PPL). Students on recreational licences are different: an SPL for a microlight, gyroplane, light sport aeroplane or glider licence sits under **Class 4**. Our guide to [SACAA medical classes](/blog/sacaa-medical-classes-explained/) has the full list."},{t:"p",x:"The 21 August 2026 amendment added the integrated student pilot licence (ISPL). An ISPL, like an SPL, requires a valid medical certificate issued under Part 67. Confirm with your flight school, or contact the practice, which class is required for your course."},{t:"p",x:"A commercial pilot licence (CPL), an airline transport pilot licence (ATPL) and an instrument rating all need a **Class 1** medical, which only a SACAA Senior DAME may do. Ask your flight school when it wants you to hold a Class 1. Dr Ndhlovu is a Regular DAME, so at ClinoTrend we do the Class 2 that covers your SPL and PPL. ClinoTrend does not currently issue Class 1."},{t:"h2",x:"When should I book my first medical?",id:"when"},{t:"p",x:"Book a few weeks before you expect to fly solo, so there is time if the examiner asks for a further test or a report. You do not usually need the certificate before your first dual lessons, unless your school asks for it. Complete the SACAA application form online before you arrive."},{t:"h2",x:"What happens at a first Class 2 medical?",id:"first"},{t:"p",x:"You complete your medical history on the SACAA form and sign a declaration that it is accurate, complete and true, as regulation 67.00.7 requires. The doctor then examines you. At ClinoTrend these tests are done on site:"},{t:"ul",items:["A resting ECG","Vision testing","A hearing test (audiometry)","Urine screening"]},{t:"p",x:"The examiner will tell you which other tests apply for a first Class 2, including whether a chest X-ray or any further tests are needed, and whether they are done on site or referred. SACAA's medical requirements list a chest X-ray at the initial examination, and afterwards only when it is indicated on clinical grounds. Ask the practice how long to allow when you book."},{t:"h2",x:"How long is a student pilot medical valid?",id:"validity"},{t:"p",x:"If you are issued a Class 2 certificate and you are less than 40 years of age, regulation 67.00.6(3) sets the period at 60 months, to the last day of the month of issue. After 40 and after 50 the period is shorter. [How long is a Class 2 medical valid?](/blog/class-2-medical-validity-by-age/) explains the dates and has a calculator. Recreational students issued a Class 4 follow the Class 4 periods."},{t:"h2",x:"What should a student pilot bring?",id:"bring"},{t:"p",x:"Bring your South African ID or passport, a list of every medicine you take, glasses or contact lenses if you use them, and any reports from your own doctor if you have a medical condition. Complete the SACAA application form beforehand. The [Aviation Medical Report form, CA 67-02(a)](https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-forms-and-checklist/CA%2067-02%28a%29.pdf) is completed on the day."},{t:"p",x:"Students can start from 15. If you are under 18, contact the practice to confirm any extra requirements before you book."},{t:"h2",x:"Can flight schools book group medicals?",id:"groups"},{t:"p",x:"Yes. Flight schools can arrange group medicals at ClinoTrend in advance. Call or email the practice with the number of students and the dates that suit you. Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical. We confirm the fee when you book. [Book a Class 2 medical](/book/?service=class-2), or read the [aviation medicals page](/aviation-medicals/)."},{t:"cta",x:"Book a student pilot medical"}],faq:[{q:"Do I need a medical before my first flying lesson?",a:"You need a valid medical certificate issued under Part 67 before you fly solo on a student pilot licence. Some schools also ask for it earlier. Check with your flight school."},{q:"What medical class is a student pilot licence?",a:"An SPL for aeroplane, airship or helicopter is listed under Class 2 in regulation 67.00.2. Recreational student licences such as microlight or glider sit under Class 4."},{q:"How old must I be for a student pilot licence?",a:"Regulation 61.02.1, as amended on 21 August 2026, says an applicant for an SPL or ISPL must be 15 years or older. If you are under 18, contact the practice to confirm any extra requirements before you book."},{q:"Can I do my Class 1 medical at ClinoTrend?",a:"ClinoTrend does not currently issue Class 1. A Class 1 needs a SACAA Senior DAME. Dr Ndhlovu is a Regular DAME and does Class 2 and Class 4 medicals."},{q:"Can a flight school book medicals for a group of students?",a:"Yes. Group bookings are arranged in advance. Contact the practice with the number of students and the dates that suit you."}],sources:[e.spl,e.classes,e.application,e.validityReg,e.protocols,e.form,e.avmed,e.register]},h={slug:"sacaa-medical-examiners-dame",title:"SACAA Medical Examiners: How to Check | ClinoTrend",h1:"SACAA medical examiners: how to check a DAME",description:"What a SACAA Designated Aviation Medical Examiner (DAME) is, Regular versus Senior, how to check the official list, and where to find one in Midrand.",excerpt:"What a DAME is, the difference between Regular and Senior examiners, how to check the official SACAA lists, and where to find one in Midrand.",keyword:"sacaa medical examiners",question:"How do I check that an aviation medical examiner is designated by SACAA?",answer:"A DAME is a doctor designated by the Director of Civil Aviation to examine applicants and to issue or defer certificates under Part 67. Regular DAMEs do Class 2 and Class 4. Senior DAMEs also do Class 1 and Class 3. Check the SACAA lists. Dr A.O. Ndhlovu is listed as Regular DAME MR 336 at Grand Central Airport, Midrand.",facts:["SACAA publishes separate lists of Regular and Senior Designated Aviation Medical Examiners on its aviation medicine page.","Your family GP cannot issue a Class 1, 2 or 3 certificate unless he or she is designated. Class 4 may be done by a registered medical practitioner under regulation 67.00.5.","Always match the examiner's designation to the class you need."],secondary:["designated aviation medical examiner","dame sacaa","aviation medical examiner midrand"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Examiners",body:[{t:"p",x:"An aviation medical in South Africa has to be done by the right kind of examiner for the class you need. This guide explains what a Designated Aviation Medical Examiner is, how Regular and Senior designations differ, and how to check the official SACAA lists before you book."},{t:"h2",x:"What is a DAME?",id:"what"},{t:"p",x:"A Designated Aviation Medical Examiner, or DAME, is a doctor designated by the Director of Civil Aviation under Part 67, regulation 67.00.4, to do aviation medical examinations and to issue, or defer, medical certificates on behalf of SACAA. The designation is personal to that doctor and is shown by a designation number, such as MR 336."},{t:"h2",x:"What is the difference between a Regular DAME and a Senior DAME?",id:"difference"},{t:"p",x:"SACAA's aviation medicine page describes two categories:"},{t:"ul",items:["**Regular DAME:** authorised to examine for and issue Class II and Class IV medical certificates.","**Senior DAME:** authorised to examine for and issue Class I, II, III and IV medical certificates."]},{t:"p",x:"If you need a Class 1 or Class 3 medical, you must see a Senior DAME. A Regular DAME can renew a Class 2 or issue a Class 4. Our guide to [SACAA medical classes](/blog/sacaa-medical-classes-explained/) lists which licences sit under each class."},{t:"h2",x:"How do I check that an examiner is designated?",id:"check"},{t:"p",x:"SACAA publishes the names of designated examiners on its [aviation medicine page](https://www.caa.co.za/industry-information/aviation-medicine/). There is a list of Regular DAMEs and a list of Senior DAMEs. Look for the doctor's name, designation number and the town or practice address, and check that the list is the current one."},{t:"p",x:"A current designation matters because only a designated examiner may issue the classes they are authorised for. If you are unsure, contact the SACAA medical department or ask the practice to confirm the designation number against the list."},{t:"h2",x:"Can my own GP do the medical?",id:"gp"},{t:"p",x:"Not for Class 1, 2 or 3, unless your GP is also a designated examiner. Class 4 is different: regulation 67.00.5 allows a medical practitioner registered with the HPCSA to perform the examination, provided the application and results are sent for verification within 60 days before the certificate is issued. A DAME can also issue Class 4."},{t:"h2",x:"Where can I find a SACAA medical examiner in Midrand?",id:"midrand"},{t:"p",x:"Dr A.O. Ndhlovu is listed as a Regular DAME, designation MR 336, at ClinoTrend Health & Aviation, Gate 2, Grand Central Airport, Midrand. He does Class 2 and Class 4 medicals, including for cabin crew when either class is required. ClinoTrend does not currently issue Class 1 or Class 3. [Book an appointment](/book/), or read the [Midrand aviation medical guide](/blog/aviation-medical-midrand-johannesburg/) and the [aviation medicals page](/aviation-medicals/)."},{t:"cta",x:"Book with a designated examiner in Midrand"}],faq:[{q:"What does DAME stand for?",a:"Designated Aviation Medical Examiner. It is a doctor designated by the Director of Civil Aviation under Part 67 to examine applicants and to issue or defer medical certificates on behalf of SACAA."},{q:"Where is the list of SACAA medical examiners?",a:"On the SACAA aviation medicine page. SACAA publishes a list of Regular DAMEs and a list of Senior DAMEs. Check the current list for the doctor's name and designation number."},{q:"Can a Regular DAME renew my Class 2?",a:"Yes. Regular DAMEs are authorised for Class II and Class IV. Senior DAMEs may also do Class I and Class III."},{q:"Can my own GP do my aviation medical?",a:"Only if your GP is a designated examiner, except for Class 4, which regulation 67.00.5 allows a registered medical practitioner to perform, subject to verification. Class 1, 2 and 3 must be done by a DAME of the right category."},{q:"Is Dr Ndhlovu a SACAA designated examiner?",a:"Yes. He is listed on the SACAA list of Regular DAMEs as MR 336, at ClinoTrend, Grand Central Airport, Midrand. He does Class 2 and Class 4 medicals. ClinoTrend does not currently issue Class 1 or Class 3."}],sources:[e.register,e.avmed,e.designation,e.class4,e.am007,e.classes]},u={slug:"aviation-medical-deferred-what-next",title:"Aviation Medical Deferral: What Next | ClinoTrend",h1:"What happens if your aviation medical is deferred",description:"What happens if a SACAA aviation medical is deferred: next steps under Part 67, the Aeromedical Committee, limitations, the 30 day appeal, and what to report.",excerpt:"What a deferral means, how SACAA reviews a case, limitations and shorter validity, the 30 day appeal, and what you must report between medicals.",keyword:"aviation medical deferred",question:"What happens if my SACAA aviation medical is deferred?",answer:"A deferral is not a final no. Under Part 67 a designated examiner may defer your certificate until SACAA gives an instruction, usually after a further report or test. Complicated cases go to the SACAA Aeromedical Committee. A certificate can also be issued with a limitation or a shorter validity, and you may appeal a decision within 30 days.",facts:["Examination records may be used to issue a certificate for no more than 90 days (regulation 67.00.12). After that the examination may need to be repeated.","SACAA procedure AM007 says the Aeromedical Committee meets on the third Tuesday of each month, and documents must be submitted at least seven days before the meeting.","An appeal against a deferral or similar decision is 30 days; an appeal against a suspension is 14 days under regulation 67.00.14."],secondary:["sacaa aeromedical committee","medical certificate limitation","appeal aviation medical"],published:"2026-11-10",updated:"2026-11-10",status:"approved",tag:"Deferrals",body:[{t:"p",x:"Most aviation medicals end with a certificate issued on the day. Sometimes the examiner cannot decide yet. This guide explains what a deferral means under Part 67, the official next steps, limitations, appeals, and what you must report between medicals."},{t:"h2",x:"What does a deferred medical mean?",id:"mean"},{t:"p",x:"Part 67, regulation 67.00.4, says a designated examiner may examine you, issue your certificate, or **defer** it pending an instruction from SACAA. A deferral means the examiner cannot decide on the day, usually because a finding or something in your history needs more information. It is not the same as being declared unfit."},{t:"h2",x:"What happens after a deferral?",id:"next"},{t:"ol",items:["The examiner will explain which reports or tests are needed, and how they are sent to SACAA.","You obtain those reports or tests and provide them as instructed.","Straightforward cases can then be finalised. SACAA procedure AM007 says complicated cases are referred to the SACAA **Aeromedical Committee (AMC)**, an advisory panel of medical and aviation industry experts."]},{t:"p",x:"Waiting times depend on the reports and on SACAA. The practice cannot give a typical wait. Time still matters: regulation 67.00.12 says the records of a medical examination may be used to issue a certificate for no more than **90 days**. If your reports take longer than that, the examination may have to be repeated."},{t:"h2",x:"Can I get a certificate with a limitation?",id:"limitation"},{t:"p",x:"Yes. Part 67 allows a certificate to be endorsed with a requirement or limitation when safe flying depends on it, for example wearing corrective lenses. Regulation 67.00.6(5) also lets the examiner or SACAA's medical assessor shorten the validity period, for instance so that a condition is reviewed more often."},{t:"p",x:"Regulation 67.00.8(4A) goes further. In exceptional circumstances SACAA's medical assessor may issue or renew a certificate for someone who does not meet some of the standards, if accredited medical conclusion shows that flying is not likely to jeopardise safety, taking account of the person's ability, skill, experience and operating conditions. Any limitation that safety depends on is endorsed on the licence."},{t:"h2",x:"Can I appeal a decision?",id:"appeal"},{t:"p",x:"Yes. SACAA procedure AM007 says applicants who are aggrieved by the decision of a designated examiner, an authorised officer or the designated body may appeal to the Director of Civil Aviation within **30 days**, as prescribed in Part 67. If SACAA suspends a certificate, regulation 67.00.14 sets a shorter period: an appeal within 14 days of the suspension."},{t:"h2",x:"What must I report between medicals?",id:"report"},{t:"p",x:"Your duties do not stop at the examination. Regulation 67.00.9 says you may not act as a pilot, air traffic service member or cabin crew member while you know of a medical condition or medicine that could affect your certificate, or once it has expired. You must also tell SACAA without undue delay about any:"},{t:"ul",items:["Hospital admission","Surgical operation or invasive procedure","Regular use of medicine","The need to use correcting lenses for the first time, or a change of lenses","An injury or illness that keeps you from exercising the privileges of your licence"]},{t:"p",x:"That applies where the event means you no longer meet the medical standards. Before you fly again you must give SACAA proof that you have fully recovered. If you are unsure whether something counts, ask your examiner. AM007 says every applicant is responsible for consulting their DAME about medical conditions or medicines being considered, to make sure they are compatible with flying."},{t:"h2",x:"How can I keep a deferral from dragging on?",id:"short"},{t:"ul",items:["Answer the history questions on the SACAA form fully. You sign a declaration that they are accurate, complete and true.","Bring recent reports if you already have a known condition.","Once a further report is requested, arrange it promptly. Examination results may only be used for 90 days.","If a case is going to the Aeromedical Committee, AM007 says documents must be in at least seven days before the meeting, which is on the third Tuesday of each month."]},{t:"p",x:"For a routine renewal with no outstanding reports, see [how to renew a Class 2 medical](/blog/renew-sacaa-class-2-medical/) or [book an appointment](/book/)."},{t:"cta",x:"Book your aviation medical"}],faq:[{q:"Does a deferred medical mean I failed?",a:"No. A deferral means the examiner cannot issue the certificate until further information is in, or until SACAA gives an instruction. It is not the same as being declared unfit."},{q:"When does the SACAA Aeromedical Committee meet?",a:"SACAA procedure AM007 says the committee meets on the third Tuesday of each month, and documents must be submitted at least seven days before the meeting."},{q:"How long are my medical examination results valid for?",a:"Regulation 67.00.12 says examination records may be used to issue a certificate for no more than 90 days. After that the examination may need to be repeated."},{q:"How long do I have to appeal a medical decision?",a:"SACAA procedure AM007 says you may appeal to the Director of Civil Aviation within 30 days. An appeal against a suspension must be made within 14 days, under regulation 67.00.14."},{q:"Can I fly while taking medicine?",a:"Not while you know of a medicine or condition that could affect your certificate. Regulation 67.00.9 also requires you to report regular use of medicine. Ask your DAME before you fly."}],sources:[e.designation,e.am007,e.protocols,e.records,e.validityReg,e.issuing,e.suspension,e.duties,e.application]},m={slug:"what-is-included-in-a-sacaa-aviation-medical",title:"What Is Included in a SACAA Aviation Medical? | ClinoTrend",h1:"What is included in a SACAA aviation medical? Tests, history and what happens on the day",description:"What a SACAA aviation medical includes: history, examination, ECG, vision, hearing and urine tests, and which extra tests depend on your class and age.",excerpt:"What a SACAA aviation medical includes: history, examination, and the on-site tests at ClinoTrend, plus which extra tests depend on class, age and history.",keyword:"what is included in an aviation medical",question:"What is included in a SACAA aviation medical?",answer:"A SACAA aviation medical is a history, a physical examination and a set of tests, not a pass or fail quiz. At ClinoTrend, a resting ECG, vision testing, a hearing test and urine screening are done on site. Extra tests are added only when class, age or history requires them. The examiner then issues or defers the certificate.",facts:["At ClinoTrend a resting ECG, vision testing, a hearing test and urine screening are done on site.","Extra tests are added only when class, age or history requires them. We will tell you when you book if something extra is expected.","Aviation medicals start from R1,500. Extra tests or reports are added only if they are needed."],secondary:["what is involved in an aviation medical exam","what does an aviation medical exam consist of","aviation medical tests","ecg aviation medical"],published:"2026-11-18",updated:"2026-11-18",status:"approved",tag:"Tests",body:[{t:"p",x:"This is general information about SACAA medical certification. It is not individual medical advice, and it does not promise that anyone will be found fit. ClinoTrend issues Class 2 and Class 4 medicals only."},{t:"h2",x:"The short answer",id:"the-short-answer"},{t:"p",x:"A designated examiner takes your history, examines you, and records the findings on the SACAA Aviation Medical Report, form CA 67-02(a). At this practice the on-site tests are a resting ECG, vision testing, audiometry and urine screening, as already stated on the [aviation medicals page](/aviation-medicals/). Further tests are added only when they are needed. If you meet the standards and no further reports are required, the certificate can usually be issued on the day. That is not a promise for every case."},{t:"h2",x:"Before you arrive",id:"before-you-arrive"},{t:"p",x:"Book the class that matches your licence: Class 2 for most student and private pilots, Class 4 for many cabin crew and recreational licences. Complete the [SACAA application form](/sacaa-form/) before you arrive. It is sent only to the practice. Bring proof of identity, your licence and current certificate if you have them, a list of medicines, and your glasses or contact lenses."},{t:"p",x:"The full packing list and directions sit in the [Midrand and Johannesburg guide](/blog/aviation-medical-midrand-johannesburg/). For a preparation checklist, including what to do the day before, see [how to prepare for a SACAA aviation medical](/blog/how-to-prepare-for-a-sacaa-aviation-medical/). [Book online](/book/), or call 011 568 7979 or WhatsApp 078 255 1405."},{t:"h2",x:"History and examination",id:"history-and-examination"},{t:"p",x:"Regulation 67.00.7 requires you to give the examiner your medical history and to sign a declaration that the information is accurate, complete and true. Form CA 67-02(a) records height, mass and body mass index, seated blood pressure, resting pulse, and the examination findings. Tell the examiner about medicines, operations, hospital visits and any condition you are being treated for, including pharmacy products."},{t:"p",x:"An honest history is not a trap. It is how the examiner decides whether the on-site tests are enough, or whether a report is needed. If more information is required, the usual next step is a deferral, which is explained in [what happens if a medical is deferred](/blog/aviation-medical-deferred-what-next/)."},{t:"h2",x:"Tests done on site at ClinoTrend",id:"tests-done-on-site-at-clinotrend"},{t:"p",x:"On the aviation medicals page, this practice lists four tests done on site:"},{t:"ul",items:["a resting ECG","vision testing","a hearing test (audiometry)","urine screening"]},{t:"p",x:"Those are the tests you should expect at a Class 2 or Class 4 visit here. If something different applies, the practice will tell you when you book. Colour perception is recorded as part of the visual examination on form CA 67-02(a), usually with pseudo-isochromatic plates. See [SACAA pilot eyesight and colour vision](/blog/sacaa-pilot-eyesight-colour-vision/) for that part of the exam."},{t:"h2",x:"Tests that are not always done here",id:"tests-that-are-not-always-done-here"},{t:"p",x:"Form CA 67-02(a) also has fields for a stress (exercise) ECG, a lung function test, a lipogram and a chest X-ray. Those are special investigations. They are used when class, age or history requires them, or when a SACAA protocol asks for them. They are not automatic for every visit, and this article does not set a rule for when a chest X-ray or a stress ECG is done. If one is needed, including at a first medical, the examiner will tell you, and will say whether it is done on site or referred. We will tell you when you book if something extra is expected."},{t:"p",x:"Aviation medicals start from R1,500. Extra tests or reports are added only if they are needed. The fee is confirmed when you book. See [how much a SACAA aviation medical costs](/blog/aviation-medical-cost-south-africa/)."},{t:"h2",x:"Class 1 and Class 3 are different visits",id:"class-1-and-class-3-are-different-visits"},{t:"p",x:"Class 1 (commercial and airline transport pilots) and Class 3 (air traffic services) must be done by a Senior Designated Aviation Medical Examiner. Dr A.O. Ndhlovu is a Regular DAME (MR 336) and issues Class 2 and Class 4 only. ClinoTrend does not offer Class 1 or Class 3 bookings. If you need Class 1, read [SACAA Class 1 medical: who needs it, and a Senior DAME](/blog/sacaa-class-1-medical-senior-dame/) and use the official list on the [SACAA Aviation Medicine page](https://www.caa.co.za/industry-information/aviation-medicine/)."},{t:"h2",x:"After the exam",id:"after-the-exam"},{t:"p",x:"If you meet the standards and no further reports are needed, the certificate can usually be issued at the end of the examination. SACAA procedure AM007 describes two copies with the same serial number: the yellow copy goes to SACAA and you keep the white copy with you while flying. If more information is needed, the examiner may defer the certificate, or issue it with a limitation or a shorter validity under regulation 67.00.6(5)."},{t:"p",x:"Ask the practice how long to allow when you book. A single time range is not published here, because the visit can be shorter or longer depending on the class and on whether further tests are needed."},{t:"p",x:"Ready to book a Class 2 or Class 4 medical? Complete the [SACAA form](/sacaa-form/), then [choose a time](/book/). Or call 011 568 7979 or WhatsApp 078 255 1405."},{t:"cta",x:"Book your Class 2 or Class 4 medical"}],faq:[{q:"What tests are done at an aviation medical?",a:"A history and physical examination, and, at ClinoTrend, a resting ECG, vision testing, a hearing test and urine screening on site. Extra tests are added only if they are required for your class, age or history."},{q:"Do I always need an ECG?",a:"A resting ECG is done on site at this practice for Class 2 and Class 4 visits. If something different applies, the practice will tell you when you book."},{q:"Do I need a chest X-ray?",a:"Not automatically. A chest X-ray, exercise ECG or other investigation is added only if it is needed. The examiner will tell you, including whether it is done on site or referred. We will tell you when you book if something extra is expected."},{q:"How long does it take?",a:"Ask when you book. The time depends on the class and on whether further tests are needed."},{q:"Will I get my certificate the same day?",a:"Usually, if no further reports are needed. That is not a promise."},{q:"Can ClinoTrend do a Class 1 medical?",a:"No. Class 1 and Class 3 need a Senior DAME. See the Class 1 guide and the [DAME post](/blog/sacaa-medical-examiners-dame/)."}],sources:[e.form,e.application,e.validityReg,e.am007,e.avmed,e.register]},p={slug:"aviation-medical-cost-south-africa",title:"SACAA Aviation Medical Cost in South Africa | ClinoTrend",h1:"How much does a SACAA aviation medical cost in South Africa?",description:"What a SACAA aviation medical costs, what the starting fee includes, and why Class 1 visits, extra reports and further tests can change the total.",excerpt:"What a SACAA aviation medical costs at ClinoTrend: the starting fee from R1,500, what may be included, and why extra tests or a Class 1 visit can change the total.",keyword:"how much is an aviation medical",question:"How much does a SACAA aviation medical cost in South Africa?",answer:"At ClinoTrend, aviation medicals start from R1,500. The starting fee is confirmed when you book. Extra tests or specialist reports are added only if they are needed for your class, age or history. Class 1 medicals are done by a Senior DAME at another practice, so their fees are separate.",facts:["Aviation medicals at ClinoTrend start from R1,500, for Class 2 and for Class 4. The fee is confirmed when you book.","Extra tests or reports are added only if they are needed for your class, age or history.","Class 1 medicals are done by a Senior DAME at another practice. This practice does not quote that fee."],secondary:["how much is an aviation medical exam","how much is a class 1 aviation medical","aviation medical cost","class 2 medical certificate cost"],published:"2026-11-18",updated:"2026-11-18",status:"approved",tag:"Cost",body:[{t:"p",x:"This page is about fees at this practice for Class 2 and Class 4 medicals. It is not a price list for every DAME in South Africa, and it is not a quote for a Class 1 visit."},{t:"h2",x:"The short answer",id:"the-short-answer"},{t:"p",x:"Aviation medicals start from R1,500, and the fee is confirmed when you book. Extra tests or reports are added only if the doctor finds they are needed during the medical. Payment by EFT or card is required at the time of your visit. The practice accepts most medical aids and charges medical aid rates. Self-pay patients receive a quote before treatment. Bring your medical aid card if you use one."},{t:"p",x:"For location, parking and what to bring, use the [Midrand and Johannesburg guide](/blog/aviation-medical-midrand-johannesburg/). The service page at [/aviation-medicals/cost/](/aviation-medicals/cost/) also covers the starting fee. This article is the dedicated cost guide for people comparing fees nationally."},{t:"h2",x:"What the starting fee is meant to include",id:"what-the-starting-fee-is-meant-to-includ"},{t:"p",x:"The starting fee is meant to cover the examination and the on-site tests listed on the [aviation medicals page](/aviation-medicals/): a resting ECG, vision testing, a hearing test and urine screening. Extra tests, specialist reports and investigations that are referred out are not part of that starting figure. If your visit needs only the examination and those on-site tests, the starting fee is the figure to plan around, once it has been confirmed when you book."},{t:"h2",x:"What can change the total",id:"what-can-change-the-total"},{t:"p",x:"The total can be higher than the starting fee when extra tests or specialist reports are needed. That can happen at a first medical, or at a renewal, if your history or the examination findings require them. Examples include a test that is referred out, or a report from a physician, cardiologist or ophthalmologist. This article does not invent add-on prices for those items. You will be told if something extra is needed, and the fee is confirmed when you book or when the extra work is identified."},{t:"p",x:"A straightforward renewal with no further tests is not always the same visit as a first medical with outstanding reports. Class 2 and Class 4 medicals at this practice both start from R1,500. The fee for your visit is confirmed when you book."},{t:"h2",x:"Class 1 and Class 3 fees",id:"class-1-and-class-3-fees"},{t:"p",x:`ClinoTrend does not issue Class 1 or Class 3 medicals. Those visits are done by a Senior DAME. Their fees are set by that examiner, not by this practice, and this page does not quote another clinic's Class 1 fee. If you are searching "how much is a class 1 aviation medical", read [SACAA Class 1 medical: who needs it, and a Senior DAME](/blog/sacaa-class-1-medical-senior-dame/) and use the official Senior DAME list on the [SACAA Aviation Medicine page](https://www.caa.co.za/industry-information/aviation-medicine/).`},{t:"h2",x:"Medical aid",id:"medical-aid"},{t:"p",x:"Medical aid cover differs between services and plans. Please check with the practice before your visit and bring your medical aid card. Self-pay patients receive a quote before treatment. That wording follows the site FAQ. It is not a promise that every plan will pay the full fee."},{t:"h2",x:"How to get a confirmed figure",id:"how-to-get-a-confirmed-figure"},{t:"p",x:"[Book a Class 2 or Class 4 medical](/book/), or call 011 568 7979 or WhatsApp 078 255 1405 and say which class you need. For group bookings for a flight school, email info@clinotrend-health.co.za. The practice is at Grand Central Airport, Gate 2, Office TG6B, Midrand, and is by appointment only. If a certificate is later deferred for reports, ask the practice about the fee; we will tell you when you book, or when the extra work is identified."},{t:"cta",x:"Get a confirmed fee, or book a Class 2 or Class 4 medical"}],faq:[{q:"How much does an aviation medical cost at ClinoTrend?",a:"Aviation medicals start from R1,500. The fee is confirmed when you book. Extra tests or reports are added only if they are needed."},{q:"Is a Class 4 cheaper than a Class 2?",a:"Both Class 2 and Class 4 medicals at this practice start from R1,500. The fee for your visit is confirmed when you book."},{q:"Does medical aid pay for an aviation medical?",a:"Cover differs between services and plans. Check with the practice before you come, and bring your card."},{q:"Why was I quoted more than the starting fee?",a:"Extra tests or reports may have been needed for your class, age or history."},{q:"How much is a Class 1 medical in South Africa?",a:"It depends on the Senior DAME. ClinoTrend does not issue Class 1 and does not quote that fee."},{q:"Do I pay if the certificate is deferred?",a:"Ask the practice about the fee if a certificate is deferred for reports. We will tell you when you book, or when the extra work is identified."}],sources:[e.avmed,e.register]},f={slug:"sacaa-class-1-medical-senior-dame",title:"SACAA Class 1 Medical and Senior DAMEs | ClinoTrend",h1:"SACAA Class 1 medical: who needs it, how long it lasts, and who can issue it",description:"Who needs a SACAA Class 1 medical, that only a Senior DAME can issue it, and how to use the official examiner list. ClinoTrend issues Class 2 and 4 only.",excerpt:"Who needs a SACAA Class 1 medical, why only a Senior DAME can issue it, and how to use the official examiner list. ClinoTrend issues Class 2 and 4 only.",keyword:"sacaa class 1 medical",question:"Who needs a SACAA Class 1 medical, and who can issue it?",answer:"A SACAA Class 1 medical is the certificate commercial and airline transport pilots need. In South Africa only a Senior Designated Aviation Medical Examiner can issue it. A Regular DAME, including Dr A.O. Ndhlovu at ClinoTrend, issues Class 2 and Class 4 medicals only. Use the SACAA Senior DAME list to find the right examiner.",facts:["A SACAA Class 1 medical can be issued only by a Senior Designated Aviation Medical Examiner.","Dr A.O. Ndhlovu is a Regular DAME, MR 336, and issues Class 2 and Class 4 medicals only.","Use the official Senior DAME list on the SACAA Aviation Medicine page to find the right examiner."],secondary:["sacaa class 1 medical requirements","class 1 medical certificate south africa","class 1 medical validity","cpl medical requirements south africa"],published:"2026-11-18",updated:"2026-11-18",status:"approved",tag:"Class 1",body:[{t:"p",x:"This is an educational guide, not a service page. ClinoTrend does not offer Class 1 or Class 3 bookings."},{t:"h2",x:"The short answer",id:"the-short-answer"},{t:"p",x:"If you need a Class 1 medical, you need a Senior DAME. That is stated on the [SACAA Aviation Medicine page](https://www.caa.co.za/industry-information/aviation-medicine/) and on this practice's [aviation medicals page](/aviation-medicals/). Regular DAMEs are authorised for Class 2 and Class 4. Senior DAMEs are authorised for Class 1, 2, 3 and 4. For the wider class table, see [SACAA aviation medical classes explained](/blog/sacaa-medical-classes-explained/). For how to check an examiner, see [SACAA medical examiners](/blog/sacaa-medical-examiners-dame/)."},{t:"h2",x:"Who needs Class 1",id:"who-needs-class-1"},{t:"p",x:"The SACAA Aviation Medicine page describes Class I medical certificate holders as including airline transport and commercial pilots. The amended Part 67 regulation 67.00.2, on classes of medical certificates, is the regulation to check for the official licence list. This article does not invent extra licence types. If you are applying for a commercial pilot licence or an airline transport pilot licence, you should expect to need Class 1, and you should confirm that against the official table and your licensing file."},{t:"p",x:"A valid Class 1 certificate is deemed to cover Class 2 and Class 4 privileges, under regulation 67.00.2. The reverse is not true: a Class 2 certificate does not stand in for Class 1."},{t:"h2",x:"Why a Regular DAME cannot do it",id:"why-a-regular-dame-cannot-do-it"},{t:"p",x:"The Director designates examiners in two categories that matter here. Regular Designated Aviation Medical Examiners may examine for and issue Class 2 and Class 4. Senior Designated Aviation Medical Examiners may examine for and issue Class 1, 2, 3 and 4. Dr A.O. Ndhlovu is listed as a Regular DAME, MR 336, at Grand Central Airport, Midrand. He cannot issue a Class 1 medical. Please do not book a Class 1 slot here; there is not one."},{t:"h2",x:"How to find a Senior DAME",id:"how-to-find-a-senior-dame"},{t:"p",x:"Open the [SACAA Aviation Medicine page](https://www.caa.co.za/industry-information/aviation-medicine/) and use the current list of Senior Designated Aviation Medical Examiners. The exact PDF address on that page can change, so this article links the page rather than a file that may go stale. Check that the examiner is on the current Senior list, and is designated for the class you need, before you book."},{t:"p",x:"If you are a student or a private pilot now, you can still do your Class 2 medical at ClinoTrend. When you later need Class 1 for commercial training or a professional licence, you move to a Senior DAME. Bring your last certificate and any reports with you."},{t:"h2",x:"Validity, carefully",id:"validity-carefully"},{t:"p",x:"Class 1 validity is set in Part 67, regulation 67.00.6(1). This practice follows the regulation, as it does for Class 2 and Class 4 on the rest of the site. Older SACAA FAQ pages have used wording that does not always match the regulation. In outline, a Class 1 certificate is issued for:"},{t:"ul",items:["12 months, where the applicant is less than 40 on the date it is issued","6 months, for an airline transport pilot in single-crew commercial air transport operations, where the applicant is 40 or more","12 months, for an airline transport pilot in multi-crew commercial air transport operations, where the applicant is 40 or more but less than 60","12 months, for a commercial pilot, where the applicant is 40 or more but less than 60","6 months, for the pilots described in those last two bullets, where the applicant is 60 or more"]},{t:"p",x:"The periods are calculated from the last day of the calendar month in which the certificate is issued. Regulation 67.00.6(2) also sets follow-up conditions for some Class 1 holders aged 40 or more. Do not mix FAA, DGCA or EASA periods into this table."},{t:"h2",x:"What ClinoTrend can still help with",id:"what-clinotrend-can-still-help-with"},{t:"p",x:"ClinoTrend remains the right place for Class 2 and Class 4 medicals: student and private pilots, many cabin crew, and recreational licences that sit under Class 4. For what happens at those visits, see [what is included in a SACAA aviation medical](/blog/what-is-included-in-a-sacaa-aviation-medical/). [Book a Class 2 or Class 4 medical](/book/), or call 011 568 7979 or WhatsApp 078 255 1405. If you need Class 1, use the SACAA Senior DAME list, not this booking form."},{t:"cta",x:"Book a Class 2 or Class 4 medical"}],faq:[{q:"Can ClinoTrend do my Class 1 medical?",a:"No. You need a Senior DAME. Use the official list on the SACAA Aviation Medicine page."},{q:"Who needs a Class 1 medical in South Africa?",a:"Commercial and airline transport pilots, as described on the SACAA Aviation Medicine page. Confirm your licence against the official class table."},{q:"How long is a SACAA Class 1 medical valid?",a:"Part 67, regulation 67.00.6(1), sets periods of 12 or 6 months depending on age and the type of operation. Older FAQ pages may differ; this practice follows the regulation."},{q:"What is the difference between Class 1 and Class 2?",a:"The licence it supports, the examiner who can issue it, and some of the standards and intervals. A Regular DAME cannot issue Class 1."},{q:"I already had a Class 2 here. What now?",a:"Book a Senior DAME for Class 1. Bring your last certificate and any reports."},{q:"How much is a Class 1 medical?",a:"Set by that examiner. This practice does not quote it."}],sources:[e.avmed,e.classesReg,e.validityReg,e.faq,e.register]},y={slug:"sacaa-pilot-eyesight-colour-vision",title:"SACAA Pilot Eyesight and Colour Vision | ClinoTrend",h1:"SACAA pilot eyesight and colour vision: what the standards say, and what happens if you do not meet them at first",description:"What SACAA requires for vision and colour perception, how the first colour-plate test works, and why a fail is not always the end of a flying career.",excerpt:"What SACAA aviation medicals include for vision and colour perception, how the first colour-plate test works, and why this page does not quote unofficial numeric limits.",keyword:"colour vision test pilot south africa",question:"What are the SACAA eyesight and colour vision requirements for pilots?",answer:"SACAA aviation medicals include vision and colour-perception tests. Many people who wear glasses can still meet the standard. If you do not pass the first colour-plate test, that is not automatically the end: further testing may be required, and some restrictions can apply. Only the official standards and the examiner's assessment decide the outcome.",facts:["Vision testing is done on site at ClinoTrend for Class 2 and Class 4 medicals.","Form CA 67-02(a) records acuity, colour perception and contact-lens conditions (monofocal, non-tinted, spare spectacles).","This article does not publish acuity or colour-test numbers, because a complete official CATS 67 visual clause was not opened to quote from."],secondary:["pilot eyesight requirements south africa","colour vision test pilot south africa","can you be a pilot with glasses","ishihara test pilot"],published:"2026-11-18",updated:"2026-11-18",status:"approved",tag:"Vision",body:[{t:"p",x:"This is general information, not a personal assessment, and it does not promise fitness. This article does not publish acuity, colour-vision or test-score numbers, because a complete official CATS 67 visual-requirement clause was not opened to quote from, and unofficial clinic tables are not the law."},{t:"h2",x:"The short answer",id:"the-short-answer"},{t:"p",x:"Vision and colour perception are part of every SACAA aviation medical. At ClinoTrend, vision testing is done on site, as stated on the [aviation medicals page](/aviation-medicals/). Form CA 67-02(a) records visual acuity (with and without correction, each eye and both eyes, for distant, intermediate and near vision), colour perception, visual fields, ocular muscle balance and other eye findings. The examiner applies the official standard to you. A blog post cannot tell you whether you will meet it."},{t:"h2",x:"Distance, near and intermediate vision",id:"distance-near-and-intermediate-vision"},{t:"p",x:"The visual standard sits in Part 67 and the associated technical standards. We have opened form CA 67-02(a) and the summarised medical protocols list, but we have not opened a complete official CATS 67 visual-requirement clause that we can quote as a numeric limit. This article therefore does not publish acuity figures such as a 6/6 or 6/9 standard, or any unofficial number copied from another clinic's website. Those figures, if they appear elsewhere, must be checked against the official text."},{t:"p",x:"What we can say from the form itself is that both uncorrected and corrected acuity are recorded, for each eye and for both eyes, at distant, intermediate and near distances. Correction, if you use it, is part of the examination, not a surprise."},{t:"h2",x:"Glasses and contact lenses",id:"glasses-and-contact-lenses"},{t:"p",x:"Many people who wear glasses or contact lenses can still meet the standard, if the corrected vision required by the official text is met. That is not a promise that every prescription will be accepted, and it is not a promise of fitness. Form CA 67-02(a), which we opened, already notes conditions for contact-lens use: monofocal, non-tinted lenses, and spare spectacles. Bring your current glasses or lenses, and a spare pair if you have one. A recent optometrist or ophthalmologist report can help, but it does not replace the aviation medical."},{t:"h2",x:"Colour perception",id:"colour-perception"},{t:"p",x:"Colour perception is recorded on the same form, usually first with pseudo-isochromatic plates (often called an Ishihara test). If you do not pass that first test, that is not automatically the end of a flying career. Further testing may be required, and some restrictions can apply, depending on the official protocol and the results. The examiner will tell you whether any further colour assessment is done on site at this practice or by referral. This article does not paste pass marks, plate counts or clinic-specific colour-test thresholds, including figures that appear on unofficial DAME websites. Those pages are not the law."},{t:"h2",x:"If you do not meet the standard at first",id:"if-you-do-not-meet-the-standard-at-first"},{t:"p",x:"If a finding needs more information, the usual first step is a deferral or a limitation, not a lifetime ban. Complex cases can be referred to the Aeromedical Committee. That process is explained in [what happens if a medical is deferred](/blog/aviation-medical-deferred-what-next/) and in the companion article [what can defer or limit a SACAA medical](/blog/what-can-defer-or-limit-a-sacaa-medical/). This page does not promise that you will still obtain any particular licence."},{t:"h2",x:"What happens at ClinoTrend",id:"what-happens-at-clinotrend"},{t:"p",x:"Vision testing is on site for Class 2 and Class 4 medicals. Class 1 eye standards, and the issue of a Class 1 certificate, sit with a Senior DAME, not with this practice. See [SACAA Class 1 medical and Senior DAMEs](/blog/sacaa-class-1-medical-senior-dame/). If you are booking a Class 2 or Class 4 medical, [book online](/book/), or call 011 568 7979 or WhatsApp 078 255 1405, and bring your glasses or lenses and any recent eye reports."},{t:"cta",x:"Book your Class 2 or Class 4 medical"}],faq:[{q:"Can I be a pilot if I wear glasses?",a:"Many people can, if the corrected official standard is met. That is not a promise of fitness. Only the examination can apply that standard to you."},{q:"What is the SACAA eyesight requirement?",a:"See Part 67 and the technical standards. This article does not publish a numeric limit, because a complete official CATS 67 visual clause was not opened to quote from."},{q:"What if I fail the Ishihara plates?",a:"Further testing may be required. The examiner will tell you whether that is done here or by referral. This page does not predict the result."},{q:"Can I be a commercial pilot with a colour-vision deficiency?",a:"Sometimes, with limits, depending on the official protocol and the test results. This page does not promise an outcome."},{q:"Should I get an eye test before my medical?",a:"It can be useful to bring a recent report. It does not replace the aviation medical."},{q:"Does ClinoTrend do Class 1 eye standards?",a:"Class 1 is issued only by a Senior DAME. We do Class 2 and Class 4 vision testing here."}],sources:[e.form,e.avmed,{...e.protocols,name:"SACAA Summarised Medical Protocols in line with Part 67 (effective 16 November 2021), item 47 (PRK and LASIK)"}]},g={slug:"blood-pressure-diabetes-medication-sacaa-medical",title:"Blood Pressure, Diabetes and Medicines | ClinoTrend",h1:"Blood pressure, diabetes and medicines: what to tell your SACAA examiner",description:"How high blood pressure, diabetes and everyday medicines are handled at a SACAA aviation medical, and why you must declare them. Not personal advice.",excerpt:"How high blood pressure, diabetes and everyday medicines are handled at a SACAA medical, and why every diagnosis and medicine must be declared. Not personal advice.",keyword:"can you be a pilot with high blood pressure",question:"Can you fly with high blood pressure, diabetes or everyday medicines at a SACAA medical?",answer:"High blood pressure, diabetes and many everyday medicines are not an automatic no at a SACAA medical, and they are not an automatic yes either. Declare every medicine and every diagnosis. The examiner applies the official protocols to your case, and may need reports from your own doctor before a certificate can be issued.",facts:["High blood pressure, diabetes and many everyday medicines are not an automatic no, and not an automatic yes.","Declare every medicine and every diagnosis. The examiner applies the official protocols and may need reports.","This article does not publish blood-pressure or glucose numbers."],secondary:["hypertension aviation medical","blood pressure aviation medical","diabetes aviation medical","can you be a pilot with diabetes"],published:"2026-11-18",updated:"2026-11-18",status:"approved",tag:"Conditions",body:[{t:"p",x:"This is general information, not individual medical advice, and it does not promise fitness. This article does not publish blood-pressure or glucose numbers."},{t:"h2",x:"The short answer",id:"the-short-answer"},{t:"p",x:"These are among the most common questions before a first medical, or before a renewal after a new diagnosis. The honest answer is that compatibility depends on the condition, how it is treated, the official protocol, and the findings on the day. A blog post cannot decide your case. If more information is needed, the usual next step is a deferral, explained in [what happens if a medical is deferred](/blog/aviation-medical-deferred-what-next/)."},{t:"h2",x:"Always declare",id:"always-declare"},{t:"p",x:'Regulation 67.00.7 and form CA 67-02(a) require a complete history, including medicines. That includes prescription medicines, pharmacy products and anything you take regularly. Incomplete disclosure is itself a problem for certification. It is also a poor way to start a medical relationship with an examiner. Do not start, stop or hide a medicine in order to "pass". Ask your treating doctor before you change anything, and tell the examiner what you take.'},{t:"h2",x:"Blood pressure",id:"blood-pressure"},{t:"p",x:"Seated blood pressure is recorded on form CA 67-02(a). The summarised SACAA medical protocols, dated 16 November 2021, which we opened, include a named protocol for hypertension (item 27). That protocol list does not, in the summary we opened, give a numeric cut-off that this article can quote. Unofficial pages, and many FAA blogs, publish figures that must not be copied here."},{t:"p",x:"If your blood pressure needs attention, the examiner may ask for a report from your own doctor, further readings, or other investigations listed in the protocol. Controlled high blood pressure can be compatible with certification in some cases. Uncontrolled high blood pressure, or a related complication, may lead to a deferral or a finding that more work is needed. Only the examination can decide."},{t:"h2",x:"Diabetes",id:"diabetes"},{t:"p",x:`SACAA distinguishes types of diabetes and types of treatment. The summarised protocols include a Type II diabetes protocol (item 33). The [SACAA Aviation Medicine page](https://www.caa.co.za/industry-information/aviation-medicine/), which we opened, discusses significant incapacitation risk at the initial examination, and gives Type 1 diabetes as an example of a condition that is screened out at that stage. That is SACAA's wording, not a clinic slogan, and it is not a personal prediction for every applicant. This article does not say "Type 1 can never fly" as a blanket clinic rule, and it does not say "Type 2 is always fine".`},{t:"p",x:"If you have diabetes, bring recent reports from your treating doctor. The examiner applies the current protocol to your case, and may defer the certificate for further information or a committee review. Glucose numbers are not published here."},{t:"h2",x:"Medicines",id:"medicines"},{t:"p",x:"Some medicines are acceptable in aviation, some need a waiting period after a change, and some are not compatible with the duties of the certificate. This page does not publish a named allowed-list or a banned list, because no short official list was opened that can be reprinted here in full. The default advice is simple: bring the box or a written list, including doses, and do not start or stop a medicine to influence the exam."},{t:"p",x:"If you take a medicine for mood, sleep, attention, pain or another long-term condition, declare it. The next article, [what can defer or limit a SACAA medical](/blog/what-can-defer-or-limit-a-sacaa-medical/), explains how those findings are handled in general terms."},{t:"h2",x:"What ClinoTrend will do",id:"what-clinotrend-will-do"},{t:"p",x:"At a Class 2 or Class 4 visit, the examiner takes the history, examines you, and decides whether the on-site tests are enough. If reports are needed, you will be told clearly. The practice cannot promise a certificate in advance. If you already know a report will be useful, ask when you [book](/book/), or call 011 568 7979 or WhatsApp 078 255 1405, and see [how to prepare for a SACAA aviation medical](/blog/how-to-prepare-for-a-sacaa-aviation-medical/)."},{t:"cta",x:"Book your Class 2 or Class 4 medical"}],faq:[{q:"Can I fly if I have high blood pressure?",a:"Sometimes, if it is controlled and the protocol is met. Only an examination can decide."},{q:"What blood pressure is acceptable?",a:"This article does not quote a figure. The examiner applies the current official protocol."},{q:"Can I be a pilot if I have diabetes?",a:"It depends on the type, the treatment and the protocol. This page does not promise an outcome."},{q:"Should I stop my medicine before the medical?",a:"No. Ask your treating doctor and tell the examiner."},{q:"Will I fail if I take antidepressants or other regular medicines?",a:"This page does not answer yes or no. Declare them. See the deferral and limits guide, and the deferred-medical post."},{q:"Can this be done at ClinoTrend?",a:"Class 2 and Class 4 medicals, yes. Complex cases may be deferred. Class 1 needs a Senior DAME."}],sources:[e.form,{...e.protocols,name:"SACAA Summarised Medical Protocols in line with Part 67 (effective 16 November 2021), item 33 (Diabetes Mellitus Type II)"},e.avmed,e.application]},A={slug:"what-can-defer-or-limit-a-sacaa-medical",title:"What Can Defer or Limit a SACAA Medical? | ClinoTrend",h1:"What can defer or limit a SACAA medical, and what that is not",description:"Medical conditions and findings that can defer or limit a SACAA certificate, how the Aeromedical Committee fits in, and why a blog cannot decide your case.",excerpt:"What can defer or limit a SACAA medical certificate, why a US-style disqualify list does not apply, and how this page sits next to the deferred-medical guide.",keyword:"what disqualifies you from a pilot medical",question:"What can defer or limit a SACAA medical certificate?",answer:"SACAA does not publish a simple fail list that a blog can apply to you. Some conditions must be declared and assessed under official protocols. The usual first step, if more information is needed, is a deferral or a limitation, not a lifetime ban. The Aeromedical Committee reviews complex cases. Only an examination can decide yours.",facts:["SACAA does not publish a simple fail list that a blog can apply to you.","The usual first step, if more information is needed, is a deferral or a limitation, not a lifetime ban.","This article is a companion to the deferred-medical process post, not a rewrite of it."],secondary:["what medical conditions prevent you from becoming a pilot","pilot disqualifying medical conditions","depression aviation medical","aviation medical failed"],published:"2026-11-18",updated:"2026-11-18",status:"approved",tag:"Deferral",body:[{t:"p",x:"This is a companion to [what happens if a medical is deferred](/blog/aviation-medical-deferred-what-next/), not a rewrite of that process guide."},{t:"h2",x:"The short answer",id:"the-short-answer"},{t:"p",x:"Three outcomes matter here, and they are not the same:"},{t:"ul",items:["A **deferral** means the certificate is not issued yet, because more information is needed.","A **limitation** means a certificate is issued, with a restriction on how you may exercise it, or with a shorter validity under regulation 67.00.6(5).","A finding that you are **unfit**, temporarily or for a longer period, is a decision after the information is in, not a shortcut a website can take."]},{t:"p",x:'The deferred post explains the process, the paperwork and what you do next. This page explains why people search "what disqualifies you", and why that wording does not travel well from US sites into SACAA practice.'},{t:"h2",x:'Why "disqualify" is the wrong word here',id:"why-disqualify-is-the-wrong-word-here"},{t:"p",x:`US "disqualifying condition" lists, forum advice and FAA blogs are not Part 67. SACAA works through official protocols, the examiner's assessment, and, when needed, the Aeromedical Committee. Some conditions are difficult. Some are compatible once they are treated and documented. A complete fail list in a blog would be both incomplete and misleading, so this article does not offer one.`},{t:"h2",x:"Kinds of issues that often need more information",id:"kinds-of-issues-that-often-need-more-inf"},{t:"p",x:"The groups below are a map, not a catalogue of bans. Each is the sort of finding that may need a report, a further test, or a committee review. The summarised SACAA medical protocols, dated 16 November 2021, which we opened, include named items in several of these areas (for example hypertension, Type II diabetes, mood disorder, and PRK/LASIK). That list is not reproduced in full here."},{t:"ul",items:["**Heart and blood pressure.** A history of raised blood pressure, a heart procedure, or an abnormal ECG often needs a report or a protocol review. See [blood pressure, diabetes and medicines](/blog/blood-pressure-diabetes-medication-sacaa-medical/).","**Metabolic and endocrine conditions**, including diabetes. The type, the treatment and the protocol all matter. There is no automatic yes or no in this article.","**Mental health**, including symptoms of depression, anxiety or related conditions, and the medicines used to treat them. Declare them. This is not a statement that you cannot fly if you have ever been depressed.","**Neurological findings**, including blackouts, seizures or unexplained loss of consciousness, which typically need specialist input.","**Vision and hearing.** Uncorrected or corrected standards, colour perception and hearing tests can lead to a further assessment or a limitation. See [SACAA pilot eyesight and colour vision](/blog/sacaa-pilot-eyesight-colour-vision/).","**Sleep**, including diagnosed sleep apnoea, which may need treatment evidence before a certificate is issued or renewed.","**Substance use.** Regulation 67.00.13 deals with the use of psychoactive substances. Honest disclosure, and the official process, is the route. This article is not a drugs-and-alcohol policy document."]},{t:"h2",x:"Mental health, carefully",id:"mental-health-carefully"},{t:"p",x:"Form CA 67-02(a) asks about mental health history and medicines. Declare symptoms and treatment. The examiner may need a report from your treating practitioner. Some cases are reviewed by the Aeromedical Committee. This page does not name or endorse a particular peer-support programme. The deferred post is the place to start if a certificate is held back for a report."},{t:"h2",x:"What you should do before you book",id:"what-you-should-do-before-you-book"},{t:"p",x:'Bring recent reports, a medicine list and, if you have them, letters from your treating doctors. Do not hide history. Do not stop a medicine to "pass". Do not expect this practice to tell you in advance whether you will be found fit. [How to prepare for a SACAA aviation medical](/blog/how-to-prepare-for-a-sacaa-aviation-medical/) has the practical checklist.'},{t:"h2",x:"How ClinoTrend handles this",id:"how-clinotrend-handles-this"},{t:"p",x:"If you meet the standards and no further reports are needed, the certificate can usually be issued on the day. That is not a promise. If something else is needed, you will be told clearly. [Book a Class 2 or Class 4 medical](/book/), or call 011 568 7979 or WhatsApp 078 255 1405. Class 1 and Class 3 medicals need a Senior DAME."},{t:"p",x:"The [SACAA Aviation Medicine page](https://www.caa.co.za/industry-information/aviation-medicine/) describes the Aeromedical Committee and appeals to the Director. Use that official page for the current process, not a summary on a blog."},{t:"cta",x:"Book a Class 2 or Class 4 medical, and bring your reports"}],faq:[{q:"What disqualifies you from a SACAA medical?",a:"There is no blog list that can decide your case. Some conditions need reports or a committee review."},{q:"If I am deferred, have I failed?",a:"No. A deferral means more information is needed. See the deferred-medical post."},{q:"Can I fly with a limitation on my certificate?",a:"You can exercise the privileges the limitation still allows. Read the certificate, and stay within it."},{q:"Should I hide a condition so I can pass?",a:"No. Incomplete disclosure is itself a problem."},{q:"Can I appeal?",a:"The SACAA Aviation Medicine page describes appeals to the Director. Follow that official process."},{q:"Can ClinoTrend tell me in advance if I will pass?",a:"No. We can tell you what to bring."}],sources:[e.avmed,e.validityReg,e.form,e.protocols,e.substance]},w={slug:"aviation-medical-pretoria-centurion",title:"Aviation Medical Near Pretoria and Centurion | ClinoTrend",h1:"Aviation medical near Pretoria and Centurion: a Class 2 or Class 4 medical at Grand Central, Midrand",description:"Looking for an aviation medical in Pretoria or Centurion? Dr A.O. Ndhlovu does SACAA Class 2 and Class 4 medicals at Grand Central Airport in Midrand.",excerpt:"There is no ClinoTrend branch in Pretoria or Centurion. Class 2 and Class 4 medicals are done at Grand Central Airport in Midrand, by appointment.",keyword:"aviation medical pretoria",question:"Where can I get an aviation medical near Pretoria or Centurion?",answer:"There is no ClinoTrend branch in Pretoria or Centurion. Dr A.O. Ndhlovu does SACAA Class 2 and Class 4 medicals at Grand Central Airport in Midrand, on the N1 between Pretoria and Johannesburg. You can drive from Centurion or Pretoria, or fly in to FAGC. Book before you come; the practice is by appointment only.",facts:["The practice is at Gate 2, Office TG6B, Grand Central Airport, 3 New Road, Midrand, 1685. There is no Pretoria or Centurion branch.","Opening times are 08h00 to 16h30 Monday to Thursday, and Friday 08h00 to 14h30, by appointment only.","Aviation medicals start from R1,500. Class 1 and Class 3 need a Senior DAME."],secondary:["aviation medical examiner pretoria","aviation medical centurion","aviation medical examiner centurion","flight medical pretoria"],published:"2026-11-18",updated:"2026-11-18",status:"approved",tag:"Location",body:[{t:"p",x:"This is a location guide for the northern Gauteng searches. The full Midrand checklist lives in the [Midrand and Johannesburg post](/blog/aviation-medical-midrand-johannesburg/). Service pages for [Pretoria](/aviation-medicals/pretoria/) and [Centurion](/aviation-medicals/centurion/) sit alongside this article and should be used for the short local answer."},{t:"h2",x:"The short answer",id:"the-short-answer"},{t:"p",x:"The practice address is Main Terminal Building, Gate 2, Office TG6B, Grand Central Airport, 3 New Road, Midrand, 1685. There is no Pretoria clinic and no Centurion clinic. Dr A.O. Ndhlovu is a SACAA Regular DAME, MR 336, and issues Class 2 and Class 4 medicals only."},{t:"h2",x:"How to get there from Pretoria and Centurion",id:"how-to-get-there-from-pretoria-and-centu"},{t:"p",x:"Grand Central sits on the N1 corridor between Pretoria and Johannesburg, in Midrand. Most Pretoria drivers use the N14 and the N1. Most Centurion drivers take the N1 south to the New Road exit. The R101, the old Pretoria road, is an alternative when the N1 is busy."},{t:"p",x:o(["pretoriaCbd","centurion"])},{t:"p",x:"Car parking at the Grand Central terminal is boom-gated. Follow New Road to the airport and go to the Main Terminal Building, Gate 2. If you prefer to fly in, the aerodrome is FAGC, as described on the [aviation medicals page](/aviation-medicals/). Current directions are also on the [contact page](/contact/)."},{t:"h2",x:"What you can have done here",id:"what-you-can-have-done-here"},{t:"p",x:"Class 2 and Class 4 medicals only. Opening times are 08h00 to 16h30 Monday to Thursday, and Friday 08h00 to 14h30, by appointment only. Aviation medicals start from R1,500. The fee is confirmed when you book. Class 1 and Class 3 medicals need a Senior DAME; see [SACAA Class 1 medical and Senior DAMEs](/blog/sacaa-class-1-medical-senior-dame/). For what the visit includes, see [what is included in a SACAA aviation medical](/blog/what-is-included-in-a-sacaa-aviation-medical/). For fees, see [how much a SACAA aviation medical costs](/blog/aviation-medical-cost-south-africa/)."},{t:"h2",x:"What to bring, in brief",id:"what-to-bring-in-brief"},{t:"p",x:"Bring proof of identity, your completed [SACAA form](/sacaa-form/), your licence and last certificate if you have them, a medicine list, and your glasses or lenses. The full checklist is on the Midrand post and the aviation medicals page, so it is not copied in full here."},{t:"h2",x:"Other examiners in Pretoria",id:"other-examiners-in-pretoria"},{t:"p",x:"If you would rather see a DAME closer to your home or office, use the official Regular and Senior lists on the [SACAA Aviation Medicine page](https://www.caa.co.za/industry-information/aviation-medicine/). This page does not list or compare other practices, and it does not invent their hours."},{t:"p",x:'The Midrand post remains the right place for the full "what to bring" list and the Johannesburg-side directions. This post exists so that a search for Pretoria or Centurion reaches a clear, honest answer: the clinic is in Midrand, it is one practice, and you can book a Class 2 or Class 4 medical if that is the class you need.'},{t:"p",x:"If you are comparing fees, aviation medicals start from R1,500 and the figure is confirmed when you book. If you are comparing examiners, use the official SACAA lists rather than an unofficial directory. If you need Class 1, do not book here."},{t:"p",x:"Coming from Pretoria or Centurion? [Book a Class 2 or Class 4 medical](/book/) at Grand Central, or call 011 568 7979 or WhatsApp 078 255 1405. Walk-ins are not offered."},{t:"cta",x:"Book a Class 2 or Class 4 medical at Grand Central"}],faq:[{q:"Do you have a Pretoria or Centurion clinic?",a:"No. The practice is at Grand Central, Midrand."},{q:"Can I walk in from Pretoria?",a:"No. Book first."},{q:"Do you do Class 1 medicals?",a:"No. You need a Senior DAME."},{q:"How much does it cost?",a:"From R1,500, confirmed when you book."},{q:"Can I fly in to the medical?",a:"Yes, to FAGC, as described on the aviation medicals page."},{q:"How do I book?",a:"Online at the booking page, or by phone 011 568 7979 or WhatsApp 078 255 1405."}],sources:[e.avmed,e.register]},C={slug:"how-to-prepare-for-a-sacaa-aviation-medical",title:"How to Prepare for a SACAA Aviation Medical | ClinoTrend",h1:"How to prepare for a SACAA aviation medical, first time or renewal",description:"How to prepare for a SACAA Class 2 or Class 4 medical: what to bring, what to do the day before, and how to reduce the chance of a deferral.",excerpt:"How to prepare for a SACAA Class 2 or Class 4 medical: what to bring, what the aviation medicals page says about the night before, and how honest paperwork prevents most delays.",keyword:"how to prepare for aviation medical",question:"How do I prepare for a SACAA aviation medical?",answer:'Prepare for a SACAA medical by booking the right class, completing the form, gathering your ID, licence, last certificate and medicine list, and arriving rested. Do not start, stop or hide medicines to "pass". Honest paperwork and the right documents prevent most delays, not last-minute tricks.',facts:["Book the right class, complete the SACAA form, and bring ID, licence, last certificate, a medicine list and your glasses or lenses.","The aviation medicals page asks you to rest well and to avoid caffeine, tobacco and high-sugar meals beforehand, because they can affect urine and ECG results.","Do not start, stop or hide medicines to influence the exam."],secondary:["what to bring to aviation medical","aviation medical requirements","prepare for aviation medical exam","aviation medical checklist"],published:"2026-11-18",updated:"2026-11-18",status:"approved",tag:"Preparation",body:[{t:"p",x:"This is general information for Class 2 and Class 4 visits at ClinoTrend. It is not individual medical advice, and it does not promise an outcome of a certificate."},{t:"h2",x:"The short answer",id:"the-short-answer"},{t:"p",x:"A calm visit starts a week before, not in the car park. Book the class that matches your licence, complete the form, collect your documents, and arrive rested. For what happens in the room, see [what is included in a SACAA aviation medical](/blog/what-is-included-in-a-sacaa-aviation-medical/). For directions, use the [Midrand and Johannesburg guide](/blog/aviation-medical-midrand-johannesburg/)."},{t:"h2",x:"A week before",id:"a-week-before"},{t:"ol",items:["Book the correct class: Class 2 for most student and private pilots, Class 4 for many cabin crew and recreational licences. ClinoTrend does not do Class 1 or Class 3.","Complete the [SACAA application form](/sacaa-form/). It is sent only to the practice.","If you already know a specialist or GP report will be needed, request it now, rather than waiting to be deferred for it.","Put together proof of identity, your licence, your last certificate if you have one, a medicine list, and your glasses or lenses."]},{t:"h2",x:"The day before and the morning",id:"the-day-before-and-the-morning"},{t:"p",x:'The aviation medicals page asks you to rest well, and to avoid caffeine, tobacco and high-sugar meals beforehand, because they can affect urine and ECG results. Arrive 10 minutes early. This article does not add further "avoid" rules, and it does not ask for routine pre-visit blood tests unless your history already requires them or the practice has asked you to arrange them.'},{t:"p",x:"Do not start, stop or hide a medicine the night before in order to influence the exam. Ask your treating doctor before you change anything, and tell the examiner what you take."},{t:"h2",x:"What to bring",id:"what-to-bring"},{t:"ul",items:["Proof of identity (ID or passport)","Your completed SACAA form, if you have not already submitted it","Your licence and last medical certificate, if you have them","A list of medicines, including pharmacy products","Your glasses or contact lenses, and a spare pair if you have one","Your medical aid card, if you use one","Any recent specialist or optometrist reports that are relevant"]},{t:"p",x:"The full checklist is on the [aviation medicals page](/aviation-medicals/) and the Midrand post."},{t:"h2",x:"What not to do",id:"what-not-to-do"},{t:"p",x:"Do not conceal history. Incomplete disclosure is itself a problem. Do not arrive without a booking; the practice is by appointment only. Do not expect a Class 1 medical here. Do not invent a set of last-minute tricks. If you forget a document, including your last certificate, call 011 568 7979 or WhatsApp 078 255 1405 before you travel, and ask whether the visit can still go ahead. Bring proof of identity and your completed form in any event."},{t:"h2",x:"First medical versus renewal",id:"first-medical-versus-renewal"},{t:"p",x:"A first medical and a straightforward renewal use the same form and the same honesty rule. First-time student pilots may also want the [student pilot guide](/blog/student-pilot-medical-south-africa/). Renewal periods themselves are explained in the [validity post](/blog/class-2-medical-validity-by-age/). If something has changed in your health, say so, even if your last visit was uneventful."},{t:"p",x:"If a previous medical was deferred, bring the reports that were requested, and read [what happens if a medical is deferred](/blog/aviation-medical-deferred-what-next/) so you know the process. If you are travelling from Pretoria or Centurion, the [location guide](/blog/aviation-medical-pretoria-centurion/) has the Midrand address and booking path."},{t:"p",x:"When you are ready, complete the [form](/sacaa-form/) and [book a Class 2 or Class 4 medical](/book/), or call 011 568 7979 or WhatsApp 078 255 1405."},{t:"cta",x:"Complete the form and book your Class 2 or Class 4 medical"}],faq:[{q:"How do I prepare for my first aviation medical?",a:"Complete the form, gather your documents, rest, and bring a list of medicines."},{q:"Can coffee or energy drinks affect the results?",a:"The aviation medicals page says to avoid caffeine beforehand because it can affect urine and ECG results."},{q:"What if I forget my last certificate?",a:"Call before you travel and ask whether the visit can still go ahead. Bring proof of identity and your completed form in any event."},{q:"Should I have blood tests done first?",a:"Only if your history already requires them, or the practice asked you to. This article does not invent a routine panel."},{q:"I am renewing and nothing has changed. Do I still need the form?",a:"Yes."},{q:"How do I book?",a:"Online at the booking page, or by phone or WhatsApp."}],sources:[e.form]},b={slug:"foreign-licence-conversion-sacaa-medical",title:"Foreign Licence Conversion: The Medical Step | ClinoTrend",h1:"Converting a foreign pilot licence: what the SACAA medical involves",description:"What medical you need when converting a foreign licence to a SACAA licence, who can do the exam, and what to bring. This is not a full conversion guide.",excerpt:"The SACAA medical step when converting a foreign licence: which class you need, who can do the exam, and what to bring. This is not a full conversion guide.",keyword:"foreign licence conversion sacaa medical",question:"What medical do I need when converting a foreign pilot licence to a SACAA licence?",answer:"A foreign medical certificate does not replace a SACAA medical when the South African rules require one. The class you need follows the SACAA licence you are applying for, not the name of the foreign class. ClinoTrend can do Class 2 and Class 4 medicals. Class 1 conversions need a Senior DAME.",facts:["A foreign medical certificate does not replace a SACAA medical when the South African rules require one.","The class follows the SACAA licence you are applying for, not the name of the foreign class.","ClinoTrend can do Class 2 and Class 4 medicals. Class 1 conversions need a Senior DAME."],secondary:["faa medical conversion south africa","icao medical certificate south africa","convert foreign pilot licence south africa","sacaa medical for foreign licence"],published:"2026-11-18",updated:"2026-11-18",status:"approved",tag:"Conversion",body:[{t:"p",x:"This page covers the medical step only. It is not a conversion or validation manual for licences, exams or hours."},{t:"h2",x:"The short answer",id:"the-short-answer"},{t:"p",x:"If you are converting, or seeking to validate, a foreign licence in South Africa, the licensing process and the medical process are separate. This practice does the medical only, and only for Class 2 and Class 4. Licence exams, hour requirements and conversion forms sit with SACAA personnel licensing, not with a DAME blog post."},{t:"h2",x:"Licence process versus medical process",id:"licence-process-versus-medical-process"},{t:"p",x:"Use the current SACAA personnel licensing pages for conversion or validation of a foreign licence. The exact URLs on the SACAA site can change, so start from the Authority's public site and the personnel licensing section, rather than from a copied link that may go stale. This article does not guess a form number or a conversion checklist. Ask the licensing department which medical class your application requires, then book that class with an examiner who is designated for it."},{t:"h2",x:"Which class you are likely to need",id:"which-class-you-are-likely-to-need"},{t:"p",x:"The class follows the SACAA licence, not the name of your foreign medical (FAA first class, EASA class 1, and so on). In outline:"},{t:"ul",items:["A South African private pilot licence is usually supported by a Class 2 medical.","A commercial or airline transport licence is supported by a Class 1 medical, which only a Senior DAME can issue. See [SACAA Class 1 medical and Senior DAMEs](/blog/sacaa-class-1-medical-senior-dame/).","Cabin crew medicals are Class 4, as explained in the [cabin crew post](/blog/cabin-crew-medical-class-4-south-africa/)."]},{t:"p",x:"Confirm the class with the licensing department. Validation (temporary recognition of a foreign licence) and full conversion are not the same licensing process. For validation, regulation 67.00.10 allows the Director to recognise a foreign medical report, medical assessment or medical certificate issued by an appropriate authority. That recognition is a SACAA decision, not an automatic substitute for a South African medical. For conversion to a SACAA licence, ask the licensing department which SACAA medical class your application requires. This article does not treat first-issue medical rules as always applying to every conversion applicant; confirm the medical step when you apply."},{t:"h2",x:"What to bring",id:"what-to-bring"},{t:"ul",items:["Your foreign licence and last medical certificate","Your passport or other proof of identity","Any specialist reports and a medicine list","The completed [SACAA application form](/sacaa-form/)","Your last South African certificate, if you already have one"]},{t:"p",x:"[Book a Class 2 or Class 4 medical](/book/) only if that is the class your application requires. For a confirmed fee, which starts from R1,500, see [how much a SACAA aviation medical costs](/blog/aviation-medical-cost-south-africa/), or call 011 568 7979 or WhatsApp 078 255 1405."},{t:"h2",x:"What does not carry over automatically",id:"what-does-not-carry-over-automatically"},{t:"p",x:'SACAA applies its own standards, validity periods and examiner categories. The [SACAA Aviation Medicine page](https://www.caa.co.za/industry-information/aviation-medicine/) states that SACAA complies with ICAO Annex 1, Chapter 6. That is a statement about the South African standard. It is not a statement that an ICAO-format or foreign medical certificate can be used in place of a SACAA certificate when a SACAA certificate is required. Do not treat an FAA, EASA or UK medical as "counting as" a SACAA Class 1 or Class 2.'},{t:"h2",x:"What ClinoTrend can do, and what it cannot",id:"what-clinotrend-can-do-and-what-it-canno"},{t:"p",x:"Dr A.O. Ndhlovu is a Regular DAME, MR 336, at Grand Central Airport, Midrand, and issues Class 2 and Class 4 only. If your application needs Class 2 or Class 4, you can book here. If it needs Class 1, you need a Senior DAME. The practice issues the medical certificate and the medical report. It does not complete licensing conversion or validation forms for the personnel licensing department."},{t:"cta",x:"Book a Class 2 or Class 4 medical, if that is the class you need"}],faq:[{q:"Can I use my FAA or EASA medical in South Africa instead of a SACAA one?",a:"Not when a SACAA certificate is required. For validation, regulation 67.00.10 allows the Director to recognise a foreign medical report; that is a SACAA decision, not an automatic substitute. Follow the official conversion or validation rules, not a blog shortcut."},{q:"Which class do I need to convert a PPL?",a:"Usually Class 2, if that is the SACAA licence you are applying for. Confirm with the licensing department."},{q:"I need a Class 1 for a CPL conversion. Can I come to ClinoTrend?",a:"No. You need a Senior DAME."},{q:"Do I need to start from a first-issue medical?",a:"Confirm the medical step with the licensing department when you apply. This article does not treat first-issue rules as always applying."},{q:"How much does it cost?",a:"From R1,500 for a Class 2 or Class 4 medical here. The fee is confirmed when you book."},{q:"Can the practice fill in licensing forms?",a:"No. The practice issues the medical certificate and the medical report, not the licensing conversion or validation file."}],sources:[e.avmed,e.classesReg,e.validation,e.register]},v={slug:"pilot-with-asthma-sacaa-medical",title:"Can You Be a Pilot With Asthma in South Africa? | ClinoTrend",h1:"Can you be a pilot with asthma? What the SACAA medical looks at",description:"How asthma is handled at a SACAA aviation medical: what to declare, the lung function tests and reports SACAA lists, and what student pilots can do first.",excerpt:"How asthma is handled at a SACAA Class 2 or Class 4 medical: what to declare, which tests and reports the SACAA protocol lists, and how student pilots can plan ahead. General information, not personal advice.",keyword:"can you be a pilot with asthma",question:"Can you be a pilot in South Africa if you have asthma?",answer:"Asthma is not an automatic no at a SACAA medical, and not an automatic yes. Declare it, even if it was only in childhood, and list every inhaler and medicine. The SACAA asthma protocol lists lung function tests, a chest X-ray at the initial examination and, in some cases, a specialist report. The examiner then decides.",facts:['Form CA 67-02(a) asks whether you have, or have ever had, "asthma, lung disease", and asks for every medicine, including non-prescribed medicine.',"The summarised SACAA medical protocols (item 29, asthma) list lung function tests, a chest X-ray on initial examination, and a pulmonologist's report if the FEV1/FVC ratio is 70% or lower.","Student pilots need a Class 2 for the SPL and PPL. Aviation medicals at ClinoTrend start from R1,500."],secondary:["pilot with asthma","asthma pilot medical","asthma aviation medical","can you be a commercial pilot with asthma","lung function test for pilots"],published:"2026-11-19",updated:"2026-11-19",status:"approved",tag:"Conditions",body:[{t:"p",x:"This is general information, not individual medical advice, and it does not promise fitness. Asthma is one of the most common questions from people thinking about flight training, often because they had it as a child. This guide explains what the official SACAA documents say, what to bring, and how to plan a first [Class 2 medical](/aviation-medicals/class-2/) or a [Class 4 medical](/class-4-medical/) if asthma is part of your history."},{t:"h2",x:"Can you be a pilot if you have asthma?",id:"can-you-be-a-pilot"},{t:"p",x:"Asthma is not on a list of automatic bars, and a diagnosis on its own does not decide the outcome. The [SACAA Aviation Medicine page](https://www.caa.co.za/industry-information/aviation-medicine/) explains that aviation authorities permit people with certain medical conditions to be certified, provided the condition does not compromise aviation safety. What matters is how the condition behaves now: how well it is controlled, how your lungs perform on testing, and which medicines you use."},{t:"p",x:"The medical standards themselves sit in Document SA-CATS 67, under regulation 67.00.2(6) of Part 67. The examiner applies those standards and the SACAA protocols to your case. A blog post cannot do that for you, and nobody can promise a certificate before the examination."},{t:"h2",x:"Do I have to declare childhood asthma?",id:"declare"},{t:"p",x:'Yes. The SACAA Aviation Medical Report, form CA 67-02(a), asks "Do you have, or have you ever had" a list of conditions, and one of them is **asthma, lung disease**. That covers asthma that settled years ago as well as asthma you treat today. The same form asks about tobacco use, and asks for every medicine you currently use, including non-prescribed medicine, with the name, dose, date started and the reason.'},{t:"p",x:"Leaving out a past diagnosis does not make it go away, and incomplete disclosure is a problem in itself. The ClinoTrend [online SACAA application form](/sacaa-form/) asks the same history questions before your visit, so you can think about dates and details in advance."},{t:"h2",x:"What tests does the SACAA asthma protocol list?",id:"tests"},{t:"p",x:"The SACAA [Summarised Medical Protocols](https://caasanwebsitestorage.blob.core.windows.net/avmed-amended-protocols/Summarised%20Medical%20Protocols%20in%20line%20with%20Part%2067%20of%20the%20Civil%20Aviation%20Regulations%20and%20Technical%20Standards.pdf) (effective 16 November 2021) include an asthma entry, item 29. It lists:"},{t:"ul",items:["**Lung function tests** (spirometry).","**A chest X-ray**, PA and lateral, on the initial examination, and later chest X-rays only on indication.","**A pulmonologist's report** if the FEV1/FVC ratio is 70% or lower."]},{t:"p",x:"Form CA 67-02(a) has fields for a lung function test and a chest X-ray among its special investigations. The doctor tells you which of these apply to you. If a lung function test (spirometry) is needed, ClinoTrend can do it at the practice during the medical: you blow out and breathe in so the examiner can measure how your lungs are working. If a chest X-ray is needed, it can be done at a nearby radiology practice, and you bring the report to your appointment. See [what is included in a SACAA aviation medical](/blog/what-is-included-in-a-sacaa-aviation-medical/) for the tests done at every visit."},{t:"h2",x:"Is it different for a Class 4 medical or cabin crew?",id:"class-4"},{t:"p",x:"Class 4 covers cabin crew and recreational licences such as microlight, gyroplane, light sport and glider pilots. A SACAA workshop presentation on Class 4 medical standards (April 2024) lists the points looked at for an applicant with asthma:"},{t:"ul",items:["lung function results within the Class 4 values","a favourable report from the physician or examiner","no bronchospasm or associated respiratory infection","no emergency treatment for asthma in the last 3 months","treatment limited to acceptable medication"]},{t:"p",x:"Regulation 67.00.2(7) adds one more rule: a Class 4 holder who flies above 12 000 ft must meet the respiratory and lung function test requirements of a Class 2 certificate. Cabin crew can read more on the [cabin crew medical page](/cabin-crew-medical/)."},{t:"h2",x:"Can I fly if I use an inhaler?",id:"inhalers"},{t:"p",x:"Some asthma medicines are acceptable in aviation and some are not, and the timing of some medicines before flight can matter. This guide does not publish a list of named inhalers, because an official SACAA list that covers every product was not available to quote in full. What you should do is simple: bring the names and doses of every inhaler and tablet you use, or the boxes, and tell the examiner how often you use your reliever."},{t:"p",x:'Do not stop or change an asthma medicine to "pass" a medical. That is a decision for your treating doctor, and the examiner needs to see your usual treatment.'},{t:"h2",x:"What should a student pilot with asthma do first?",id:"student-pilots"},{t:"p",x:"Under Part 61, a student pilot licence needs a valid medical certificate before you fly solo, and the SPL and PPL sit under **Class 2**. If asthma is part of your history, book the first medical early, ideally before you pay for a full course. That leaves time for a lung function test, a chest X-ray or a letter from your own doctor if the examiner asks for one. Our [student pilot medical guide](/blog/student-pilot-medical-south-africa/) and the [student pilot medical page](/aviation-medicals/student-pilot/) cover the rest of the first-medical steps."},{t:"p",x:"A useful letter from your treating doctor describes the diagnosis, how often you have symptoms, any hospital or emergency visits, your current treatment, and recent lung function results if you have them. It does not replace the aviation medical."},{t:"p",x:"If you plan a commercial career, the commercial pilot licence, airline transport pilot licence and instrument rating need a **Class 1** medical, which only a SACAA Senior DAME can issue. ClinoTrend does not issue Class 1. If asthma is part of your history, you may want to ask a Senior DAME about Class 1 early. See [SACAA Class 1 medicals and Senior DAMEs](/blog/sacaa-class-1-medical-senior-dame/)."},{t:"p",x:"Flight schools can arrange group medicals for students at Grand Central Airport, Midrand. See the [flight schools page](/flight-schools/)."},{t:"h2",x:"What if my asthma flares up between medicals?",id:"between-medicals"},{t:"p",x:"Regulation 67.00.9 says a certificate holder must not act as a crew member while aware of a medical condition or medication that could affect the validity of the certificate. It also requires the holder to notify the designated body of any hospitalisation or regular use of medication that leaves the holder unable to meet the medical standards. If you have a significant flare-up, a hospital visit or a new regular medicine, stop and speak to your examiner before you fly again."},{t:"h2",x:"What happens if more information is needed?",id:"deferral"},{t:"p",x:"If the examiner needs a test result or a report, the usual step is a deferral, not a refusal. SACAA procedure AM007 says complicated cases are referred to the Aeromedical Committee. See [what happens if an aviation medical is deferred](/blog/aviation-medical-deferred-what-next/) and [what can defer or limit a SACAA medical](/blog/what-can-defer-or-limit-a-sacaa-medical/)."},{t:"h2",x:"Booking a Class 2 or Class 4 medical at ClinoTrend",id:"booking"},{t:"p",x:"Dr Ndhlovu does Class 2 and Class 4 medicals at Grand Central Airport, Midrand. Bring your ID, any licence and current certificate, your medicine list, and any reports or lung function results you already have. Aviation medicals start from R1,500, and extra tests or reports are added only if the doctor finds they are needed. [Book online](/book/), call 011 568 7979 or WhatsApp 078 255 1405. More about the visit is on the [aviation medicals page](/aviation-medicals/) and the [Midrand page](/aviation-medicals/midrand/)."},{t:"cta",x:"Book your Class 2 or Class 4 medical"}],faq:[{q:"Can you be a pilot with asthma in South Africa?",a:"It is possible for some people, depending on how the asthma is controlled, lung function results and medicines. It is not automatic either way. The examiner applies the SACAA standards to your case."},{q:"I had asthma as a child. Do I have to declare it?",a:"Yes. Form CA 67-02(a) asks whether you have, or have ever had, asthma or lung disease. Declare it and give the dates you remember."},{q:"Will I need a lung function test?",a:"The SACAA asthma protocol lists lung function tests. The doctor tells you if one is needed. If it is, ClinoTrend can do the test at the practice during the medical: you blow out and breathe in so the examiner can measure how your lungs are working."},{q:"Do I need a chest X-ray if I have asthma?",a:"The protocol lists a chest X-ray on the initial examination, and later only on indication. The doctor tells you if you need one."},{q:"Can I use my inhaler and still fly?",a:"Some asthma medicines are acceptable and some are not. Bring the names and doses of everything you use and do not stop a medicine without your own doctor."},{q:"Can I become a commercial pilot with asthma?",a:"A commercial licence needs a Class 1 medical from a Senior DAME, who assesses asthma against the Class 1 standards. ClinoTrend does Class 2 and Class 4 only."},{q:"Can cabin crew have asthma?",a:"Cabin crew need a Class 4. The SACAA Class 4 standards look at lung function, control, recent emergency treatment and medication."}],sources:[e.form,{...e.protocols,name:"SACAA Summarised Medical Protocols in line with Part 67 (effective 16 November 2021), item 29 (Asthma)"},e.classesReg,e.class4Standards,e.duties,e.spl,e.am007,e.avmed]},x={slug:"pilot-hearing-test-sacaa-medical",title:"Pilot Hearing Test at a SACAA Medical | ClinoTrend",h1:"Pilot hearing test: what the SACAA medical checks, and what if your hearing is not perfect",description:"How hearing is tested at a SACAA aviation medical, the hearing standards in SA-CATS 67, hearing loss and hearing aids, and what to declare about your ears.",excerpt:"What the hearing test at a SACAA Class 2 or Class 4 medical involves, what the official hearing standards say, and what happens if you have hearing loss or wear hearing aids. General information, not personal advice.",keyword:"pilot hearing test",question:"What hearing test do pilots do at a SACAA medical, and can you fly with hearing loss?",answer:"Every SACAA aviation medical checks your ears and hearing. SACAA allows an audiogram or a spoken and whispered voice test, and the result goes on form CA 67-02(a). The standard is hearing well enough to fly and use the radio safely. Hearing loss or hearing aids are not an automatic no. The examiner applies the standards.",facts:['Form CA 67-02(a) has an audiogram section for each ear at 250 to 6000 Hz, and asks if you have ever had "deafness, ear disease".',"The audiometry limit in SA-CATS 67 is a loss of no more than 35 dB at 500 to 2000 Hz, or 50 dB at 3000 Hz, in either ear.","At ClinoTrend the hearing test (audiometry) is done on site. Aviation medicals start from R1,500."],secondary:["hearing requirements for pilots","can you be a pilot with hearing loss","aviation medical hearing test","can you be a pilot with hearing aids","pilot audiogram"],published:"2026-11-20",updated:"2026-11-20",status:"approved",tag:"Tests",body:[{t:"p",x:"This is general information, not individual medical advice, and it does not promise fitness. The hearing test is part of every [Class 2 medical](/aviation-medicals/class-2/) and [Class 4 medical](/class-4-medical/), and it worries some pilots more than it needs to, especially after years of engine noise. This guide explains what the official SACAA documents say, what happens on the day, and what to bring if your hearing is not perfect."},{t:"h2",x:"Do pilots need a hearing test for a SACAA medical?",id:"do-pilots-need"},{t:"p",x:"Yes. Regulation 67.00.2(6) of Part 67 says the medical standards are prescribed in Document SA-CATS 67. For each class, SA-CATS 67 includes ear, nose and throat and hearing standards, and each class says the applicant must be free from any hearing defect which would interfere with the safe exercise of the privileges of the licence."},{t:"p",x:'The SACAA Aviation Medical Report, form CA 67-02(a), has an audiogram section for the right and left ear at 250, 500, 1000, 2000, 3000, 4000 and 6000 Hz, recorded as dB hearing loss. The examination list on the same form includes "ears, especially eardrum". At ClinoTrend the hearing test (audiometry) is done on site, with the resting ECG, vision testing and urine screening. See [what is included in a SACAA aviation medical](/blog/what-is-included-in-a-sacaa-aviation-medical/) for the rest of the visit.'},{t:"h2",x:"What happens during the hearing test?",id:"what-happens"},{t:"p",x:"The [SACAA FAQ](https://www.caa.co.za/information-for-the-public/frequently-asked-questions/) says the hearing screening requirements are prescribed in the Part 67 technical standards, with alternate requirements: an audiogram, or a conversation and whisper test. In practice that means one of these:"},{t:"ul",items:["**An audiogram (pure tone audiometry).** You wear headphones and respond each time you hear a tone. Each ear is tested at several pitches, and the softest level you hear is recorded in decibels (dB).","**A spoken and whispered voice test.** The SACAA guide for medical examiners (revision March 2023) describes a quiet room with background noise under 35 dB(A), and an average conversational voice heard with both ears at 2 m, with your back turned to the examiner."]},{t:"p",x:"Neither test is something you can study for. If you work or fly in loud noise, you may want to give your ears a quiet day before the test: a SACAA workshop presentation on audiology notes that screening audiograms in noisy workplaces are done after at least 16 hours away from high noise."},{t:"h2",x:"What are the hearing requirements for pilots in South Africa?",id:"requirements"},{t:"p",x:"The wording differs by class. This table summarises the official documents. It is not a self-test, and the examiner applies the standards to your results."},{t:"table",caption:"Hearing standards by class (SA-CATS 67, SACAA guide for medical examiners, SACAA Class IV standards presentation)",head:["Class","Who it covers","What the documents say about hearing"],rows:[["Class 2","SPL, PPL (aeroplane, helicopter, airship), commercial glider, free balloon CPL and others","Free from any hearing defect that would interfere with safe flying. Screening by audiogram or by conversation and whisper test."],["Class 4","Cabin crew and recreational licences such as microlight, gyroplane, LSA and glider","Free from any hearing defect that would interfere with safe duties. The SACAA Class IV standards presentation says the applicant shall be able to hear a whispered voice in a quiet room."],["Class 1","ATPL, CPL, instrument rating","Routine audiometry with set dB limits. Class 1 is issued only by a Senior DAME, not by ClinoTrend."]]},{t:"p",x:"Where audiometry limits are applied, SA-CATS 67 and the SACAA guide for medical examiners use the same numbers: a hearing loss of no more than **35 dB at 500, 1000 and 2000 Hz**, and no more than **50 dB at 3000 Hz**, in either ear. Higher frequencies such as 4000 and 6000 Hz are recorded on the form but are not part of that limit."},{t:"h2",x:"Can you be a pilot with hearing loss?",id:"hearing-loss"},{t:"p",x:"It can be possible, and it is not automatic either way. A result outside the audiometry limit does not end the assessment. The official documents describe further steps:"},{t:"ul",items:["SA-CATS 67 says an applicant who does not meet the limit in one ear may be assessed fit if the loss for both ears, averaged at each frequency, is within the limit and the applicant scores 90% or better on speech audiometry (speech discrimination).","The SACAA guide for medical examiners describes testing hearing against background noise that simulates flight deck noise, or a practical hearing test in flight in the type of aircraft you fly."]},{t:"p",x:"The examiner tells you if any of these apply. If an audiologist report is needed, SACAA has a checklist for it, form [CA 67-30, Audiology Consultation Report Checklist](https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-forms-and-checklist/CA%2067-30.pdf) (15 September 2025). It covers the ears and Eustachian tube function, tinnitus and vertigo, how you communicate by phone and radio, hearing aids and hearing protection, conversation at 1 m and 2 m with your back to the examiner, pure tone audiometry, tympanometry and speech audiometry. If you already know your hearing has changed, a recent audiologist report along those lines helps the examiner and can save a second visit. Hearing loss linked to noise is common in aviation, and it usually develops slowly over years, which is one reason it is checked at each medical."},{t:"h2",x:"Can you fly with hearing aids?",id:"hearing-aids"},{t:"p",x:"Hearing aids are not an automatic bar. The Class IV standards presentation treats the ability to communicate with assisted devices as the test, and a presentation on audiology at a SACAA aviation medicine workshop (April 2022) explains that pilots who need hearing aids can receive a medical certificate with a restriction to use hearing amplification. That presentation is guidance, not a regulation, and the outcome for you depends on your results with the aids."},{t:"p",x:"Bring your hearing aids to the medical and wear them as you would when you fly, and bring any audiologist report. Tell the examiner if you use them only on the ground."},{t:"h2",x:"What ear problems should I declare on the form?",id:"declare"},{t:"p",x:'Form CA 67-02(a) asks "Do you have, or have you ever had" a list of conditions. Three of them are about the ears: **deafness, ear disease**; **nose or throat disease or speech disorder**; and **dizziness or fainting spells**. Declare them even if they were years ago, with the dates you remember. The ClinoTrend [online SACAA application form](/sacaa-form/) asks the same questions before your visit.'},{t:"p",x:"The SA-CATS 67 ear, nose and throat standards also look at:"},{t:"ul",items:["disease of the middle or inner ear","a perforated eardrum that has not healed (a single dry perforation may be acceptable if the hearing standards are still met)","chronic or recurrent blocking of the Eustachian tubes, which equalise ear pressure when you climb and descend","serious or recurrent balance (vestibular) problems","a speech defect that could interfere with safe radio communication"]},{t:"p",x:"If you have had ear surgery, grommets, or treatment by an ear, nose and throat specialist, bring the reports. See [what can defer or limit a SACAA medical](/blog/what-can-defer-or-limit-a-sacaa-medical/) for how further information is handled."},{t:"h2",x:"What if I have a cold or blocked ears on the day?",id:"blocked-ears"},{t:"p",x:"A blocked ear, an ear infection or a heavy cold can affect a hearing test. If that happens close to your appointment, phone the practice on 011 568 7979 before you come in, and the doctor can tell you whether to go ahead or move the booking."},{t:"h2",x:"What if my hearing changes between medicals?",id:"between-medicals"},{t:"p",x:"Regulation 67.00.9 says a certificate holder must not act as a crew member while aware of a medical condition that could affect the validity of the certificate. If you notice a sudden change in your hearing, ringing that does not settle, or dizziness, see your own doctor and speak to your examiner before you fly again."},{t:"h2",x:"Is it different for a commercial pilot?",id:"commercial"},{t:"p",x:"Commercial pilots, airline pilots and pilots with an instrument rating need a **Class 1** medical, which only a SACAA Senior DAME can issue. Class 1 has routine audiometry. ClinoTrend does not issue Class 1. See [SACAA Class 1 medicals and Senior DAMEs](/blog/sacaa-class-1-medical-senior-dame/)."},{t:"h2",x:"Booking a Class 2 or Class 4 medical at ClinoTrend",id:"booking"},{t:"p",x:"Dr Ndhlovu does Class 2 and Class 4 medicals at Grand Central Airport, Midrand, for pilots and cabin crew from Johannesburg, Pretoria, Centurion and the rest of Gauteng. Bring your ID, any licence and current certificate, your medicine list, glasses or hearing aids, and any audiologist or specialist reports. Aviation medicals start from R1,500, and extra tests or reports are added only if the doctor finds they are needed. [Book online](/book/), call 011 568 7979 or WhatsApp 078 255 1405. More about the visit is on the [aviation medicals page](/aviation-medicals/), the [cabin crew medical page](/cabin-crew-medical/) and the [Gauteng page](/aviation-medicals/gauteng/)."},{t:"cta",x:"Book your Class 2 or Class 4 medical"}],faq:[{q:"Is there a hearing test at a SACAA aviation medical?",a:"Yes. Your ears and hearing are checked at every Class 2 and Class 4 medical, by audiogram or by a spoken and whispered voice test. At ClinoTrend the hearing test is done on site."},{q:"What are the hearing requirements for pilots in South Africa?",a:"You must be free from any hearing defect that would interfere with safe flying. Where audiometry limits are applied, SA-CATS 67 uses a loss of no more than 35 dB at 500 to 2000 Hz and 50 dB at 3000 Hz in either ear."},{q:"Can you be a pilot with hearing loss?",a:"It can be possible. A result outside the limit can lead to further tests, such as speech audiometry or a test against cockpit noise. The examiner and SACAA decide, so nobody can promise an outcome before the medical."},{q:"Can you be a pilot with hearing aids?",a:"Hearing aids are not an automatic bar. SACAA workshop material describes certificates with a restriction to use hearing amplification. Bring your hearing aids and any audiologist report to the medical. SACAA form CA 67-30 lists what an audiologist report covers."},{q:"Do cabin crew have a hearing test?",a:"Yes. Cabin crew need a Class 4 medical, and the SACAA Class IV standards presentation says the applicant shall be able to hear a whispered voice in a quiet room."},{q:"Do I need to declare an old ear problem?",a:"Yes. Form CA 67-02(a) asks if you have ever had deafness or ear disease, nose or throat disease, or dizziness. Declare it with the dates you remember and bring any reports."}],sources:[e.classesReg,e.sacats67,e.damesGuide,e.form,e.audiologyChecklist,e.faq,e.class4Standards,e.audiology,e.duties,e.avmed]},S={slug:"aviation-medical-ecg",title:"Aviation Medical ECG: When You Need One | ClinoTrend",h1:"ECG at the aviation medical: when you need one and what it shows",description:"When a resting ECG is due at a SACAA Class 2 or Class 4 medical, what the test shows, when a stress ECG is needed, and what happens if a result is unclear.",excerpt:"When a resting ECG is part of a SACAA Class 2 or Class 4 aviation medical, what the heart tracing can and cannot show, when a stress ECG comes in, and what happens next if the result needs a second look. General information, not personal advice.",keyword:"aviation medical ecg",question:"Do you need an ECG for a SACAA aviation medical, and how often?",answer:"A resting 12 lead ECG is part of your first SACAA Class 2 or Class 4 medical. Under the current SACAA guide for medical examiners it is repeated at the first medical after you turn 40 and at set intervals after 50. A stress ECG is asked for only when risk factors or results call for it.",facts:["SACAA guide for medical examiners (March 2023), Class 2: resting ECG at the initial medical, at the first medical after 40, and every 2 years after 50.","Class 4: at the initial medical, after 40, after 50, then every four years, and when clinically indicated.","At ClinoTrend the resting ECG is done on site. Aviation medicals start from R1,500."],secondary:["aviation medical ecg requirements","pilot medical ecg","ecg test for pilots","class 2 medical ecg","pilot ecg requirements"],published:"2026-11-23",updated:"2026-11-23",status:"approved",tag:"Tests",body:[{t:"p",x:"This is general information, not individual medical advice, and it does not promise fitness. An ECG (electrocardiogram) records the electrical activity of your heart. It is part of many [Class 2 medicals](/aviation-medicals/class-2/) and [Class 4 medicals](/class-4-medical/), but not every visit. Most search results on this topic describe the American or Canadian rules, which are different. This guide explains what the official South African documents say."},{t:"h2",x:"Do you need an ECG for a SACAA aviation medical?",id:"do-you-need"},{t:"p",x:"Usually at your first medical, and then at set ages. Regulation 67.00.2(6) of Part 67 says the medical standards are prescribed in Document SA-CATS 67. The SACAA Guide for Medical Examiners (revision March 2023), which is the guide listed on the [SACAA Aviation Medicine page](https://www.caa.co.za/industry-information/aviation-medicine/), sets out when a resting ECG is due for each class."},{t:"p",x:'The SACAA Aviation Medical Report, form CA 67-02(a), has a "special investigations" section for the resting ECG and the stress ECG, with the date performed, the result and when the next one is due. The same form records your resting pulse rate and whether the rhythm is regular. At ClinoTrend the resting ECG is done on site, with vision testing, the hearing test and urine screening.'},{t:"h2",x:"How often is an ECG done at a pilot medical?",id:"how-often"},{t:"p",x:"The schedule depends on the class of certificate and your age. This table summarises the current SACAA guide for medical examiners. Your examiner confirms at each visit whether an ECG is due."},{t:"table",caption:"When a routine resting ECG is due (SACAA Guide for Medical Examiners, revision March 2023)",head:["Class","Who it covers","Routine resting ECG"],rows:[["Class 2","SPL, PPL (aeroplane, helicopter, airship) and others","At the initial medical, at the first medical after you turn 40, and every 2 years after you turn 50."],["Class 4","Cabin crew and recreational licences such as microlight, gyroplane, LSA and glider","At the initial medical, after you turn 40, after you turn 50, then every four years, and when clinically indicated."],["Class 1","ATPL, CPL, instrument rating","A more frequent schedule. Class 1 is issued only by a Senior DAME, not by ClinoTrend."]]},{t:"p",x:"The SACAA Frequently Asked Questions page still shows an older table with different ECG intervals. ClinoTrend follows the current guide for medical examiners. Some SACAA protocols also ask for an ECG outside the routine schedule. For example, the hypertension protocol includes an ECG at follow up visits. See [blood pressure, diabetes and medication at a SACAA medical](/blog/blood-pressure-diabetes-medication-sacaa-medical/)."},{t:"p",x:"Cabin crew: the amended regulations list cabin crew under Class 4, while some operators ask for Class 2. The [cabin crew medical page](/cabin-crew-medical/) explains which one to book."},{t:"h2",x:"What happens during the ECG?",id:"what-happens"},{t:"p",x:"The SACAA guide describes a standard 12 lead resting ECG:"},{t:"ul",items:["You rest quietly in a warm room, usually lying down.","The skin is cleaned where the sticky electrodes go, on your chest, arms and legs.","The machine records the tracing. It does not send anything into your body, and it is painless."]},{t:"p",x:"The test itself is usually quick. A top that is easy to open or remove makes it simpler. The [aviation medicals page](/aviation-medicals/) asks you to avoid caffeine, tobacco and high sugar meals beforehand, because they can affect urine and ECG results. See [how to prepare for a SACAA aviation medical](/blog/how-to-prepare-for-a-sacaa-aviation-medical/) for the full checklist."},{t:"h2",x:"What does an aviation medical ECG show?",id:"what-it-shows"},{t:"p",x:"A SACAA aviation medicine workshop presentation on aviation cardiology describes what a routine resting ECG is good at, and what it is not:"},{t:"ul",items:["It is better at picking up disturbances of heart rhythm and conduction, such as atrial fibrillation, than narrowed heart arteries.","It can show signs of an earlier heart attack that went unnoticed, and the SACAA guide uses it to look for thickening of the heart muscle when assessing blood pressure risk.","It is not a sensitive test for early coronary artery disease, so a normal tracing is not a full heart check.","Minor variations are common. The presentation says that in at least 10 to 15 per cent of cases a tracing needs comparing with earlier recordings, which is one reason to bring copies of any previous ECGs."]},{t:"p",x:"The same presentation says the purpose of the routine ECG is case finding, and that on its own it does not justify disqualification without further cardiovascular investigation."},{t:"h2",x:"What happens if my ECG is abnormal?",id:"abnormal"},{t:"p",x:"An unusual tracing is not an automatic no. The SACAA guide says ECGs are read by the examiner, who refers to a cardiologist or specialist physician when in doubt. If a tracing is found to be abnormal, the SACAA protocol for abnormal ECG tracings (Schedule 44 of SA-CATS 67, in force from 17 March 2023, for Classes 1 to 4) asks for:"},{t:"ul",items:["a cardiology report","a stress ECG report","a 24 hour Holter ECG report","an echocardiogram (heart ultrasound)"]},{t:"p",x:"The SACAA guide adds that these cases are assessed case by case. The examiner explains what is needed and why, and nobody can promise an outcome before the reports are in. See [what can defer or limit a SACAA medical](/blog/what-can-defer-or-limit-a-sacaa-medical/) and [what happens if a medical is deferred](/blog/aviation-medical-deferred-what-next/)."},{t:"h2",x:"Will I need a stress ECG?",id:"stress-ecg"},{t:"p",x:"Not routinely. A stress (exercise) ECG records the heart while you walk on a treadmill. Under the SACAA guide it is done if the resting ECG is abnormal, or if your cardiovascular risk calls for it. The risk factors the guide lists are high blood pressure, smoking, raised cholesterol, diabetes, a raised BMI or waist size, and a family history of early heart disease."},{t:"p",x:"The guide grades risk with a set of tables. For moderate risk, a DAME may do the stress ECG. For high or very high risk, it is done only by a cardiologist or specialist physician. If your history means you need a test that is not done at the practice, ClinoTrend tells you when you book."},{t:"h2",x:"What should I bring if I have a heart condition?",id:"bring"},{t:"p",x:"Declare any heart condition, palpitations, chest pain, fainting or heart medicine on the application form, with the dates you remember. The ClinoTrend [online SACAA application form](/sacaa-form/) asks the same questions before your visit. Bring copies of earlier ECGs and any cardiologist reports, because the examiner may need to compare them."},{t:"p",x:"Between medicals, regulation 67.00.9 says a certificate holder must not act as a crew member while aware of a medical condition that could affect the validity of the certificate. If you develop chest pain, palpitations or fainting, see your own doctor and speak to your examiner before you fly again."},{t:"h2",x:"Is it different for a commercial pilot?",id:"commercial"},{t:"p",x:"Commercial pilots, airline pilots and pilots with an instrument rating need a **Class 1** medical, which only a SACAA Senior DAME can issue. Class 1 has more frequent ECGs. ClinoTrend does not issue Class 1. See [SACAA Class 1 medicals and Senior DAMEs](/blog/sacaa-class-1-medical-senior-dame/)."},{t:"h2",x:"Booking a Class 2 or Class 4 medical at ClinoTrend",id:"booking"},{t:"p",x:"Dr Ndhlovu does Class 2 and Class 4 medicals at Grand Central Airport, Midrand, for pilots and cabin crew from [Johannesburg](/aviation-medicals/johannesburg/), [Pretoria](/aviation-medicals/pretoria/), [Centurion](/aviation-medicals/centurion/) and the rest of [Gauteng](/aviation-medicals/gauteng/). Bring your ID, any licence and current certificate, your medicine list, glasses, and any earlier ECGs or specialist reports. Aviation medicals start from R1,500, and extra tests or reports are added only if the doctor finds they are needed. [Book online](/book/), call 011 568 7979 or WhatsApp 078 255 1405. More about the visit is on the [aviation medicals page](/aviation-medicals/) and in [what is included in a SACAA aviation medical](/blog/what-is-included-in-a-sacaa-aviation-medical/)."},{t:"cta",x:"Book your Class 2 or Class 4 medical"}],faq:[{q:"Do you need an ECG for a Class 2 medical?",a:"Yes, at the initial medical. The current SACAA guide for medical examiners then lists a resting ECG at the first medical after you turn 40 and every 2 years after you turn 50. At ClinoTrend the resting ECG is done on site."},{q:"How often do pilots have an ECG in South Africa?",a:"It depends on the class and your age. For Class 2: initial, first medical after 40, then every 2 years after 50. For Class 4: initial, after 40, after 50, then every four years. Some SACAA protocols, such as the hypertension protocol, add ECGs at follow up visits."},{q:"Do cabin crew need an ECG?",a:"Yes. Cabin crew on a Class 4 medical have a resting ECG at the initial medical, after 40, after 50, then every four years, and when clinically indicated. Some operators ask for Class 2 instead, which follows the Class 2 schedule."},{q:"What happens if my ECG is abnormal?",a:"It is not an automatic no. Under the SACAA protocol for abnormal ECG tracings, you may be asked for a cardiology report, a stress ECG, a 24 hour Holter ECG and an echocardiogram, and the case is assessed case by case."},{q:"Will I need a stress ECG at my aviation medical?",a:"Not routinely. Under the SACAA guide a stress ECG is done if the resting ECG is abnormal or if your cardiovascular risk calls for it, for example because of blood pressure, smoking, cholesterol, diabetes or family history."},{q:"How should I prepare for the ECG?",a:"Avoid caffeine, tobacco and high sugar meals beforehand, wear a top that is easy to open, and bring copies of any earlier ECGs or cardiologist reports."}],sources:[e.classesReg,e.damesEcg,e.damesClass4,e.ecgProtocol,e.form,e.cardiology,e.class4Ecg,e.faq,e.duties,e.avmed]},a={p64req:{name:"Civil Aviation Regulations, 2011, Part 64, regulation 64.02.1 (Requirements for cabin crew member licence)",url:"https://www.acts.co.za/civil-aviation-act-2009/nr425_64_02_1_requirement"},p64app:{name:"Civil Aviation Regulations, 2011, Part 64, regulation 64.02.5 (Application for cabin crew member licence, as substituted 16 November 2021)",url:"https://www.acts.co.za/civil-aviation-act-2009/nr425_64_02_5_application"},p64valid:{name:"Civil Aviation Regulations, 2011, Part 64, regulation 64.02.7 (Period of validity of the cabin crew member licence)",url:"https://www.acts.co.za/civil-aviation-act-2009/nr425_64_02_7_period_of_v"},flysafair:{name:"FlySafair careers: Flight Attendant vacancy, O.R. Tambo and Lanseria (posted 6 November 2025), job requirements",url:"https://flysafairjobs.mcidirecthire.com/Vacancy/ViewDetails?parameters=q4%2F37VDQTFWXnK7wNIeCPREdPyZ%2Bm5GtClsYiCoryhuFzWtsmfjHgmOJE%2FI%2B3ZNfhEtMmMXnFTPo4D58b926jo%2FZJyIWWj33MCPgKCqf%2BXTAtjM3wACbNEj%2B8KhQAdM74LQqnGBTTuc8X%2BrXJkE3cPmdFXqTDm96gtK9%2Fkc%2FuU0%3D"},flysafairLinkedIn:{name:"FlySafair Flight Attendant vacancy on LinkedIn (personal attributes, including grooming and visible tattoos)",url:"https://za.linkedin.com/jobs/view/flight-attendant-at-flysafair-4052072636"},damesVision:{name:"SACAA Guide for Medical Examiners (DAMEs Guide, revision March 2023), 9.16.2 Class II visual standards (acuity, lenses, refractive surgery) and Class 4 colour perception",url:"https://caasanwebsitestorage.blob.core.windows.net/shared-documents/Dames%20Guide.pdf"},class4Vision:{name:"SACAA Aviation Medicine workshop presentation: Class IV Medical Standards, ophthalmology (visual acuity, visual fields, colour vision not applicable)",url:"https://caasanwebsitestorage.blob.core.windows.net/aviation-medicine-workshop-presentations/Class%20IV%20Medical%20Standards%20-%20Sr%20Tshepo%20Masole.pdf"},damesCabin:{name:"SACAA Guide for Medical Examiners (DAMEs Guide, revision March 2023), 11.1.1 Epilepsy for cabin crew, Class IV protocols (psychiatric, respiratory lung function) and pregnancy",url:"https://caasanwebsitestorage.blob.core.windows.net/shared-documents/Dames%20Guide.pdf"}},k={slug:"how-to-become-a-flight-attendant-south-africa",title:"How to Become a Flight Attendant in SA | ClinoTrend",h1:"How to become a flight attendant in South Africa: the steps, in order",description:"The steps to become a flight attendant in South Africa: age, matric, cabin crew training, the SACAA exam, the aviation medical, your licence and applying.",excerpt:"The steps to become a flight attendant in South Africa, in the order most people do them, with what the law requires and what airlines add.",keyword:"how to become a flight attendant in south africa",question:"How do you become a flight attendant in South Africa?",answer:"You must be at least 18, hold a Part 67 aviation medical certificate, complete approved cabin crew training, pass the SACAA theory exam and a skills test, then apply for a cabin crew licence. Airlines add their own conditions, such as matric and swimming. Many people do the medical first, before paying course fees.",facts:["Regulation 64.02.1 sets the licence requirements: 18 or older, a valid Part 67 medical certificate, training, the theory exam and a skills test.","The SACAA pass mark for licence examinations is 75%, and the exams are written on computer.","A cabin crew licence has no end date, but you may only use it with a valid medical certificate and current recurrent training (regulation 64.02.7)."],secondary:["how to become a cabin crew in south africa","how to get a cabin crew license in south africa","flight attendant qualifications in south africa","how long does it take to become a flight attendant in south africa"],published:"2026-11-26",updated:"2026-11-26",status:"approved",tag:"Cabin crew",body:[{t:"p",x:"In South Africa, a flight attendant is a licensed cabin crew member. The licence is issued by the South African Civil Aviation Authority (SACAA) under Part 64 of the Civil Aviation Regulations, and the airline you work for adds its own hiring conditions on top. This guide sets out the steps in the order most people follow them, and separates what the law requires from what an airline may ask for."},{t:"h2",x:"Step 1: Check the legal minimums",id:"minimums"},{t:"p",x:"Regulation 64.02.1 lists what you need to be issued a cabin crew member licence. You must:"},{t:"ul",items:["Be **at least 18 years old**","Hold a **valid medical certificate issued under Part 67**","Complete the cabin crew training referred to in regulation 64.02.2","Pass the theoretical knowledge examination (regulation 64.02.3)","Undergo the skills test (regulation 64.02.4)"]},{t:"p",x:"Part 64 does not set a maximum age, a height or a weight. If you see those in a job advert, they are the airline's own conditions. Our guide to [flight attendant requirements in South Africa](/blog/flight-attendant-requirements-south-africa/) explains the difference in more detail."},{t:"h2",x:"Step 2: Get your aviation medical early",id:"medical"},{t:"p",x:"You need a current Part 67 medical certificate to apply for the licence, and you must keep one valid for as long as you fly. Many students do the medical **before they pay course fees**. If the examiner finds something that needs a specialist report, you then have time to sort it out without delaying your course or your licence application."},{t:"p",x:"The amended regulation 67.00.2 lists the cabin crew member licence under **Class 4**, and a SACAA FAQ says designated examiners should issue Class 4 for cabin crew. Regulation 64.02.5, on the licence application, still refers to a Class 2 certificate, and some SACAA pages still show Class 2. Ask your training school or airline which class it wants. At ClinoTrend, Dr Ndhlovu can issue either. See [what medical cabin crew need](/blog/cabin-crew-medical-class-4-south-africa/) for the full explanation."},{t:"p",x:"The medical includes your history, a physical examination, vision and hearing tests, a resting ECG and urine screening. Some people need extra tests, such as lung function testing or a specialist report, depending on their history. [Can you be a flight attendant with a medical condition?](/blog/can-you-be-a-flight-attendant-with-a-medical-condition/) covers common questions."},{t:"h2",x:"Step 3: Complete cabin crew training",id:"training"},{t:"p",x:"Cabin crew training typically covers safety and emergency procedures, the aircraft cabin, first aid, fire fighting, ditching and dangerous goods. You can train with a private cabin crew school, or through an airline that runs its own programme. Airline vacancies often list the separate certificates you need, for example a Dangerous Goods, Ditching and Fire Fighting certificate, so keep copies of each one. Our guide to [cabin crew courses in South Africa](/blog/cabin-crew-course-south-africa-medical/) explains when the medical fits in."},{t:"h2",x:"Step 4: Pass the SACAA exam and skills test",id:"exam"},{t:"p",x:"According to the SACAA frequently asked questions, you need a South African ID document or passport to write the cabin crew examination, and foreign applicants need a passport. The exams are written on computer, the pass mark is **75%**, and you can rewrite a failed exam after 7 calendar days. If you fail three times in a row, or score below 50%, you wait 60 days before you rewrite."},{t:"p",x:"The skills test is done by a designated examiner, who signs a skills test report in the format set out in SA-CATS 64."},{t:"h2",x:"Step 5: Apply for your cabin crew licence",id:"licence"},{t:"p",x:"Regulation 64.02.5 says the application to SACAA must include:"},{t:"ul",items:["A certified copy of proof of identity and age","A valid medical certificate issued under Part 67","Proof that you passed the theoretical knowledge examination","The skills test report signed by a designated examiner","The prescribed fee","Two recent passport size photographs"]},{t:"p",x:"The licence itself is valid for an indefinite period. Regulation 64.02.7 says you may only use its privileges while you hold a valid medical certificate and complete the recurrent training required by your operator."},{t:"h2",x:"Step 6: Apply to airlines",id:"apply"},{t:"p",x:"Airlines publish their own requirements. A recent FlySafair flight attendant vacancy, for example, asked for Grade 12 or equivalent, a current SACAA cabin crew licence, a current aviation medical certificate, Dangerous Goods, Ditching and Fire Fighting certificates, a valid driver's licence, Level 4 English, and that applicants are medically fit and able to swim. Requirements change, so read each vacancy on the airline's own careers site and apply only through official channels."},{t:"h2",x:"How long does it take?",id:"time"},{t:"p",x:"It depends on the length of your course, exam bookings and how quickly SACAA processes your licence. The medical itself usually takes one visit. If a specialist report is needed, allow extra time for that appointment and for the report to reach the examiner."},{t:"table",caption:"Steps at a glance",head:["Step","What you need","Who sets it"],rows:[["1","Age 18 or older","Part 64 (64.02.1)"],["2","Valid Part 67 medical certificate","Part 64 and Part 67"],["3","Cabin crew training and certificates","Part 64, training school, airline"],["4","SACAA theory exam (75%) and skills test","SACAA"],["5","Licence application with documents and fee","SACAA (64.02.5)"],["6","Matric, swimming, driver's licence and similar","The airline"]]},{t:"h2",x:"Book your cabin crew medical",id:"book"},{t:"p",x:"ClinoTrend Health & Aviation is in the Main Terminal Building at Grand Central Airport, Gate 2, Office TG6B, in Midrand, between Johannesburg and Pretoria. Dr A.O. Ndhlovu is a SACAA designated aviation medical examiner (Regular DAME, MR 336) and does aviation medicals for pilots and for cabin crew. Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical, and we confirm the fee when you book."},{t:"p",x:"[Book a Class 4 medical](/book/?service=class-4) or a [Class 2 medical](/book/?service=class-2), and complete the [SACAA application form](/sacaa-form/) online before you arrive. The [cabin crew medical page](/cabin-crew-medical/) covers what to bring."},{t:"cta",x:"Book your cabin crew medical"}],faq:[{q:"What is the minimum age to become a flight attendant in South Africa?",a:"Regulation 64.02.1 says you must be at least 18 years old to be issued a cabin crew member licence. Part 64 does not set a maximum age. Airlines may set their own age conditions in their vacancies."},{q:"Do I need matric to become a flight attendant?",a:"Part 64 does not list matric as a licence requirement. Many airlines ask for Grade 12 or equivalent in their vacancies, so check each advert."},{q:"Should I do the medical before or after my cabin crew course?",a:"Many students do it before they pay course fees, and some schools ask for it before you start. You need a valid medical certificate to apply for the licence in any case."},{q:"Which medical class do flight attendants need?",a:"Amended Part 67 lists cabin crew under Class 4, while regulation 64.02.5 and some SACAA pages still refer to Class 2. Ask your school or airline. ClinoTrend can issue either."},{q:"Does a cabin crew licence expire?",a:"No. Regulation 64.02.7 says it is valid for an indefinite period, but you may only use it with a valid medical certificate and current recurrent training."},{q:"Can I become a flight attendant online?",a:"Parts of the theory may be studied online, but the medical, the practical safety training and the skills test are done in person."}],sources:[a.p64req,a.p64app,a.p64valid,e.classes,e.faq,e.class4,e.cabin,a.flysafair]},T={slug:"flight-attendant-requirements-south-africa",title:"Flight Attendant Requirements in South Africa | ClinoTrend",h1:"Flight attendant requirements in South Africa: what the law says and what airlines add",description:"Flight attendant requirements in South Africa: age, medical, licence, height, weight, matric, swimming and tattoos, split into legal rules and airline rules.",excerpt:"Age, medical, licence, height, weight, matric, swimming and tattoos: which flight attendant requirements are law in South Africa and which come from airlines.",keyword:"flight attendant requirements south africa",question:"What are the requirements to be a flight attendant in South Africa?",answer:"By law you need to be 18 or older, hold a Part 67 aviation medical certificate, finish cabin crew training, and pass the SACAA exam and skills test to get a cabin crew licence. Height, weight, matric, swimming and grooming rules are set by each airline, so they differ between employers.",facts:["Part 64 sets age (18 or older), the medical, training, the exam and the skills test. It does not set height or weight.","A recent FlySafair vacancy listed Grade 12, a SACAA cabin crew licence, an aviation medical certificate, safety certificates, Level 4 English and the ability to swim.","The aviation medical checks health and fitness for safety duties. It does not assess appearance."],secondary:["cabin crew requirements south africa","flight attendant requirements height south africa","flight attendant weight requirements in south africa","flight attendant age limit in south africa","flight attendant qualifications in south africa"],published:"2026-11-26",updated:"2026-11-26",status:"approved",tag:"Cabin crew",body:[{t:"p",x:"Search for flight attendant requirements and you will find lists of heights, weights and ages from airlines all over the world. In South Africa, the rules come from two places: the **Civil Aviation Regulations**, which apply to everyone who holds a cabin crew licence, and **each airline's own hiring conditions**, which differ between employers and change over time. Knowing which is which saves you time and money."},{t:"h2",x:"Legal requirements (Part 64)",id:"legal"},{t:"p",x:"Regulation 64.02.1 says an applicant for a cabin crew member licence must be at least 18 years old, hold a valid medical certificate issued under Part 67, complete the prescribed training, pass the SACAA theoretical knowledge examination and undergo a skills test. Regulation 64.01.6 repeats that every applicant for, or holder of, a cabin crew licence must hold a Part 67 medical certificate."},{t:"p",x:"These are the only requirements that apply to every flight attendant in the country. The step by step route is in [how to become a flight attendant in South Africa](/blog/how-to-become-a-flight-attendant-south-africa/)."},{t:"h2",x:"Airline requirements",id:"airline"},{t:"p",x:"Airlines add conditions that suit their aircraft and their service. A FlySafair flight attendant vacancy posted in November 2025, for example, listed:"},{t:"ul",items:["Grade 12 or equivalent","A current SACAA cabin crew licence","A current aviation medical certificate","Dangerous Goods, Ditching and Fire Fighting certificates","A valid South African driver's licence, and in that advert, your own vehicle","Level 4 English language proficiency","Being medically fit and able to swim","Willingness to work shifts, weekends and public holidays"]},{t:"p",x:"Other South African and international airlines publish their own lists. Always read the current vacancy on the airline's official careers site, because requirements are updated and recruitment agencies sometimes copy old versions."},{t:"h2",x:"Height requirements",id:"height"},{t:"p",x:"There is **no height requirement in Part 64 or Part 67**. Some airlines set a minimum height or an arm reach so crew can reach overhead lockers and safety equipment. If height matters to you, check the airline's own vacancy rather than a general list online, and ask the school whether it has seen applicants measured at assessment days."},{t:"h2",x:"Weight requirements",id:"weight"},{t:"p",x:"Part 64 does not set a weight limit. The aviation medical looks at your health, not your appearance. The examiner records your height and weight on the SACAA medical report form and checks whether any health condition could affect your ability to carry out safety and emergency duties. Some airlines say weight should be in proportion to height; that is an employer condition, not a SACAA rule."},{t:"h2",x:"Age limits",id:"age"},{t:"p",x:"The legal minimum is 18. There is **no maximum age** for a cabin crew licence in Part 64. Your medical certificate does last for a shorter period as you get older. A Class 4 certificate is valid for 60 months if you are under 40, and 36 months from 40 onwards (regulation 67.00.6(4)). [How long is a Class 2 medical valid?](/blog/class-2-medical-validity-by-age/) includes a calculator."},{t:"h2",x:"Education and language",id:"education"},{t:"p",x:"Part 64 does not require matric, but many airlines ask for Grade 12 or equivalent, and some ask for English proficiency at a set level. Other languages can be an advantage for international routes, according to many airline adverts."},{t:"h2",x:"Swimming",id:"swimming"},{t:"p",x:"Swimming is not part of the SACAA medical. Airlines and training schools may test it because ditching drills are part of safety training. Practise in a pool before your course or assessment day if you are not a confident swimmer."},{t:"h2",x:"Tattoos, piercings and grooming",id:"tattoos"},{t:"p",x:"Tattoos are not a medical issue and do not affect your aviation medical certificate. They are an airline grooming matter. A FlySafair vacancy on LinkedIn, for example, listed no visible tattoos and full adherence to uniform and grooming rules among its personal attributes. Policies differ between airlines, so check before you apply."},{t:"h2",x:"Eyesight and health",id:"health"},{t:"p",x:"The medical tests your vision, hearing and general health. Many people who wear glasses or contact lenses meet the standard. Read [cabin crew eyesight requirements](/blog/cabin-crew-eyesight-requirements/) and [can you be a flight attendant with a medical condition?](/blog/can-you-be-a-flight-attendant-with-a-medical-condition/) before you book."},{t:"table",caption:"Legal requirement or airline requirement?",head:["Requirement","Set by law (Part 64 or 67)?","Set by the airline?"],rows:[["Age 18 or older","Yes","Some airlines add their own range"],["Aviation medical certificate","Yes","Yes, and it must be current"],["Training, SACAA exam, skills test","Yes","Yes"],["Height or arm reach","No","Sometimes"],["Weight","No","Sometimes"],["Matric (Grade 12)","No","Often"],["Swimming","No","Often"],["No visible tattoos","No","Sometimes"]]},{t:"h2",x:"Book your medical",id:"book"},{t:"p",x:"ClinoTrend Health & Aviation is in the Main Terminal Building at Grand Central Airport, Gate 2, Office TG6B, in Midrand, between Johannesburg and Pretoria. Dr A.O. Ndhlovu is a SACAA designated aviation medical examiner (Regular DAME, MR 336) and does aviation medicals for pilots and for cabin crew. Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical, and we confirm the fee when you book."},{t:"p",x:"[Book a Class 4 medical](/book/?service=class-4) or a [Class 2 medical](/book/?service=class-2), depending on what your school or airline asks for. The [cabin crew medical page](/cabin-crew-medical/) explains what to bring."},{t:"cta",x:"Book your cabin crew medical"}],faq:[{q:"What is the height requirement for flight attendants in South Africa?",a:"There is no height requirement in the Civil Aviation Regulations. Some airlines set a minimum height or reach so crew can reach overhead safety equipment. Check the airline's own vacancy."},{q:"Is there a weight requirement for cabin crew?",a:"Not in Part 64. The aviation medical assesses health, not appearance. Some airlines ask that weight is in proportion to height, which is an employer condition."},{q:"Is there an age limit to become a flight attendant in South Africa?",a:"You must be at least 18. Part 64 sets no maximum age. Your medical certificate is valid for a shorter period from age 40."},{q:"Do I need matric to be a flight attendant?",a:"It is not a legal requirement, but many airlines ask for Grade 12 or equivalent."},{q:"Can I be a flight attendant with tattoos?",a:"Tattoos do not affect the aviation medical. Whether visible tattoos are allowed is an airline grooming policy, and it differs between airlines."},{q:"Do flight attendants need to swim?",a:"Swimming is not part of the SACAA medical, but many airlines and schools require it because ditching drills are part of training."}],sources:[a.p64req,e.cabin,e.validityReg,e.classes,e.form,a.flysafair,a.flysafairLinkedIn]},q={slug:"cabin-crew-eyesight-requirements",title:"Cabin Crew Eyesight Requirements in SA | ClinoTrend",h1:"Cabin crew eyesight requirements in South Africa: glasses, contact lenses and colour vision",description:"Cabin crew eyesight requirements in South Africa: SACAA vision standards for Class 4 and Class 2, glasses, contact lenses, colour vision and laser surgery.",excerpt:"What SACAA material says about vision for cabin crew, whether glasses and contact lenses are allowed, whether colour vision is tested, and what to bring.",keyword:"cabin crew eyesight requirements",question:"What are the eyesight requirements for cabin crew in South Africa?",answer:"Cabin crew vision is checked at the aviation medical. Glasses and contact lenses are allowed if your corrected vision meets the standard. SACAA material for Class 4 lists visual acuity of 6/12 with both eyes or 6/18 in each eye, normal visual fields, and no colour vision requirement. Class 2 standards are stricter.",facts:["SACAA Class IV standards material: visual acuity with or without correction of 6/12 binocularly or 6/18 in each eye; colour vision not applicable.","DAMEs Guide Class II standard: 6/12 or better in each eye and 6/9 or better with both eyes, with or without correction.","Contact lenses must be monofocal and non-tinted, and a spare pair of glasses must be readily available (Class II text)."],secondary:["flight attendant eyesight requirements","flight attendant vision requirements","can you be a flight attendant with glasses","cabin crew colour blind"],published:"2026-11-26",updated:"2026-11-26",status:"approved",tag:"Cabin crew",body:[{t:"p",x:"Good vision matters in the cabin: you read safety cards and placards, find equipment in poor light and watch passengers during an evacuation. That is why vision is tested at every cabin crew medical. The good news for many applicants is that **glasses and contact lenses are allowed**, as long as your corrected vision meets the standard that applies to your certificate."},{t:"p",x:"This article is general information, not a personal assessment. The examiner applies the official standard to you on the day."},{t:"h2",x:"Which standard applies to cabin crew?",id:"which"},{t:"p",x:"Amended Part 67 regulation 67.00.2 lists the cabin crew member licence under **Class 4**, and a SACAA FAQ says examiners should issue Class 4 to cabin crew. Some airlines and older SACAA pages still refer to **Class 2**. The vision standard depends on which class you are issued, so ask your school or airline which class it wants before you book. Our guide to [what medical cabin crew need](/blog/cabin-crew-medical-class-4-south-africa/) explains the two classes."},{t:"h2",x:"Class 4 vision",id:"class-4"},{t:"p",x:"A SACAA aviation medicine workshop presentation on Class IV medical standards lists, under ophthalmology:"},{t:"ul",items:["Visual acuity, with or without correction, of **6/12 with both eyes or 6/18 in each eye**","If you have sight in only one eye, you may be assessed as fit if the unaffected eye sees **6/6 or better**, with or without correction","A **normal binocular visual field**, or a normal visual field in one eye","**Colour vision: not applicable**"]},{t:"p",x:"The SACAA Guide for Medical Examiners (March 2023) also says that, for Class 4, colour perception standards are **not applicable**, and that eye cases needing a decision are referred to the SACAA Aeromedical Committee under the relevant protocols."},{t:"h2",x:"Class 2 vision",id:"class-2"},{t:"p",x:"If your airline asks for a Class 2 certificate, the DAMEs Guide sets a stricter distance standard: **6/12 or better in each eye separately, and 6/9 or better with both eyes**, with or without correction. There is no limit on uncorrected vision, but if you need lenses to meet the standard, your certificate is endorsed that corrective lenses must be worn, and you must keep a spare pair of glasses readily available. Class 2 also has near vision requirements and a colour perception standard. The [pilot eyesight and colour vision guide](/blog/sacaa-pilot-eyesight-colour-vision/) covers colour testing."},{t:"table",caption:"Vision at a glance (from SACAA material)",head:["","Class 4","Class 2"],rows:[["Distance acuity (with or without correction)","6/12 both eyes or 6/18 each eye","6/12 each eye and 6/9 both eyes"],["Glasses allowed","Yes, if the standard is met","Yes, with an endorsement and a spare pair"],["Colour vision","Not applicable","Tested"],["Visual fields","Normal (binocular or monocular)","Normal"]]},{t:"h2",x:"Glasses and contact lenses",id:"lenses"},{t:"p",x:"For Class 2, the DAMEs Guide says contact lenses may be used if they are **monofocal and non-tinted**, well tolerated, and you keep a pair of suitable glasses readily available. People with a large refractive error must use contact lenses or high-index spectacle lenses. If your uncorrected vision in either eye is worse than 6/60, the guide asks for a full ophthalmic report before the first assessment and every five years after that."},{t:"p",x:"For any class, bring your current glasses or contact lenses, your spare pair, and your latest prescription to the medical."},{t:"h2",x:"Laser eye surgery",id:"laser"},{t:"p",x:"Laser eye surgery does not automatically rule you out. The DAMEs Guide says that applicants who have had surgery affecting the refractive status of the eye are assessed as unfit **unless they are free from after effects** likely to interfere with safe duties. Bring your surgeon's or optometrist's report, including the date of surgery and your current vision, so the examiner can assess it."},{t:"h2",x:"Colour blindness and cabin crew",id:"colour"},{t:"p",x:"Many people search whether a colour blind person can be a flight attendant. For **Class 4**, SACAA material says colour vision is not applicable. If an airline asks for **Class 2**, colour perception is tested, and a fail on the first plate test can lead to further testing under the SACAA colour vision protocol. Some airlines may also have their own eyesight checks during recruitment, so read the vacancy."},{t:"h2",x:"How vision is tested at ClinoTrend",id:"test"},{t:"p",x:"Vision testing is done on site at ClinoTrend for Class 2 and Class 4 medicals. The examiner checks distance and near vision, with and without your lenses, and your visual fields, and records the results on the SACAA medical report form CA 67-02(a). If anything needs a specialist eye report, we will explain what is needed and why."},{t:"h2",x:"Book your cabin crew medical",id:"book"},{t:"p",x:"ClinoTrend Health & Aviation is in the Main Terminal Building at Grand Central Airport, Gate 2, Office TG6B, in Midrand, between Johannesburg and Pretoria. Dr A.O. Ndhlovu is a SACAA designated aviation medical examiner (Regular DAME, MR 336) and does aviation medicals for pilots and for cabin crew. Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical, and we confirm the fee when you book."},{t:"p",x:"[Book a Class 4 medical](/book/?service=class-4) or a [Class 2 medical](/book/?service=class-2), and bring your glasses or lenses. You may also like [flight attendant requirements in South Africa](/blog/flight-attendant-requirements-south-africa/)."},{t:"cta",x:"Book your cabin crew medical"}],faq:[{q:"Can you be a flight attendant with glasses?",a:"Yes, if your vision with glasses meets the standard for your medical class. Bring your glasses and a spare pair to the medical."},{q:"Can cabin crew wear contact lenses?",a:"Yes. For Class 2, the DAMEs Guide says lenses must be monofocal and non-tinted and well tolerated, with a spare pair of glasses readily available."},{q:"Can a colour blind person be cabin crew in South Africa?",a:"For a Class 4 certificate, SACAA material says colour vision is not applicable. Class 2 includes a colour perception test. Airlines may have their own checks."},{q:"What is the minimum eyesight for cabin crew?",a:"SACAA Class IV material lists 6/12 with both eyes or 6/18 in each eye, with or without correction. Class 2 requires 6/12 in each eye and 6/9 with both eyes."},{q:"Can I be cabin crew after laser eye surgery?",a:"Possibly. Applicants are assessed as unfit only if after effects could interfere with safe duties. Bring your surgery report and current prescription."}],sources:[a.class4Vision,a.damesVision,e.classes,e.faq,e.form]},M={slug:"cabin-crew-course-south-africa-medical",title:"Cabin Crew Course in SA: Your Medical | ClinoTrend",h1:"Cabin crew course in South Africa: where the aviation medical fits in",description:"Planning a cabin crew course in South Africa? When to do your aviation medical, which class to book, what schools ask for, and how it links to your licence.",excerpt:"When to do your aviation medical before or during a cabin crew course in South Africa, which class to ask for, and how it links to your SACAA licence.",keyword:"cabin crew course south africa",question:"When should I do my aviation medical for a cabin crew course in South Africa?",answer:"Do your aviation medical before you pay course fees, or as soon as your school asks. You need a valid Part 67 medical certificate to apply for your cabin crew licence, and doing it early leaves time for any specialist report. Ask the school whether it wants a Class 4 or Class 2 certificate.",facts:["Regulation 64.02.1(b): a cabin crew licence applicant must hold a valid medical certificate issued under Part 67.","A Class 4 certificate lasts 60 months if you are under 40 (regulation 67.00.6(4)), so a medical done before your course will usually still be valid when you apply for the licence.","Airline vacancies often list Dangerous Goods, Ditching and Fire Fighting certificates separately from the licence and the medical."],secondary:["cabin crew training south africa","flight attendant course south africa","flight attendant course in south africa requirements","cabin crew training schools in south africa","how to get a cabin crew license"],published:"2026-11-26",updated:"2026-11-26",status:"approved",tag:"Cabin crew",body:[{t:"p",x:"A cabin crew course is a big investment of time and money. Before you sign up, it helps to understand how the course, the SACAA licence and the aviation medical fit together, so that a paperwork gap does not hold you back at the end."},{t:"h2",x:"How the course, the medical and the licence link up",id:"link"},{t:"p",x:"To be issued a cabin crew member licence, regulation 64.02.1 says you must be at least 18, hold a **valid Part 67 medical certificate**, complete the prescribed training, pass the SACAA theoretical knowledge examination and undergo a skills test. The course prepares you for the training, exam and skills test. The medical is a separate step, done by a medical examiner, not by the school."},{t:"p",x:"That means you can finish a course and pass every exam, and still be unable to apply for your licence if you do not hold a valid medical certificate. Our guide to [how to become a flight attendant in South Africa](/blog/how-to-become-a-flight-attendant-south-africa/) shows all the steps in order."},{t:"h2",x:"When to do the medical",id:"when"},{t:"p",x:"Many students find it useful to do the medical **before they pay course fees**, or as soon as the school asks for it. There are three practical reasons:"},{t:"ol",items:["**Time for follow up.** If the examiner needs a report from your doctor, an eye specialist or another specialist, you have time to arrange it before the course starts.","**No surprises at the end.** You know early whether there is anything to address, instead of finding out after you have finished training.","**Some schools ask for it.** Schools and airlines may want a current medical before you start practical training, especially before ditching and fire drills."]},{t:"p",x:"A Class 4 certificate issued before age 40 is valid for 60 months, so a medical done before your course will usually still be valid when you apply for the licence and when you start applying to airlines."},{t:"h2",x:"Which class to ask for",id:"class"},{t:"p",x:"The amended Part 67 regulation 67.00.2 lists cabin crew under **Class 4**, and a SACAA FAQ says examiners should issue Class 4 to cabin crew. Regulation 64.02.5, which lists the documents for the licence application, still refers to a **Class 2** medical certificate, and some airline adverts and SACAA pages also say Class 2. Because the sources differ, **ask your school which class it wants** before you book. Dr Ndhlovu at ClinoTrend can issue either. The two classes have different validity periods and slightly different standards, for example for vision. See [cabin crew eyesight requirements](/blog/cabin-crew-eyesight-requirements/)."},{t:"h2",x:"What the medical includes",id:"includes"},{t:"p",x:"At ClinoTrend the cabin crew medical includes your medical history on SACAA form CA 67-02(a), a physical examination, vision testing, a hearing test, a resting ECG and urine screening, done on site. For a first Class 4 medical under age 40, the SACAA Guide for Medical Examiners says flow-volume lung function testing forms part of the respiratory assessment. The examiner will tell you whether anything else is needed. [What is included in a SACAA aviation medical](/blog/what-is-included-in-a-sacaa-aviation-medical/) has more detail."},{t:"h2",x:"What cabin crew schools usually ask for",id:"schools"},{t:"p",x:"Each school sets its own entry rules, so check them directly. Common items in school and airline requirements include:"},{t:"ul",items:["Proof of identity, and proof of age (18 or older for the licence)","Grade 12 or equivalent, which many airlines ask for","An aviation medical certificate, or a plan to get one before practical training","Being able to swim, for ditching drills","Good spoken and written English"]},{t:"p",x:"Airline vacancies often list the **Dangerous Goods, Ditching and Fire Fighting certificates** separately, so keep the originals and copies from your course. A recent FlySafair flight attendant vacancy listed all three, along with a SACAA cabin crew licence and an aviation medical certificate."},{t:"h2",x:"Choosing a school",id:"choose"},{t:"p",x:"ClinoTrend does not recommend or partner with any particular cabin crew school. When you compare schools, ask each one:"},{t:"ul",items:["Whether it is approved by SACAA to present cabin crew training","What the total cost includes: training, SACAA exam fees, certificates and uniform","Which certificates you receive at the end","Whether it books the SACAA exam and skills test for you","Which medical class it wants, and by when"]},{t:"h2",x:"After the course: your licence",id:"after"},{t:"p",x:"Regulation 64.02.5 lists what goes with the licence application: certified proof of identity and age, a valid medical certificate, proof that you passed the theory exam, the skills test report signed by a designated examiner, the fee and two passport photographs. The SACAA FAQ says the exam pass mark is 75%. The licence is valid indefinitely, but regulation 64.02.7 says you may only use it while your medical certificate is valid and your recurrent training is current."},{t:"h2",x:"Book your medical before your course",id:"book"},{t:"p",x:"ClinoTrend Health & Aviation is in the Main Terminal Building at Grand Central Airport, Gate 2, Office TG6B, in Midrand, between Johannesburg and Pretoria. Dr A.O. Ndhlovu is a SACAA designated aviation medical examiner (Regular DAME, MR 336) and does aviation medicals for pilots and for cabin crew. Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical, and we confirm the fee when you book."},{t:"p",x:"[Book a Class 4 medical](/book/?service=class-4) or a [Class 2 medical](/book/?service=class-2), and complete the [SACAA application form](/sacaa-form/) online first. Training schools can also read our [flight schools page](/flight-schools/)."},{t:"cta",x:"Book your cabin crew medical"}],faq:[{q:"Do I need a medical before a cabin crew course?",a:"Part 64 requires a valid medical certificate for the licence. Many schools ask for it before practical training, and doing it before you pay fees leaves time for any follow up."},{q:"Which medical class should cabin crew students book?",a:"Amended Part 67 lists cabin crew under Class 4, while regulation 64.02.5 and some airline adverts still refer to Class 2. Ask your school which it wants."},{q:"How long is my medical valid during training?",a:"A Class 4 certificate is valid for 60 months if you are under 40, and 36 months from 40, under regulation 67.00.6(4)."},{q:"Can I do the cabin crew course online?",a:"Theory may be offered online by some schools, but safety drills, the skills test and the medical are done in person."},{q:"What is the pass mark for the SACAA cabin crew exam?",a:"The SACAA FAQ says the pass mark for all its examinations is 75%."}],sources:[a.p64req,a.p64app,a.p64valid,e.classes,e.faq,e.validityReg,e.form,a.damesCabin,a.flysafair]},P={slug:"can-you-be-a-flight-attendant-with-a-medical-condition",title:"Can You Be a Flight Attendant With a Condition? | ClinoTrend",h1:"Can you be a flight attendant with a medical condition? Common questions answered",description:"Can you be a flight attendant with glasses, asthma, epilepsy, diabetes, anxiety or while pregnant? How SACAA assesses cabin crew, and what reports to bring.",excerpt:"Glasses, asthma, epilepsy, diabetes, anxiety, HIV and pregnancy: how SACAA standards treat common conditions for cabin crew, and what to bring to your medical.",keyword:"can you be a flight attendant with",question:"Can you be a flight attendant if you have a medical condition?",answer:"Often, yes. A medical condition does not automatically stop you from being cabin crew. The examiner assesses whether it is well controlled and unlikely to affect safety duties, using SACAA standards and protocols. Some conditions need specialist reports or a SACAA decision first. Bring your reports and medicine list to the medical.",facts:["SACAA standards for cabin crew mostly say a condition is disqualifying unless acceptable and effective treatment has controlled the risk.","Epilepsy has a specific cabin crew protocol in the SACAA DAMEs Guide, including specialist reports and restrictions.","Regulation 67.00.9 sets duties for certificate holders, including pregnancy rules and reporting illness, surgery and regular medication."],secondary:["can you be a flight attendant with epilepsy","can you be a flight attendant with glasses","can you be a flight attendant with asthma","can cabin crew fly when pregnant","can you be a flight attendant with tattoos"],published:"2026-11-26",updated:"2026-11-26",status:"approved",tag:"Cabin crew",body:[{t:"p",x:"If you have a health condition, it is natural to worry that it will end your plans to fly as cabin crew before they begin. In most cases the answer depends on **how well the condition is controlled** and whether it could suddenly affect you during flight or an emergency. This article explains how SACAA standards approach common conditions for cabin crew."},{t:"p",x:"It is general information, not a personal assessment and not a promise of fitness. Only the examiner, and in some cases SACAA, can decide your outcome. If you have a condition, the most useful thing you can do is bring recent reports to your medical."},{t:"h2",x:"How the medical approaches conditions",id:"approach"},{t:"p",x:"The SACAA Class IV medical standards, which cover cabin crew, are written in a similar way for most body systems: a condition is disqualifying **unless acceptable and effective treatment has controlled** the risk of sudden or subtle incapacitation, or unless specialist reports support fitness. Some conditions have their own protocol, which sets out exactly which reports are needed. Some cases are sent to SACAA medical assessors or the Aeromedical Committee for a decision."},{t:"h2",x:"Glasses and contact lenses",id:"glasses"},{t:"p",x:"Yes, many cabin crew wear glasses or contact lenses. What matters is whether your corrected vision meets the standard for your medical class. For Class 4, SACAA material says colour vision is not applicable. See [cabin crew eyesight requirements](/blog/cabin-crew-eyesight-requirements/) for the numbers."},{t:"h2",x:"Asthma",id:"asthma"},{t:"p",x:"Asthma is assessed on how well it is controlled and on your lung function. The SACAA Guide for Medical Examiners says flow-volume lung function testing forms part of the respiratory assessment for a first Class 4 certificate under age 40, and is repeated after 40 and after 50. Bring your inhalers or a list of them, and any recent lung function results. Our [asthma and the SACAA medical guide](/blog/pilot-with-asthma-sacaa-medical/) explains the respiratory standards in more detail."},{t:"h2",x:"Epilepsy and seizures",id:"epilepsy"},{t:"p",x:"Epilepsy has a specific cabin crew protocol in the DAMEs Guide. A cabin crew member diagnosed with epilepsy is medically unfit to fly at first. They may be considered for recertification by a SACAA medical assessor **after one year on medication**, with a neurologist report, a brain CT or MRI scan and a 16 lead EEG, none older than three months. If certified, restrictions apply, such as short haul flights of not more than three hours and operating under supervision or in pairs. A change of medication means six months off flying and a new neurologist report. A single seizure is considered case by case."},{t:"h2",x:"Diabetes, blood pressure and other long term conditions",id:"chronic"},{t:"p",x:"Many long term conditions are compatible with flying once they are stable and your medicine is acceptable for flight duties. The examiner looks at control, complications and side effects, and may ask for reports from your doctor. Our guide to [blood pressure, diabetes and medication at the SACAA medical](/blog/blood-pressure-diabetes-medication-sacaa-medical/) covers what to bring."},{t:"h2",x:"Anxiety and depression",id:"mental-health"},{t:"p",x:"A history of mental health treatment does not automatically rule you out. Under the SACAA Class IV protocols, an applicant with a history of **mild to moderate anxiety** may be assessed as fit if psychiatrist and psychologist reports are favourable, they have been well and stable for at least one month, and the medicine used is acceptable for flight duties. Mild to moderate depression is assessed under the mood disorder protocol. Be honest on the medical form, because the declaration you sign is part of the application."},{t:"h2",x:"HIV",id:"hiv"},{t:"p",x:"SACAA has a dedicated HIV protocol for cabin crew and recreational pilots in the DAMEs Guide. HIV status is assessed under that protocol, and your medical information stays confidential between you, the examiner and SACAA's medical department."},{t:"h2",x:"Hearing",id:"hearing"},{t:"p",x:"A hearing test is part of the cabin crew medical. A result outside the standard does not always end the process, because further assessment may be possible. See [the pilot hearing test](/blog/pilot-hearing-test-sacaa-medical/) for how audiometry works and what happens if a result is outside the standard."},{t:"h2",x:"Pregnancy",id:"pregnancy"},{t:"p",x:"Regulation 67.00.9 says a certificate holder may not act as cabin crew while pregnant during the periods and circumstances set out in SA-CATS 67, or if she has given birth in the preceding six weeks, and must tell the designated body about a pregnancy. The DAMEs Guide says pregnant applicants are assessed as unfit unless obstetric evaluation and ongoing medical supervision show a low risk, uncomplicated pregnancy, with reports from a gynaecologist or obstetrician. Your airline's own pregnancy policy applies separately."},{t:"h2",x:"Tattoos",id:"tattoos"},{t:"p",x:"Tattoos are not a medical condition and do not affect your aviation medical certificate. Whether visible tattoos are allowed is an airline grooming policy. See [flight attendant requirements in South Africa](/blog/flight-attendant-requirements-south-africa/)."},{t:"h2",x:"What to bring if you have a condition",id:"bring"},{t:"ul",items:["A list of every medicine you take, with doses, including over the counter medicines","Recent reports from your doctor or specialist (ideally from the last three to six months)","Test results, such as lung function, blood tests or scans, if you have them","Glasses, contact lenses or hearing aids, if you use them","Your ID or passport, and any previous medical certificate"]},{t:"p",x:"If the examiner needs more information, we will explain what is needed and why. A deferred decision is not a refusal. Read [what happens if your aviation medical is deferred](/blog/aviation-medical-deferred-what-next/)."},{t:"h2",x:"Book your cabin crew medical",id:"book"},{t:"p",x:"ClinoTrend Health & Aviation is in the Main Terminal Building at Grand Central Airport, Gate 2, Office TG6B, in Midrand, between Johannesburg and Pretoria. Dr A.O. Ndhlovu is a SACAA designated aviation medical examiner (Regular DAME, MR 336) and does aviation medicals for pilots and for cabin crew. Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical, and we confirm the fee when you book."},{t:"p",x:"[Book a Class 4 medical](/book/?service=class-4) or a [Class 2 medical](/book/?service=class-2), and complete the [SACAA application form](/sacaa-form/) online before your visit."},{t:"cta",x:"Book your cabin crew medical"}],faq:[{q:"Can you be a flight attendant with epilepsy?",a:"Under the SACAA cabin crew protocol you are unfit at diagnosis, but may be considered for recertification after one year on medication with neurologist, scan and EEG reports. Restrictions such as short haul flights apply."},{q:"Can you be a flight attendant with asthma?",a:"Often, if it is well controlled. Lung function testing forms part of the first Class 4 assessment under age 40. Bring your inhaler list and recent results."},{q:"Can cabin crew fly when pregnant?",a:"Only under the conditions in SA-CATS 67 and the DAMEs Guide, with obstetric reports showing a low risk, uncomplicated pregnancy. Not within six weeks after giving birth. Airline policy also applies."},{q:"Can you be a flight attendant with anxiety or depression?",a:"A history of mild to moderate anxiety or depression can be assessed as fit with favourable specialist reports, stability and acceptable medicine, under SACAA protocols."},{q:"Do I have to declare a condition on the medical form?",a:"Yes. You sign a declaration on the SACAA medical form, and regulation 67.00.9 requires holders to report illness, surgery, hospitalisation and regular medication."},{q:"Can you be a flight attendant with tattoos?",a:"Tattoos do not affect the medical. Visible tattoo rules are set by each airline."}],sources:[a.damesCabin,a.class4Vision,e.duties,e.class4Standards,e.classes,e.form,e.protocols]},i={pplA:{name:"Civil Aviation Regulations, 2011, Part 61, regulation 61.03.1 (Requirements for a PPL (Aeroplane))",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_61_03_1_requirement.php"},pplH:{name:"Civil Aviation Regulations, 2011, Part 61, regulation 61.04.1 (Requirements for a PPL (Helicopter))",url:"https://api.acts.co.za/civil-aviation-act-2009/nr425_61_04_1_requirement.php"},pplAChecklist:{name:"SACAA form CA 61-03.1a, Checklist of requirements for initial issue of a Private Pilot Licence (Aeroplane)",url:"https://caasanwebsitestorage.blob.core.windows.net/personnellicensingforms/CA%2061-03%201a.pdf"},pplHChecklist:{name:"SACAA form CA 61-04a, Requirements for issue of a Private Pilot Licence (Helicopter), 26 August 2025",url:"https://caasanwebsitestorage.blob.core.windows.net/personnellicensingforms/CA%2061-04a.pdf"},damesRefractive:{name:"SACAA Guide for Medical Examiners (DAMEs Guide, revision March 2023), 16.14.5 Radial Keratotomy, PRK and LASIK protocol, and visual standard for applicants who have had refractive surgery",url:"https://caasanwebsitestorage.blob.core.windows.net/shared-documents/Dames%20Guide.pdf"},damesOsa:{name:"SACAA Guide for Medical Examiners (DAMEs Guide, revision March 2023), Obstructive Sleep Apnea protocol (Classes 1, 2, 3 and 4) and Protocol on Obesity",url:"https://caasanwebsitestorage.blob.core.windows.net/shared-documents/Dames%20Guide.pdf"},protocolsLaser:{name:"SACAA Summarised Medical Protocols in line with Part 67 (effective 16 November 2021), item 47 (Radial keratotomy, PRK and LASIK protocol)",url:"https://caasanwebsitestorage.blob.core.windows.net/avmed-amended-protocols/Summarised%20Medical%20Protocols%20in%20line%20with%20Part%2067%20of%20the%20Civil%20Aviation%20Regulations%20and%20Technical%20Standards.pdf"}},I={slug:"how-to-become-a-pilot-south-africa",title:"How to Become a Pilot in South Africa | ClinoTrend",h1:"How to become a pilot in South Africa: the steps, and where the medical fits",description:"The steps to become a pilot in South Africa: the Class 2 medical, student licence, training, exams and private pilot licence, and the later Class 1 step.",excerpt:"The steps to become a pilot in South Africa, with the SACAA Class 2 medical as an early step, and what changes if you later train for a commercial licence.",keyword:"how to become a pilot in south africa",question:"How do you become a pilot in South Africa?",answer:"You train at an approved flight school, hold a valid Part 67 medical certificate, and apply for a SACAA licence at each stage. For an aeroplane or helicopter student or private licence, that medical is Class 2. Book it before you fly solo. A commercial licence later needs a Class 1 medical, which only a Senior DAME may issue.",facts:["Part 61, regulation 61.02.1, says an applicant for a student pilot licence must be 15 years or older and hold a valid medical certificate issued under Part 67.","A private pilot licence needs you to be 17 or older, with a valid Part 67 medical, training at an approved school, theory exams and a skills test (regulations 61.03.1 and 61.04.1).","Part 61 does not list school subjects such as mathematics or physical science. Flight schools may set their own entry rules."],secondary:["pilot requirements south africa","pilot license requirements south africa","how to become a commercial pilot in south africa","pilot license south africa"],published:"2026-11-26",updated:"2026-11-26",status:"approved",tag:"Student pilots",body:[{t:"p",x:"Becoming a pilot in South Africa is a sequence of SACAA licences, each with a medical certificate issued under Part 67 of the Civil Aviation Regulations. This guide covers the usual path from first lesson to a private pilot licence (PPL), where the medical sits, and what changes if you later train commercially. It does not replace the advice of an approved training organisation (ATO)."},{t:"h2",x:"Do I need maths, physics or matric?",id:"subjects"},{t:"p",x:"A common first question is about school subjects. Part 61, which sets the licence requirements, does not list mathematics, physical science or matric as a condition for a student or private pilot licence. Flight schools and, later, airlines may still set their own entry rules, especially for commercial courses. Ask the approved training organisation you plan to join what it requires, rather than relying on unofficial lists."},{t:"h2",x:"Step 1: Choose an approved flight school",id:"school"},{t:"p",x:"Training for a Part 61 student or private licence must be completed at a SACAA-approved Part 141 aviation training organisation. The school will tell you whether you are starting on an aeroplane or a helicopter, what the course includes, and when it wants you to hold a medical certificate. Schools can also arrange group medicals; see our [flight schools page](/flight-schools/)."},{t:"h2",x:"Step 2: Get your aviation medical early",id:"medical"},{t:"p",x:"You need a valid medical certificate issued under Part 67 before you fly solo on a student pilot licence, and you must keep one valid whenever you exercise licence privileges. Many students book the medical in the first weeks of training, so there is time if the examiner asks for a further test or a report."},{t:"p",x:"Regulation 67.00.2 lists the student pilot licence (SPL) and the private pilot licence for aeroplane, airship and helicopter under **Class 2**. Recreational student licences, such as microlight or glider, sit under **Class 4**. A commercial pilot licence (CPL), an airline transport pilot licence (ATPL) and an instrument rating need a **Class 1** medical, which only a SACAA Senior DAME may do. Dr Ndhlovu is a Regular DAME, so ClinoTrend issues Class 2 and Class 4. ClinoTrend does not currently issue Class 1 or Class 3."},{t:"p",x:"Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical, and we confirm the fee when you book. [Book a Class 2 medical](/book/?service=class-2), or read [student pilot medical requirements](/blog/student-pilot-medical-south-africa/) if you are about to fly solo."},{t:"cta",x:"Book a Class 2 medical"},{t:"h2",x:"Step 3: The student pilot licence",id:"spl"},{t:"p",x:"Regulation 61.02.1, as amended on 21 August 2026, says an applicant for an SPL or integrated student pilot licence (ISPL) must be 15 years or older, hold a valid medical certificate issued under Part 67, and be registered with an approved training organisation. The SPL is what allows you to fly solo under instruction. If you are under 18, contact the practice to confirm any extra requirements before you book."},{t:"h2",x:"Step 4: Training, radio licence, exams and the skills test",id:"training"},{t:"p",x:"Your school will take you through dual instruction, solo flying and the theoretical knowledge examinations. For a PPL you also need at least a restricted certificate of proficiency in radiotelephony (aeronautical). The PPL application checklist used by SACAA also lists an ICAO language proficiency certificate at a minimum of level 4. The subjects, hours and skills test are set in Part 61 and SA-CATS 61; our guide to [private pilot licence medical requirements](/blog/private-pilot-licence-medical-south-africa/) sets out the PPL step in more detail, including the hour minimums."},{t:"h2",x:"Step 5: The private pilot licence",id:"ppl"},{t:"p",x:"A PPL (aeroplane) or PPL (helicopter) needs you to be 17 years or older and still hold a valid Part 67 medical certificate. The same Class 2 certificate that covered your SPL usually covers the PPL, if it is still in date. [How long a Class 2 medical is valid](/blog/class-2-medical-validity-by-age/) explains the periods by age. Helicopter training uses the same medical class, with different hour minimums; see [helicopter pilot medical requirements](/blog/helicopter-pilot-medical-requirements/)."},{t:"h2",x:"If you want to fly commercially later",id:"commercial"},{t:"p",x:"A CPL or ATPL needs a Class 1 medical, done by a SACAA Senior DAME. Ask your flight school when it wants you to hold Class 1. ClinoTrend can do the Class 2 medicals that cover your student and private licences, and can point you to the [Class 1 and Senior DAME guide](/blog/sacaa-class-1-medical-senior-dame/) when you need that step. Cabin crew follow a different licence path under Part 64, with their own medical; see [how to become a flight attendant in South Africa](/blog/how-to-become-a-flight-attendant-south-africa/)."},{t:"table",caption:"Usual path from first lesson to a private licence",head:["Step","What you need","Who sets it"],rows:[["1","Approved Part 141 flight school","Part 61"],["2","Valid Part 67 medical (Class 2 for SPL or PPL on aeroplane or helicopter)","Part 67, regulation 67.00.2"],["3","Student pilot licence, from age 15","Part 61, regulation 61.02.1"],["4","Training, radio certificate, theory exams and skills test","Part 61 and SA-CATS 61, your ATO"],["5","Private pilot licence, from age 17, with a current medical","Part 61, regulations 61.03.1 and 61.04.1"]]},{t:"h2",x:"Book your first aviation medical",id:"book"},{t:"p",x:"ClinoTrend Health & Aviation is in the Main Terminal Building at Grand Central Airport, Gate 2, Office TG6B, in Midrand, between Johannesburg and Pretoria. Dr A.O. Ndhlovu is a SACAA designated aviation medical examiner (Regular DAME, MR 336) and does aviation medicals for pilots and for cabin crew. Opening times: 08h00 to 16h30 Monday to Thursday. Friday 08h00 to 14h30."},{t:"p",x:"[Book a Class 2 medical](/book/?service=class-2) and complete the [SACAA application form](/sacaa-form/) online before you arrive. The [aviation medicals page](/aviation-medicals/) and [what is included in a SACAA aviation medical](/blog/what-is-included-in-a-sacaa-aviation-medical/) explain the visit. Aviation medicals start from R1,500, and we confirm the fee when you book."},{t:"cta",x:"Book a Class 2 medical"}],faq:[{q:"Do I need a medical before my first flying lesson?",a:"You need a valid medical certificate issued under Part 67 before you fly solo on a student pilot licence. Some schools also ask for it earlier. Check with your flight school."},{q:"Which medical class does a new pilot need?",a:"An SPL or PPL for aeroplane, airship or helicopter is listed under Class 2 in regulation 67.00.2. Recreational student licences such as microlight or glider sit under Class 4. A CPL or ATPL needs Class 1, which only a Senior DAME may issue."},{q:"Do I need maths or physical science to become a pilot in South Africa?",a:"Part 61 does not list mathematics, physical science or matric as a requirement for a student or private pilot licence. Individual flight schools may set their own entry rules, so ask the ATO you plan to join."},{q:"How old must I be?",a:"Regulation 61.02.1 says an applicant for a student pilot licence must be 15 years or older. A private pilot licence needs you to be 17 or older (regulations 61.03.1 and 61.04.1)."},{q:"Can I do a Class 1 medical at ClinoTrend?",a:"No. ClinoTrend does not currently issue Class 1 or Class 3. A Class 1 needs a SACAA Senior DAME. Dr Ndhlovu is a Regular DAME and does Class 2 and Class 4 medicals."}],sources:[e.spl,e.classes,i.pplA,i.pplH,i.pplAChecklist,e.validityReg,e.avmed,e.register]},D={slug:"private-pilot-licence-medical-south-africa",title:"PPL Medical Requirements in South Africa | ClinoTrend",h1:"Private pilot licence in South Africa: the medical step",description:"Private pilot licence requirements in South Africa, with the Class 2 medical step: age, hours, exams, what the SACAA medical includes, and how long it lasts.",excerpt:"What a South African private pilot licence requires, with the Class 2 medical as the step you complete with a designated examiner.",keyword:"private pilot license requirements south africa",question:"What medical do you need for a private pilot licence in South Africa?",answer:"A private pilot licence for an aeroplane or helicopter needs a valid medical certificate issued under Part 67. That certificate is Class 2. You must also be 17 or older, hold a restricted radiotelephony certificate, complete training at an approved school, pass the theory exams and pass a skills test. The same Class 2 visit covers student and private pilots.",facts:["Regulation 61.03.1 sets the PPL (aeroplane) requirements, including a minimum age of 17 and a valid Part 67 medical certificate.","Regulation 67.00.2 lists the private pilot licence for aeroplane, airship and helicopter under Class 2.","A PPL (aeroplane) needs not less than 45 hours of aeroplane flight time, including at least 25 hours dual and 15 hours solo, of which at least five hours are cross-country."],secondary:["ppl medical requirements","private pilot medical requirements","medical for pilot license","pilot license medical requirements"],published:"2026-11-26",updated:"2026-11-26",status:"approved",tag:"Licences",body:[{t:"p",x:"A private pilot licence (PPL) lets you fly as pilot-in-command privately, once you meet the Part 61 requirements and hold a current medical certificate. This guide focuses on the medical step for a South African PPL, and summarises the other licence conditions so you can see where the medical fits. For a first medical before solo, start with the [student pilot medical guide](/blog/student-pilot-medical-south-africa/)."},{t:"h2",x:"Which medical does a PPL need?",id:"class"},{t:"p",x:"Regulation 67.00.2 lists the private pilot licence for aeroplane, airship and helicopter under **Class 2**, alongside the student pilot licence. A Regular or Senior Designated Aviation Medical Examiner (DAME) may issue Class 2. Dr Ndhlovu is a Regular DAME, and ClinoTrend issues Class 2 and Class 4 medicals at Grand Central Airport, Midrand."},{t:"p",x:"If you already hold a valid Class 1 certificate, regulation 67.00.2(2) treats a flight crew member with a valid Class 1 as also holding valid Class 2 and Class 4 certificates. You do not need a separate Class 2 in that case. ClinoTrend does not currently issue Class 1. If you are moving toward a commercial licence, see [SACAA Class 1 medical and Senior DAMEs](/blog/sacaa-class-1-medical-senior-dame/)."},{t:"cta",x:"Book a Class 2 medical"},{t:"h2",x:"The other PPL requirements, in brief",id:"licence"},{t:"p",x:"Regulation 61.03.1 says an applicant for a PPL (aeroplane) must:"},{t:"ul",items:["Be **17 years or older**","Hold a **valid medical certificate issued under Part 67**","Hold at least a valid restricted certificate of proficiency in radiotelephony (aeronautical)","Hold a valid student pilot licence, or have held a qualifying licence within the previous 60 months","Complete the prescribed training at an approved Part 141 aviation training organisation","Pass the theoretical knowledge examination and the skills test"]},{t:"p",x:"The SACAA checklist for the initial issue of a PPL (aeroplane) also lists an ICAO language proficiency certificate at a minimum of level 4, and says all eight theory subjects must be passed within 18 months, calculated from the date of the first pass. The skills test must be undergone within 36 months from the date the theoretical knowledge examinations were completed."},{t:"h2",x:"How many hours does a PPL need?",id:"hours"},{t:"p",x:"For a PPL (aeroplane), regulation 61.03.1(2) requires not less than 45 hours of flight time as pilot of an aeroplane with a maximum certificated mass in excess of 450 kg, of which at least 25 hours are dual instruction and at least 15 hours are solo. Of the solo time, at least five hours must be cross-country, including one triangular cross-country flight of at least 150 NM, with at least one point not less than 50 NM from base and full-stop landings at two different aerodromes away from base. A maximum of five hours of dual instruction may be done in an approved aeroplane flight simulation training device."},{t:"p",x:"A [helicopter PPL](/blog/helicopter-pilot-medical-requirements/) uses the same medical class, but the hour minimum is 50 hours and the required solo cross-country triangle is at least 100 NM. Holders of certain other licences may be credited with some hours, as set out in Part 61. Your flight school will apply those credits."},{t:"h2",x:"What happens at the Class 2 medical?",id:"visit"},{t:"p",x:"You complete your medical history on the SACAA application form and sign a declaration that it is accurate, complete and true, as regulation 67.00.7 requires. Complete the form [online before you arrive](/sacaa-form/). The doctor then examines you. At ClinoTrend a resting ECG, vision testing, a hearing test (audiometry) and urine screening are done on site. The examiner will tell you if a chest X-ray or any further test is needed. [What is included in a SACAA aviation medical](/blog/what-is-included-in-a-sacaa-aviation-medical/) and [how to prepare](/blog/how-to-prepare-for-a-sacaa-aviation-medical/) cover the visit in more detail."},{t:"h2",x:"How long is a PPL medical valid?",id:"validity"},{t:"p",x:"The licence is not a substitute for the medical. You may only exercise PPL privileges while the medical certificate is valid and you comply with any endorsements on it. For a Class 2 certificate, regulation 67.00.6(3) sets 60 months if you are less than 40, 24 months after 40, and 12 months after 50, to the last day of the month of issue. [How long a Class 2 medical is valid](/blog/class-2-medical-validity-by-age/) explains the dates, and [how to renew a Class 2 medical](/blog/renew-sacaa-class-2-medical/) covers the renewal visit."},{t:"h2",x:"Book a PPL medical",id:"book"},{t:"p",x:"ClinoTrend Health & Aviation is in the Main Terminal Building at Grand Central Airport, Gate 2, Office TG6B, Midrand. Dr A.O. Ndhlovu does Class 2 and Class 4 medicals for pilots and for cabin crew. Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical, and we confirm the fee when you book. [Book a Class 2 medical](/book/?service=class-2), or start from the [Class 2 medical page](/aviation-medicals/class-2/)."},{t:"cta",x:"Book a Class 2 medical"}],faq:[{q:"Is a PPL medical Class 1 or Class 2?",a:"Class 2. Regulation 67.00.2 lists the private pilot licence for aeroplane, airship and helicopter under Class 2. A valid Class 1 is deemed to cover Class 2, but a PPL does not itself require Class 1."},{q:"How old must I be for a private pilot licence?",a:"Regulation 61.03.1 (aeroplane) and regulation 61.04.1 (helicopter) both say an applicant must be 17 years or older."},{q:"How many hours do I need for a PPL (aeroplane)?",a:"Not less than 45 hours of aeroplane flight time, including at least 25 hours dual instruction and 15 hours solo, of which at least five hours are cross-country, as set out in regulation 61.03.1(2)."},{q:"Can I use my student pilot medical for the PPL?",a:"Yes, if it is a current Class 2 certificate and still within its validity period. You must hold a valid Part 67 medical when you apply for the PPL and whenever you fly under it."},{q:"Does ClinoTrend issue Class 1 medicals for a future CPL?",a:"No. ClinoTrend does not currently issue Class 1 or Class 3. Class 1 is done by a SACAA Senior DAME."}],sources:[i.pplA,i.pplAChecklist,i.pplH,e.classes,e.classesReg,e.application,e.validityReg,e.spl,e.avmed,e.register]},E={slug:"laser-eye-surgery-pilot-medical",title:"Laser Eye Surgery and Your Pilot Medical | ClinoTrend",h1:"Laser eye surgery and your SACAA medical: waiting periods and reports",description:"Waiting periods after LASIK, PRK or radial keratotomy, the reports your examiner needs, and how refractive surgery is handled at a Class 2 or Class 4 medical.",excerpt:"What the SACAA examiner guide says about LASIK, PRK and radial keratotomy: waiting periods, fitness criteria and the follow-up reports you should bring.",keyword:"laser eye surgery pilot",question:"Can you be a pilot in South Africa after laser eye surgery?",answer:"Refractive surgery is not an automatic no. The SACAA examiner guide says you are assessed as unfit after surgery that changes the refractive status of the eye, until you are free from problems that would interfere with safe flying. Named procedures have set waiting periods, and you need ophthalmologist reports before a certificate can be considered.",facts:["The March 2023 DAMEs Guide names radial keratotomy (RK), photorefractive keratectomy (PRK) and LASIK, and sets waiting periods that depend on the procedure and the pre-operative refractive error.","For a pre-operative spherical equivalent up to 10.00 D, the guide lists six months after RK or PRK, and two months after LASIK.","After return to duty, follow-up ophthalmologist reports are listed at six weeks after the procedure, at six months after return to duty, and annually thereafter."],secondary:["laser eye surgery pilot requirements","can pilots have laser eye surgery","can you have lasik and be a pilot","lasik pilot medical south africa"],published:"2026-11-26",updated:"2026-11-26",status:"approved",tag:"Vision",body:[{t:"p",x:"Pilots and cabin crew sometimes ask whether laser eye surgery is compatible with a SACAA medical certificate. The short answer is that it can be, after a waiting period and if the result meets the visual standards, but the certificate is not automatic. This page follows the SACAA Guide for Medical Examiners (DAMEs Guide, revision March 2023). The usual visual standards, including glasses, contact lenses and colour vision, are in [SACAA pilot eyesight and colour vision](/blog/sacaa-pilot-eyesight-colour-vision/)."},{t:"h2",x:"What the visual standard says after surgery",id:"standard"},{t:"p",x:"The DAMEs Guide says applicants who have undergone surgery affecting the refractive status of the eye shall be assessed as unfit unless they are free from those sequelae which are likely to interfere with the safe exercise of their licence and rating privileges. In plain terms, you are not passed on the day of surgery. The examiner looks at the outcome once the eye has recovered."},{t:"p",x:"The guide also warns applicants who are contemplating refractive surgery that the operation might delay a return to aircrew or air traffic control duties and that, if complications occur, it may result in the permanent loss of medical certification. That is a risk statement from the official guide, not a prediction about any one person."},{t:"h2",x:"Waiting periods after RK, PRK and LASIK",id:"waiting"},{t:"p",x:"Section 16.14.5 of the March 2023 DAMEs Guide sets waiting periods during which an applicant is considered medically unfit. The period depends on the procedure and on the pre-operative refractive error, measured as the spherical equivalent."},{t:"table",caption:"Waiting periods in the DAMEs Guide (March 2023), section 16.14.5",head:["Pre-operative refractive error","Radial keratotomy (RK)","PRK","LASIK"],rows:[["Up to 10.00 D spherical equivalent","Six months","Six months","Two months"],["Greater than 10.00 D spherical equivalent","Six months","Six months","Six months"]]},{t:"p",x:"The visual acuity result must meet the visual requirements of technical standard 67.00.3, and the assessment must be based on measurements made by an ophthalmologist. An older summarised protocol table, effective 16 November 2021, used shorter wording: a waiting period of six months, or three months after PRK or LASIK. This article follows the more detailed March 2023 examiner guide. Your examiner applies the current protocol on the day."},{t:"h2",x:"What must be true before you can be considered fit",id:"criteria"},{t:"p",x:"Once the waiting period has passed, the guide says an applicant who is considered for medical certification or recertification after refractive surgery shall meet these criteria:"},{t:"ul",items:["The surgery must have been without complications","The vision must be stable","There must be no corneal haze, and no complaints of glare, halos or ghosting"]},{t:"p",x:"If those criteria are not met, the examiner cannot treat the case as a straightforward clearance. Further reports, a deferral or a decision by the Authority may follow. [What happens if your aviation medical is deferred](/blog/aviation-medical-deferred-what-next/) explains that process."},{t:"h2",x:"Which reports to bring",id:"reports"},{t:"p",x:"The DAMEs Guide lists a post-operative assessment report by an ophthalmologist at these intervals:"},{t:"ul",items:["At six weeks after the procedure","At six months after return to duty","Annually thereafter"]},{t:"p",x:"Bring the operative report, the pre-operative refraction, and every ophthalmologist report you already have. Declare the surgery on the SACAA application form. If you have had a procedure that the written protocol does not name, such as a form of refractive surgery other than RK, PRK or LASIK, tell the examiner and bring the operative notes. The examiner will tell you what is needed."},{t:"h2",x:"Cabin crew and other licence holders",id:"crew"},{t:"p",x:"The refractive-surgery standard sits in the visual requirements used at aviation medicals. Cabin crew, recreational pilots and other Class 4 applicants who have had laser eye surgery should declare it in the same way and bring the same kind of reports. ClinoTrend does Class 2 and Class 4 medicals for pilots and for cabin crew. [Cabin crew eyesight requirements](/blog/cabin-crew-eyesight-requirements/) covers Class 4 vision in more detail."},{t:"h2",x:"Book a medical after laser eye surgery",id:"book"},{t:"p",x:"ClinoTrend Health & Aviation is in the Main Terminal Building at Grand Central Airport, Gate 2, Office TG6B, Midrand. Dr A.O. Ndhlovu is a Regular DAME (MR 336) and issues Class 2 and Class 4 certificates. ClinoTrend does not currently issue Class 1 or Class 3. Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical, and we confirm the fee when you book."},{t:"p",x:"Book only once you are past the waiting period that applies to your procedure, unless you are coming in to discuss timing and the reports you will need. [Book a Class 2 medical](/book/?service=class-2) or a [Class 4 medical](/book/?service=class-4), and complete the [SACAA application form](/sacaa-form/) before you arrive."},{t:"cta",x:"Book a Class 2 or Class 4 medical"}],faq:[{q:"Can I fly as soon as my eyes feel fine after LASIK?",a:"No. The March 2023 DAMEs Guide sets a waiting period during which you are considered medically unfit: two months after LASIK if your pre-operative spherical equivalent was up to 10.00 D, and six months if it was greater than 10.00 D. You also need ophthalmologist measurements that meet the visual standard."},{q:"Is the waiting period the same for PRK and LASIK?",a:"Not always. For a pre-operative spherical equivalent up to 10.00 D, the guide lists six months after PRK and two months after LASIK. If the pre-operative error was greater than 10.00 D, both are listed as six months. Radial keratotomy is listed as six months in both groups."},{q:"What reports do I need after laser eye surgery?",a:"A post-operative ophthalmologist assessment at six weeks after the procedure, at six months after return to duty, and annually thereafter, plus the operative and pre-operative records you already have."},{q:"What if I still have glare or halos?",a:"The guide says there must be no corneal haze and no complaints of glare, halos or ghosting, and that the vision must be stable, before certification or recertification is considered. Tell the examiner, and bring your ophthalmologist reports."},{q:"Does this apply to cabin crew as well as pilots?",a:"Yes. Declare refractive surgery at a Class 2 or Class 4 medical and bring the reports. ClinoTrend does both classes for pilots and for cabin crew."}],sources:[i.damesRefractive,i.protocolsLaser,e.form,e.avmed,e.register]},R={slug:"sleep-apnoea-pilot-medical",title:"Sleep Apnoea and the Pilot Medical | ClinoTrend",h1:"Sleep apnoea and the pilot medical: what the SACAA protocol requires",description:"How obstructive sleep apnoea is handled at a SACAA medical: temporary unfitness, and the reports and CPAP records listed in the official protocol.",excerpt:"What the SACAA obstructive sleep apnoea protocol says about diagnosis, reports, CPAP use and follow-up, for Class 2 and Class 4 medicals.",keyword:"sleep apnea pilot medical",question:"Can you be a pilot in South Africa if you have sleep apnoea?",answer:"A diagnosis of obstructive sleep apnoea does not close the door. The SACAA examiner guide says an applicant shall be declared temporarily medically unfit upon diagnosis, and that first certification is considered case by case. You will need specialist reports and, if you use CPAP, usage records that meet the figures in the protocol.",facts:["The obstructive sleep apnoea protocol in the March 2023 DAMEs Guide applies to applicants for Class 1, 2, 3 and 4 medical certificates, so it covers pilots and cabin crew.","The guide says an applicant shall be declared temporarily medically unfit upon diagnosis, and that an application shall be assessed case by case before initial certification.","Where CPAP is used, the protocol lists use for at least five hours per night and six nights per week, including the sleep period just prior to flight."],secondary:["sleep apnea private pilot license","does sleep apnea disqualify you from being a pilot","sleep apnea pilot","CPAP pilot medical south africa"],published:"2026-11-26",updated:"2026-11-26",status:"approved",tag:"Conditions",body:[{t:"p",x:"Obstructive sleep apnoea (OSA) is a medical condition that can cause daytime sleepiness, so it is treated seriously at an aviation medical. Search results often quote foreign regulators. This page follows the SACAA Guide for Medical Examiners (DAMEs Guide, revision March 2023). It explains the protocol; it does not decide your case. Only the examiner and, where the protocol requires it, the Medical Assessor of the Authority can do that."},{t:"h2",x:"Does sleep apnoea disqualify you from being a pilot?",id:"disqualify"},{t:"p",x:"The protocol does not say that a diagnosis is a permanent bar. It does say that an applicant shall be declared temporarily medically unfit upon diagnosis, and that an application shall be assessed on a case-by-case basis and presented by the Medical Assessor prior to initial certification. In practice, that means you should not expect a certificate on the day a diagnosis is confirmed. Certification is considered once the listed reports are available and treatment, if any, can be reviewed."},{t:"p",x:"The protocol applies to Class 1, 2, 3 and 4 medical certificates. That includes student and private pilots on Class 2, and cabin crew on Class 4. ClinoTrend issues Class 2 and Class 4 only. ClinoTrend does not currently issue Class 1 or Class 3."},{t:"h2",x:"What the protocol lists at first certification",id:"initial"},{t:"p",x:"The guide lists the following as part of the information considered at first certification: symptoms of obstructive sleep apnoea; a body mass index above 40; an Epworth Sleep Score above 10; and a neck circumference above 42 cm for men and 40 cm for women. These are protocol items, not a do-it-yourself diagnosis. If any of them apply to you, declare your symptoms and history honestly on the SACAA form and tell the examiner."},{t:"p",x:"The reports the protocol says an applicant shall submit for consideration of a medical certificate include:"},{t:"ul",items:["A sleep physician report, covering the history of presenting symptoms, the Epworth score, clinical status, and investigations such as a sleep study, a Maintenance of Wakefulness Test or a Sleep Latency Test","A report on the progress and management of the condition from the treating specialist","A review of the Continuous Positive Airway Pressure (CPAP) download, if you use CPAP, including usage statistics","An objective measure of sleep apnoea control (the Apnoea-Hypopnoea Index, or AHI)","A repeat sleep study after weight loss or surgery, or after CPAP is started, as applicable","A clinical psychologist report if clinically indicated"]},{t:"p",x:"You should also report side effects of CPAP or of any surgical procedure to the aviation medical examiner. Bring every report you already have to the appointment. If something is still outstanding, the examiner will tell you what to obtain next. [What happens if your aviation medical is deferred](/blog/aviation-medical-deferred-what-next/) explains a deferred decision."},{t:"cta",x:"Book a Class 2 or Class 4 medical"},{t:"h2",x:"CPAP use, if that is your treatment",id:"cpap"},{t:"p",x:"Where CPAP is used, the protocol is specific. It says CPAP should be utilised for at least five hours per night and for six nights per week, and that it must be used during the sleep period just prior to flight. For follow-up, an applicant is required to submit a copy of the cumulative annual CPAP device report showing actual time used. The target listed in the guide is use for at least 75% of sleep periods and an average minimum of five hours per sleep period."},{t:"p",x:"The protocol also says an applicant will submit a signed Airman Compliance with Treatment form, or equivalent, attesting to the absence of OSA symptoms and continued daily use of prescribed therapy, and a status report from the treating physician indicating that treatment is still effective. If you have had successful surgical treatment, you submit a statement attesting to the continued absence of symptoms."},{t:"h2",x:"Obesity, BMI and sleep studies",id:"bmi"},{t:"p",x:"A separate protocol on obesity, in the same examiner guide, applies to Class 1, 2, 3 and 4 certificates. It says an initial applicant shall be referred for further assessment if his or her BMI is 35 or above, and that a pilot whose BMI exceeds 35 requires investigation within two months. Sleep studies are listed if BMI exceeds 40. That protocol also lists other investigations, including an Epworth score. It sits alongside the sleep apnoea protocol; the examiner will tell you which reports apply in your case."},{t:"h2",x:"Cabin crew",id:"crew"},{t:"p",x:"Because the sleep apnoea protocol applies to Class 4 as well as Class 2, cabin crew members who have been diagnosed with OSA, or who use CPAP, should declare it and bring the same kind of specialist and usage records. See [can you be a flight attendant with a medical condition](/blog/can-you-be-a-flight-attendant-with-a-medical-condition/) for other common health questions, and the [cabin crew medical guide](/blog/cabin-crew-medical-class-4-south-africa/) for the Class 4 visit."},{t:"h2",x:"Book a medical if you have sleep apnoea",id:"book"},{t:"p",x:"ClinoTrend Health & Aviation is in the Main Terminal Building at Grand Central Airport, Gate 2, Office TG6B, Midrand. Dr A.O. Ndhlovu is a Regular DAME (MR 336) and does Class 2 and Class 4 medicals for pilots and for cabin crew. Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical, and we confirm the fee when you book."},{t:"p",x:"If you already have a diagnosis, bring your sleep physician reports, CPAP download if you use one, and any treating-physician letters. [Book a Class 2 medical](/book/?service=class-2) or a [Class 4 medical](/book/?service=class-4), and complete the [SACAA application form](/sacaa-form/) before you arrive. Declare the condition on the form. The examiner decides what happens next against the protocol; this page cannot promise a particular outcome."},{t:"cta",x:"Book a Class 2 or Class 4 medical"}],faq:[{q:"Does sleep apnoea automatically fail a SACAA medical?",a:"No. The March 2023 DAMEs Guide says you are declared temporarily medically unfit upon diagnosis, and that first certification is considered case by case, with listed specialist reports. It does not describe the diagnosis as a permanent bar."},{q:"How many hours of CPAP use does the protocol expect?",a:"It says CPAP should be used for at least five hours per night and six nights per week, including the sleep period just prior to flight. For annual follow-up, the target is use for at least 75% of sleep periods and an average minimum of five hours per sleep period."},{q:"Does the sleep apnoea protocol apply to cabin crew?",a:"Yes. The protocol is written for Class 1, 2, 3 and 4 medical certificates. Cabin crew medicals are issued in Class 4 at ClinoTrend."},{q:"What if my BMI is above 35 but I have not been diagnosed with sleep apnoea?",a:"A separate obesity protocol in the same guide says an initial applicant with a BMI of 35 or above shall be referred for further assessment, and it lists sleep studies if BMI exceeds 40. The examiner will tell you which reports, if any, are needed."},{q:"Can ClinoTrend issue a Class 1 medical if I have sleep apnoea and fly commercially?",a:"No. ClinoTrend does not currently issue Class 1 or Class 3. Class 1 is done by a SACAA Senior DAME. ClinoTrend can do Class 2 and Class 4 medicals."}],sources:[i.damesOsa,e.application,e.duties,e.classes,e.avmed,e.register]},G={slug:"helicopter-pilot-medical-requirements",title:"Helicopter Pilot Medical Requirements | ClinoTrend",h1:"Helicopter private pilot medical: what Class 2 means for you",description:"The SACAA Class 2 medical for a helicopter student or private licence, how the hour minimums differ from an aeroplane PPL, and when Class 1 is needed.",excerpt:"What medical a helicopter student or private pilot needs in South Africa, and when a commercial helicopter licence requires a Class 1 examination elsewhere.",keyword:"helicopter pilot medical requirements",question:"What medical does a helicopter pilot need in South Africa?",answer:"A helicopter student or private pilot licence needs a valid Class 2 medical certificate issued under Part 67. The examination is the same Class 2 visit used for aeroplane student and private pilots. A commercial helicopter licence needs a Class 1 medical, which only a SACAA Senior DAME may issue. ClinoTrend issues Class 2 and Class 4, not Class 1.",facts:["Regulation 67.00.2 lists the student pilot licence and the private pilot licence for helicopter under Class 2.","A PPL (helicopter) applicant must be 17 or older and hold a valid Part 67 medical certificate (regulation 61.04.1).","The hour minimum for a PPL (helicopter) is 50 hours, not the 45 hours that apply to a PPL (aeroplane)."],secondary:["helicopter pilot license medical requirements","helicopter ppl south africa","helicopter licence south africa","helicopter student pilot medical"],published:"2026-11-26",updated:"2026-11-26",status:"approved",tag:"Licences",body:[{t:"p",x:"If you are learning to fly helicopters in South Africa, the medical class is the same one used for aeroplane student and private pilots: Class 2. The licence itself has different hour and cross-country minimums. This guide sets out the medical, the PPL (helicopter) conditions that sit next to it, and what changes if you later train for a commercial helicopter licence."},{t:"h2",x:"Which medical class does a helicopter pilot need?",id:"class"},{t:"p",x:"Regulation 67.00.2 lists the student pilot licence and the private pilot licence for helicopter under **Class 2**. A Regular or Senior DAME may issue that certificate. Dr Ndhlovu is a Regular DAME, so ClinoTrend can do the Class 2 medical for a helicopter SPL or PPL at Grand Central Airport, Midrand. The visit is the same Class 2 examination described for aeroplane pilots: history, physical examination, a resting ECG, vision testing, a hearing test and urine screening, with further tests only if they are indicated. See [what is included in a SACAA aviation medical](/blog/what-is-included-in-a-sacaa-aviation-medical/)."},{t:"p",x:"A **commercial pilot licence for helicopter** sits under **Class 1**, together with an airline transport pilot licence and an instrument rating. Class 1 must be done by a SACAA Senior DAME. ClinoTrend does not currently issue Class 1 or Class 3. When you need that step, use the [Class 1 and Senior DAME guide](/blog/sacaa-class-1-medical-senior-dame/)."},{t:"cta",x:"Book a Class 2 medical"},{t:"h2",x:"Student helicopter pilots",id:"student"},{t:"p",x:"Before you fly solo on a student pilot licence you need a valid medical certificate issued under Part 67. Regulation 61.02.1 says an applicant for an SPL must be 15 years or older, hold that medical, and be registered with an approved training organisation. Book a few weeks before you expect to fly solo. The [student pilot medical guide](/blog/student-pilot-medical-south-africa/) covers the first visit, including what to bring."},{t:"h2",x:"PPL (helicopter) requirements",id:"pplh"},{t:"p",x:"Regulation 61.04.1 says an applicant for a PPL (helicopter) must:"},{t:"ul",items:["Be **17 years or older**","Hold a **valid medical certificate issued under Part 67**","Hold at least a valid restricted certificate of proficiency in radiotelephony (aeronautical)","Hold a valid student pilot licence, or have held a qualifying licence within the previous 60 months","Complete the prescribed training at an approved Part 141 aviation training organisation","Pass the theoretical knowledge examination and the skills test"]},{t:"p",x:"The SACAA requirements form for a PPL (helicopter), dated 26 August 2025, also says all eight theory subjects must be passed within 18 months, calculated from the date of the first pass, and that the final theoretical knowledge examination must have been passed within the 36 months preceding the skills test."},{t:"h2",x:"How the hours differ from an aeroplane PPL",id:"hours"},{t:"p",x:"A PPL (helicopter) needs not less than **50 hours** of flight time as pilot of a helicopter, of which at least 25 hours are dual instruction and at least 15 hours are solo. Of the solo time, five hours must be cross-country, including one triangular cross-country flight of at least **100 NM**, in the course of which full-stop landings at two different aerodromes away from base must have been made. A maximum of five hours of dual instruction may be accumulated in an approved helicopter flight simulation training device."},{t:"p",x:"By comparison, a [PPL (aeroplane)](/blog/private-pilot-licence-medical-south-africa/) needs 45 hours, and its required solo triangle is at least 150 NM. The medical class does not change with those hour figures. Your helicopter school will plan the training; this page only records the regulatory minimums."},{t:"h2",x:"How long is the medical valid?",id:"validity"},{t:"p",x:"Class 2 validity is set in regulation 67.00.6(3) and depends on your age: 60 months if you are less than 40, 24 months after 40, and 12 months after 50, to the last day of the month of issue. You may only exercise helicopter licence privileges while the certificate is valid. [How long a Class 2 medical is valid](/blog/class-2-medical-validity-by-age/) has the detail, and [Class 2 renewal](/blog/renew-sacaa-class-2-medical/) covers the next visit."},{t:"h2",x:"Book a helicopter pilot medical",id:"book"},{t:"p",x:"ClinoTrend Health & Aviation is in the Main Terminal Building at Grand Central Airport, Gate 2, Office TG6B, Midrand, and does Class 2 and Class 4 medicals for pilots and for cabin crew. Helicopter and aeroplane student and private pilots book the same Class 2 appointment. Aviation medicals start from R1,500. Extra tests or reports are added only if the doctor finds they are needed during the medical, and we confirm the fee when you book. [Book a Class 2 medical](/book/?service=class-2), or read the [flight schools page](/flight-schools/) if you are arranging a group."},{t:"cta",x:"Book a Class 2 medical"}],faq:[{q:"Do helicopter pilots need a different medical from aeroplane pilots?",a:"Not at student or private level. Regulation 67.00.2 lists the SPL and the PPL for helicopter under Class 2, the same class as the aeroplane SPL and PPL. The licence hour minimums are different; the medical class is not."},{q:"What medical does a commercial helicopter pilot need?",a:"A commercial pilot licence for helicopter needs a Class 1 medical, which only a SACAA Senior DAME may issue. ClinoTrend does not currently issue Class 1 or Class 3."},{q:"How many hours is a helicopter PPL?",a:"Regulation 61.04.1 requires not less than 50 hours of helicopter flight time, including at least 25 hours dual and 15 hours solo, of which five hours are cross-country, including one triangular flight of at least 100 NM."},{q:"How old must I be for a helicopter PPL?",a:"Regulation 61.04.1 says an applicant must be 17 years or older. A student pilot licence can be issued from 15."},{q:"Can I do my helicopter PPL medical at ClinoTrend?",a:"Yes, if you need Class 2. Dr Ndhlovu is a Regular DAME and issues Class 2 and Class 4 medicals at Grand Central Airport, Midrand."}],sources:[i.pplH,i.pplHChecklist,i.pplA,e.classes,e.spl,e.validityReg,e.avmed,e.register]},B=[s,n,r,l,h,d,c,u,m,p,f,y,g,A,w,C,b,v,x,S,k,T,q,M,P,I,D,E,R,G],L=t=>`/blog/${t.slug}/`,H=[{name:"Home",path:"/"},{name:"Blog",path:"/blog/"}];export{H as B,B as P,e as S,L as p};
